window.__D("text/sefer-hasichot-rayatz/c005",{"p":[[4301600293,"שכל איז אַ קלאָרער פאַרשטאַנד באַזירט אויף אַ גרונטיקן באָדען, דער פאַרשטאַנד ענטהאַלט אַ געשמאַק אַז דער פאַרשטאַנד איז גוט, און דער געשמאַק ווערט פאַרוואַנדלט אין אַ צי (המשכה) און אַ וועהל (געלוסטיגקייט) צו דעם בכן פון דעם פאַרשטאַנד, דער וועהל ווערט אָנגירופען מדות שבשכל, וויילע דאָס איז די התפעלות פון דעם שכל, ווי ער איז נאָך שכל.\nדער געשמאַק און די התפעלות וואָס עס איז אין שכל, איז אַז דאָס קומט אין האַרצען, רעגט דאָס אויף די האַרץ און ער ווערט דערוועקט מיט אַ מדה, וואָס די מדה איז נאָך דעם אינהאַלט פון דעם שכל.\nשכל איז מחייב מדות, און מדות האָבן אַ געבורטס אָנהויב ווער עס בריינגט זיי אין לעבן, חכמה ובינה זיינען דער פאָטער און מוטער פון די מדות חסד וגבורה תפארת כו' און אהבה ויראה זיינען די קינדער פון חכמה ובינה<sup data-n=\"790\">87</sup>.\nיעדער מדה חסד אָדער גבורה, אהבה אָדער יראה און אַזוי די איבעריקע מדות האָבען עלטערן, ווער עס האָט זיי געבראַכט אין לעבן, ווי אין גשמיות, קינדער האָבן עלטערן, עלטערן בריינגען קינדער, וואָס דאָס איז דער יתרון פון אדם על בעלי חיים, די מדות וואָס זיינען על פי השכל.\nכה. אַז איינער לייגט אַריין זיין שכל צו דענקען און קלערן, אין דעם זין און צוועק פון דעם מענטשליכן זיין אויף דער וועלט, צו וואָס איז דער מענטש בעשאַפן געוואָרן, וואָס פאַר אַ מעגליכקייטן גייסטליכע (כחות רוחנים) און קערפערליכע (כחות גשמים) השי\"ת האָט איהם געגעבן, וואָס ער קאָן שאַפן מיט זיינע כחות, און צו וואָס ער קאָן צוקומען, און צו וואָס ער קאָן דעם אַנדערן צובריינגען.\nאיז אַז דער מענטש טראַכט אין דעם מיט אַ גוטער טיפער איבערלייגונג, זוכט צו פאַרשטיין די מענטשהייט און זיין ריכטיקן הפכים'דיקן גרונד, אחור וקדם'דיק<sup data-n=\"791\">88</sup> מעגליכקייט, קומט ער צו, צו דער איבערצייגונג אַז דער מענש איז דער איינצעלטער נברא וואָס זאָל בעזיצן, גייסט און קראַפט, גוטס און שלעכטס, און פערשידענע הפכים אין איין קערפּער.\nבנים אתם לה' אלקיכם<sup data-n=\"792\">89</sup>, אפילו דער גאַנץ געוויינליכער וואָכעדיגקער איד מיט זיין וואָכעדיגקן לעבן, איז אַז ער פיהרט זיין לעבן אין אַלע צווייגן לויט די פעראָרדענונג פון תורה (תורה איז לערונג תורה לערנט ווי צו פיהרן זיך<sup data-n=\"793\">90</sup>, די הויז געזינד די געשעפט דעם געזעלשאַפטליכן לעבן), איז ער אַ בן לאבינו שבשמים.\nמענטשהייט איז שכל, און מדות וואָס זיינען עפ\"י השכל, וואָס דאָס איז דער יתרון פון אַ מענטש אויף בעלי חיים, השי\"ת האָט אין דעם גופא געשאָנקען לעמו ישראל דעם גרעסטען יתרון, און געגעבן די מתנה פון תורה און מצות.\nאון אַז דער מענטש נעמט דעם",[["790","87","ראה תניא פ\"ג. ובכ\"מ."],["791","88","ע\"פ תהלים קלט, ה. וראה אוה\"ת (יהל אור) עה\"פ (ע' תקיט ואילך. ע' תשמז ואילך). ובכ\"מ."],["792","89","ראה יד, א."],["793","90","ראה זח\"ג נג, ב. רד\"ק לתהלים יט, ח. ספר השרשים להרד\"ק ערך ירה."]]],[4301600294,"ריכטיקן בעטראַכט אין דער נעימות פון דרכי התורה והמצוה, און פאַרטראַכט זיך אין דער טיפעניש פון די קלאָר ריינע געבאָרענע נשמה געפילן וואָס באַ אידן אין פאַראַן, דער אידישער אומבאַגרעניצט פייאיקער שכל, די אידישע אייביק ברענענדיקע האַרץ.\nאון ווי געזאָגט השכלה און השגה, זיינען פאָטער און מוטער וואָס בריינגען מדות, עס איז פאַראַן אַ השכלה והשגה וואָס שאַפן די מדת האהבה, און עס איז פאַראַן אַ השכלה והשגה וואָס בריינגען די מדת היראה, און אַזוי בשארי המדות.\nאהבה הייסט, אַ המשכה צו דעם גוט וואָס ער האָט פאַרשטאַנען און געפילט אין זיין שכל, ווען בא איהם ווערט אָט די המשכה (דער ציה צו דער גוטער זאַך וואָס ער האָט פאַרשטאַנען) ווערט איהם זעהר געשמאַק און עס לאָזט אין איהם איבער אַ געוויסן רושם אין מדות און הנהגות טובות, און מדת היראה ווירקט אויף איהם מואס זיין ברע.\nכו. שכל אלקי איז אויך מוגדר אין דריי הגדרות כללים, ווי געזאָגט שכל אלקי איז די געטליכקייט וואָס איז מצומצם אַז אַ נברא זאָל דאָס קאָנען פאַרשטיין, ווי דער מאמר<sup data-n=\"794\">91</sup>, דברה תורה כלשון בני אדם.\nהגדר הא' פון שכל אלקי איז, אָט דאָס וואָס ער איז מוגבל, דאָס הייסט אַז הגם זיין פאַרשטאַנד איז דאָך פאַרנומען אין פאַרשטיין אלקות וואָס אלקות איז דאָך בלי גבול, און כמה הפכים בנושא אחד מכל מקום איז שכל אלקי אַ מוגבל וואָס פאַרשטייט, באַנעמט, חלקים פון בלי גבול.\nדער פאַרשטאַנד פון שכל אלקי איז פאַרקערט פון שכל אנושי, שכל אנושי קאָן פאַרשטיין נאָר דאַן ווען די זאַך איז באַגרעניצט, ווי געזאָגט אַז פריהער איז ער מגביל און נאָכדעם פאַרשטייט ער, און שכל אלקי איז ניט נאָר וואָס ער באַגרעניצט ניט פריער די זאַך וואָס ער פאַרשטייט, נאָר ער בעווייזט אַז נאָך דעם ווי די זאַך איז שוין פאַרשטאַנדיק איז דאָס יעמולט אויך בלי גבול.\nלמשל, שכל אלקי בעווייזט ריין קלאָהר פאַרשטאַנדיק, ווי אתה מחי' את כולם<sup data-n=\"795\">92</sup>, ביז ער דערפיהרט צו דעם קלאָהרן בעוואוסטזיין אַז אין<sup data-n=\"796\">93</sup> עוד מלבדו ית', און אין דער זלעבער רגע גופא ערקלערט ער ווי דאָס איז העכער ווי השגה, און בריינגט די ראי' פון חיות הנפש וואָס איז מחי' דעם גוף, וואָס די אַלע איינצעלהייטן פון דעם משל איז באַ דעם מענשן ניט נאָר אַ פאַרשטאַנד נאָר אַ געפיל, ער פיהלט דאָס בעשיינפּערליך וואָס עס קאָן אין דעם ניט זיין קיין צווייפעל.\nוואָס דאָס איז דאָך וואָס עס שטייט<sup data-n=\"797\">94</sup> מבשרי אחזה אלוקה, דער מענטש, איז פון דעם אייגענעם קערפּער זעהט ער געטליכקייט, וכמאמר הידוע<sup data-n=\"798\">95</sup> מה הנשמה ממלא את הגוף כך הקב\"ה ממלא את העולם, וואָס פון די אַלע פרטי אופני החיות ווי דער נפש איז מחי' דעם גוף, פאַרשטייט מען דעם אופן החיות ווי דער בורא ברוך הוא איז מחי' דעם עולם.\nוואָס דאָס איז דאָך דער ענין התפלה,",[["794","91","ברכות לא, ב. רמב\"ם הל' יסוה\"ת פ\"א ה\"ט. שם הי\"ב."],["795","92","נחמי' ט, ו."],["796","93","ואתחנן ד, לה."],["797","94","איוב יט, כו."],["798","95","מדרש תהלים קג, א. וראה לקו\"ת אמור לא, ב. ובכ\"מ."]]],[4301600295,"וואָס אין פסוקי דזמרה ווערט אויסגירעכנט דער סדר ואופן הבריאה יש מאין ברוך שאמר והי' העולם, אַז באמירה נבראו כל העולמות וכל הנבראים, עיני כל אליך ישברו ואתה נותן להם את אכלם בעתו<sup data-n=\"799\">96</sup>, און נאָכדעם ווערט אויסגירעכנט די אַלע פרטי הנבראים און דעם אופן החיות זייערער, וואָס די התהוות הנבראים און דער קיום זייערער איז נאָהר אלקות ווי דער ענין פון בריאה יש מאין און ואתה מחי' את כולם, ווערט גוט אַרומגירעט אין חסידות בארוכה.\nכז. איז טראָצדעם וואָס אַזאַ ערקלערונג און פאַרשטאַנד בריינגט דעם מענשן אין אַ שיינער קלוגער וועלט, וואו דער מענש ווערט פאַרנומען מיט זיך אַליין, מיט זיין נשמה, ווערט בא איהם ערוועקט אינוועניקסטע כחות, עס עפענען זיך שליסל קוועלען פון פאַרשטאַנדן וואָס זיינען אַרום געוויקלט מיט פאַרגיניגן (תענוג) געפילן.\nעס איז אַ מעין עולם הבא לעבן, די גמרא זאָגט אין ב\"מ (דפ\"ג ע\"ב), העוה\"ז דומה ללילה, בו תרמוש כל חיתו יער<sup data-n=\"800\">97</sup> אלו רשעים שדומין לחי' רעה, ואל מעונתם ירבצון<sup data-n=\"801\">98</sup> אלו הצדיקים אַז יעדער צדיק האָט לעולם הבא אַ מדור (וואָהנונג) לפי כבודו, כל אחד ואחד המוכן לו, רש\"י.\nדער עולם הבא לעבן, איז אַ לעבן פון ליכט און קלאָרקייט. אַלעס זעהט זיך אין זיין ריכטיקער געשטאַלט, מי זעהט דעם אמת'ן פערגעניגען פון גוט, און די אמת'ע יסורים פון שלעכט.\nשכל אלקי בעלייכט און בעווייזט דעם דו פּרצופין<sup data-n=\"802\">99</sup> וואָס השי\"ת האָט דעם מענשן געגעבן, פון איין זייט די חי' רעה וואָס אין דעם מענשן אין פאַראַן, און פון דער צווייטער זייט דעם צדיק גמור וואָס דער מענטש בעזיצט און ערקלערט ווי דער מענטש האָט די בחירה אויסקלייבן ווי ער וויל.\nשכל אלקי איז ווי געזאָגט, אויך אַ מוגבל, אָבער די הגבלה זיינע איז מער ניט ווי אין דעם וואָס פון השכלה ווערט אַ געוויסער געשמאַק לויט דעם השכלה און פאַרשטאַנד וואָס ער איז איבערגעגעבן.\nעס איז פאַראַן אַ השכלה והשגה פאָטער און מוטער וואָס בריינגט אַ אהבה והמשכה להשי\"ת, און עס איז פאַראַן אַ השכלה והשגה וואָס בריינגט אַ יראה ופחד ה' מהדר גאונו<sup data-n=\"803\">100</sup>.\nיעדער פאַרשטאַנד איז דער אויסנאַם זיינער ווערט פאָרמירט אין אַ געשמאַק, און דער געשמאַק פערוואַנדעלט זיך ענטווידער אין אַ כוסף ותשוקה אָדער אין אַ יראה ופחד.\nווי עס זאָל ניט זיין, דאָס הייסט אין וואָס פאַר אַ מדה דער געשמאַק ווערט ניט פאַרוואַנדעלט, צי אין אַ מדה פון אהבה, צי אין אַ מדה פון יראה, איז דאָס גאַנץ אנדערש ווי אין שכל אנושי.\nכח. דער גדר הב' פון שכל אלקי איז חיות. ווי געזאָגט דער אונטערשייד פון שכל אנושי און שכל אלקי איז אין דעם, אַז שכל אנושי איז שכל הנקנה און שכל אלקי איז אַ שכל עצמי במילא איז דער",[["799","96","תהלים קמה, טו."],["800","97","שם קד, כ."],["801","98","שם, כב."],["802","99","ראה ברכות סא, א."],["803","100","ישעי' ב, כא."]]],[4301600296,"גדר החיות פון שכל אלקי, אַ חיות עצמי.\nשכל הנקנה איז דער פאַרשטאַנד נאָר אין און פון די אַרומיקע זאַכן, אָבער שכל עצמי איז דער פאַרשטאַנד אין און פון דעם עצם המושכל און מושג אַליין, דייטליכער אַרויסזאָגן — דאָס — שכל הנקנה איז דער פאַרשטאַנד איז נאָר אין און פון דער הגבלה וואָס אין דעם מושכל און מושג איז, דאָס הייסט, ער גיט צו פאַרשטיין דאָס וואָס עס איז פאַראַן.\nאָבער שכל אלקי איז דער פאַרשטאַנד אין דעם בלי גבול וואָס אין דעם מושכל ומושג איז, דאָס הייסט אַז ער גיט צו פאַרשטיין די נשמה וואָס עס איז פאַראַן אין יעדער זאַך, און ווי דאָס איז דער עיקר, ובמילא מובן אַז ער גיט צו ערקלערן דאָס וואָס מי זעהט ניט.\nבמילא איז דער געשמאַק גאָר אַ אַנדערער, און עס זעהט זיך אָן אין דעם אויסגאָס פון דעם געשמאַק אַז אין שכל אנושי ווערט טאַקע אַ רייץ אין האַרצן, וואָס דערפון ווערט אַ מדה, אָבער דאָס איז אַ בעזונדערע זאַך פון איהם, עס רירט ניט אָן דעם גאַנצן עצם זיינעם, משא\"כ דער אויסגאָס פון דעם געשמאַק וואָס אין שכל אלקי, ווערט ער אינגאַנצען אַרומגענומען אין דעם, אַז עס איז תתלהב ותתלהט נפשו, ער ברענט און פלאַקערט אין אַ קירוב והמשכה פון אהבה, אָדער ער טרייסט זיך און פלאַטערט אין אַ ריחוק און שרעק פון יראה.\nדער רושם וואָס בלייבט נאָך דעם איז אַ טיפע צובראָכענקייט און בענקעניש, און בדרך ממילא איז אַלע זיינע מדות בין אדם לחבירו, און די הנהגות זעהר ריינע און גוטע.\nכט. דער גדר השלישי פון שכל אלקי איז, אַז ער איז אמת לאמתו<sup data-n=\"804\">101</sup>, ער איז דאָך אַ עצמי, און אַ עצמי בייט זעך ניט, ער איז אומעטום און אַלע מאָהל ווי און וואָס ער איז.\nאין שכל אלקי איז אויך פאַראַן סברות פון חיוב ושלילה, אָבער דער חיוב און שלילה פון שכל אלקי זיינען ניט קיין הפכים, אין שכל אנושי זיינען איינע פון די ביידע הטיות אַ ליגן, אין שכל אלקי זיינען חיוב ושלילה ביידע אמת, עס זיינען צוויי שטראַלן פון איין מקור וואָס די ביידע בעלייכטען אויף צו פאַרשטיין אַ טייל פון דעם וואָס מי פיהלט.\nחסידות איז שכל אלקי געטליכער שכל, אַ חקירה אלקית וואָס ווירקט אויף דעם קערפּערליכן לעבן, דאָס הייסט, אַז חכמת החסידות מאַכט פון דער חי' רעה וואָס אין דעם מענשן איז, אַ אדם השכלי, און אין דעם אדם השכלי פאַרשטאַרקט זי און ענטוויקלט דעם צדיק וואָס באַ דעם מענשן איז פאַראַן.\nחסידות האָט דריי גדרים: א) חיות (לעבעדיגקייט). ב) אור (קלאָהר, און ליכטיג). ג) אמת. דאָס הייסט, חסידות איז אַ אמת'ע קלאָהרע לעבעדיגקייט.\nאון מיט דעם שכל פון חסידות, וואָס רבינו הגדול ואחריו רבותינו הק' נ\"ע האָבען אונז געגעבן, דאַרפן מיר פאַרשטיין און פיהלן די שאלה וואָס רבינו הבעש\"ט נ\"ע, האָט געפרעגט באַ משיח'ן<sup data-n=\"805\">102</sup>, און דערהערן דעם ענטפער וואָס משיח האָט געענטפערט.",[["804","101","ראה לעיל סעיף ד (ע' 89)."],["805","102","ראה לעיל סעיף א (ע' 84)."]]],[4301600297,"ל. דער בעש\"ט נ\"ע פרעגט באַ משיח'ן אימתי קאתי מר, אין פלוג האָט דאָך קיין אָרט ניט די שאלה עס איז דאָך אַ קלאָר אָפענע גמרא (סנהדרין דצ\"ח ע\"א) ר' יהושע בן לוי האָט זעך געטראָפען מיט אלי' הנביא אין דער מערה פון ר' שמעון בן יוחאי פרעגט ריב\"ל בא אליהו'ן ווען וועט קומען משיח, ענטפערט אלי' ר' יהושע בן לוי'ן, גיי פרעג באַ איהם אַליין, פרעגט ריב\"ל וואו קאָן איך איהם טרעפן, האָט איהם אלי' געזאָגט דעם אָרט אין גן עדן, וואו משיח זיצט.\nווי עס איז ניכר איז באַ ריב\"ל דער אָרט געווען גוט בעקאַנט און די וועג אַהין אַדורך גיטראָטענע, אַז ער איז געקומען אַהין איז נאָך די סימנים וואָס אליהו האָט איהם גיגעבן האָט ער דערקענט ווער איז משיח, פרעגט ריב\"ל באַ משיח'ן לאימת אתי מר, צו וואָס פאַר אַ צייט וועט קומען דער האַר, ענטפערט משיח, היום היינט.\nריב\"ל איז גיווען זייער צופרידן מיט דעם ענטפער איז געגאַנגען צוריק זעהן זיך מיט אליהו'ן דערווייל איז דורך געגאַנגען דער טאָג, און משיח איז ניט געקומען, איז ריב\"ל געוואָרן פאַרביטערט, אַז ער איז געקומען צו אליהו'ן, פרעגט איהם אליהו וואָס האָט דיר משיח געזאָגט.\nריב\"ל זייענדיק זייער פאַרביטערט און פאַר עגמת נפש פון דעם וואָס משיח איז ניט געקומען דעם טאָג, זאָגט ער אליהו'ן אַז משיח האָט איהם געענט­פערט היום קומט ער, דער טאָג איז דורך און משיח איז ניט געקומען.\nאלהיו הנביא ערלקערט ר' יהושע בן לוי דעם ריכטיקן זין פון משיח'ס ענטפער — אויף ריב\"ל פראַגע צו וואָס פאַר אַ צייט וועט קומען דער האַר — היום אם בקולו תשמעו<sup data-n=\"806\">103</sup>.\nאין דעם סיפור המעשה פון ריב\"ל מיט אליהו'ן זעהן מיר קלאָהר און דייטלעך אַז דער זין פון ביאת המשיח (בב\"א) איז פאַרבונדען מיט דעם היום אם בקולו של הקב\"ה תשמעו. וואָס נאָך דעם קלאָהרן ענטפער איז דאָך ניט מובן די שאלה פון בעש\"ט אימתי קאתי מר, עס איז דאָך אַ גמרא מפורשת, אַז ביום אשר בקולו של הקב\"ה תשמעו, קומט משיח גואל צדק, היינט וואָס פרעגט דער בעש\"ט נ\"ע אימתי קאתי מר.\nלא. מורנו הבעש\"ט נ\"ע איז דער משה רבינו ע\"ה פון תורת החסידות הכללית, דאָס הייסט אַז אַזוי ווי משה רבינו ע\"ה דער בחיר הוי', אַז על ידו איז נתגלה געוואָרען תורתנו הקדושה, אָט אַזוי איז מורנו הבעש\"ט נ\"ע דער בחיר הוי' אַז על ידו איז נתגלה תורת החסידות הכללית.\nאין מדרש<sup data-n=\"807\">104</sup> אויפן פסוק<sup data-n=\"808\">105</sup> ומשה הי' רועה שטייט הוי' צדיק יבחן<sup data-n=\"809\">106</sup>, ובמה הוא בוחנו במרעה צאן, און רז\"ל<sup data-n=\"807\">104</sup> דערציילען אונז די מעשה וואָס עס האָט געטראָפען בא משה רבינו ע\"ה בעת ער האָט גיפיטערט צאן יתרו, וואָס פון דער מעשה זעהט מען אַרויס די מדות טובות וואָס משה רבינו ע\"ה האָט געהאַט.\nמורנו הבעש\"ט נ\"ע איז בעוואוסט מיט זיין אהבת ישראל, ער האָט געזעהן אין יעדער אידן אַ מעלה און אין יעדער פועל פון אַ אידן, הן אַ מצוה אָדער אַ",[["806","103","תהלים צה, ז."],["807","104","שמו\"ר פ\"ב, ב."],["808","105","שמות ג, א."],["809","106","תהלים יא, ה."],["807","104","שמו\"ר פ\"ב, ב."]]],[4301600298,"מדה טובה, האָט ער געזעהן דעם אמת'ן ליכטיקען שיין.\nמורנו הבעש\"ט קוקט מיט זיינע ליכטיקע אויגן אין דעם פינסטערן גלות, זעהט ווי אידן זיינען מקיים תורה און מצות מיט גרויס מסירות נפש און פּיין, ווערן געדריקט און גערודפ'ט פון פערשידענע שלעכטע מענשן.\nמורנו הבעש\"ט זעהט ווי אידן זיינען מקיים דעם בקולו של הקב\"ה תשמעו מיט מס\"נ, ווערט באַ איהם די שאלה פאַר וואָס קומט ניט משיח, גואל צדק און וויל בעשליסן אַז ער מיט דער חבריא קדישא, הצדיקים הנסתרים נ\"ע זאָלן בריינגען משיח'ן.\nעס איז בעוואוסט די פערשידענע אסיפות הצדיקים הנסתרים וואָס זיינען געווען מזמן לזמן בימי מורנו הבעש\"ט, און די כמה מיני התעסקות און שתדלנות וואָס זיי פלעגן טאָהן בנוגע דער מצב הרוחני און אויך דעם מצב הגשמי פאַר דעם כלל ישראל.\nאון אין יענער צייט איז געווען די עליית הנשמה של מורנו הבעש\"ט וואָס ער איז געווען אין היכל המשיח און האָט געפרעגט אימתי קאתי מר.\nלב. דער אימתי וואָס דער בעש\"ט נ\"ע פרעגט באַ משיח'ן, איז דאָס ווי דער מאמר אם לא עכשיו אימתי וואָס עס שטייט אין אבות (פ\"א מי\"ד).\nדאָס הייסט, אַז דער בעש\"ט רעדט מיט משיח'ן, אין דעם ענין פון דער גמרא סנהדרין, וואו משיח ענטפערט אַז היום אם בקולו של הקב\"ה תשמעו, און אויף דעם פרעגט דער בעש\"ט עס איז דאָך ב\"ה בקולו תשמעו.\nאון אויף דערויף ענטפערט משיח דעם בעש\"ט לכשיפוצו מעיינותיך חוצה, ברחבות פלגי מים (משלי ה' ט\"ז). יפוצו מעיינותיך חוצה, סוף שתקנה תלמידים ותורה הוראות ברבים, ויצא לך שם, רש\"י, ברחבות, עיר תפוצנה פלגי מימיך, רש\"י.\nחסידות<sup data-n=\"811\">107</sup> ווייס צו מאַכן אַ חילוק פון אַ מעין און נהר, נהר הוא התפשטות לאורך ורוחב ומחזיק שטח גדול, והמים בו בריבוי והילוכם הוא בשפע ורעש גדול, והמעין הוא נמשך כגיד בכיווץ תפיסת מקום שאינו תופס מקום גם לעצמו, ומימיו נובעין טיפּין טיפּין.\nחוצה<sup data-n=\"812\">108</sup> הייסט דאָך אין דרויסען. ד.ה. ניט אין דעם מקום המוכשר<sup data-n=\"813\">109</sup>, וואָרום דער מקום המוכשר איז דאָך ניט קיין חוצה, ער איז דאָך דער ריכטיגער מקום המוכשר, וואָדען אויב ער איז אַ חוצה, דאָס הייסט אַז ער איז ניט קיין מקום המוכשר איז ווי איז דאָרטן דער אָרט פון אַ מעין, איז דאָך דער פסוק זעהר ניט פאַרשטאַנדיק, עס איז דאָך סותר איינע די אַנדערע, איז דאָס אַ מעין פאַרוואָס רופט מען דאָס חוצה? איז דאָס חוצה, ווי קומט אַהין אַ מעין, וואָדען, עס איז ביידע זאַכן, איז ווי איז ביידע זאַכן<sup data-n=\"814\">110</sup>?\nמפרשים<sup data-n=\"815\">111</sup> טייטשן דעם פסוק יפוצו מעיינותיך חוצה, עס וועלן אַזוי שטאַרק זיין די וואָס קומען אַרויס פון דיינע קוועלן אַז זיי וועלן זיך צו שפּרייטן אפילו חוצה ביז אַז ברחבות אפילו אין",[["811","107","ראה לקו\"ת שה\"ש לט, א ואילך. ובכ\"מ."],["812","108","ראה ספר השיחות תורת שלום ע' 113."],["813","109","ראה לקוטי שיחות חלק טו ע' 287. וראה שם ע' 282. ועוד."],["814","110","הביאור — ראה לקמן סעיף נג (ע' 130)."],["815","111","ראה ראב\"ע ומצו\"ד עה\"פ."]]],[4301600299,"די גאַסן וועלן זיין פלגי מים, און חאָטש עס וועט זיין חוצה גאָר אין דרויסען, פונדעסטוועגן וועט מען וויסן אַז דאָס קומט פון דיינע מעיינות.\nפון משיח'ס ענטפער אויף דעם בעש\"ט פראַגע פאַרשטעהט מען, אַז תורת רבינו הבעש\"ט נ\"ע, און די התגלות שכל אלקי, וואָס דער בעש\"ט ותלמידיו ותלמידי תלמידיו אבותינו רבותינו הק' נ\"ע זי\"ע האָבן אונז געגעבן, האָט דאָס אַ שייכות צו ביאת המשיח (יבא בב\"א).\nלג. יעדער חכמה, אויך די חכמה פון שכל אלקי, האָט איהר שטייגער בסדר ואופן השכלתה והשגתה על פי דער הבנה און הסברה פון חסידות, איז דער יחס און שייכות פון אַ זאַך צו נאָך אַ זאַך, כמו אָט ווי דאָ, די שייכות פון תורת הבעש\"ט נ\"ע און ביאת המשיח, מוז איין זאַך זיין אַ אור, און די צווייטע זאַך אַ כלי צו דעם אור. אין אור וכלי איז דאָך פון דער כלי קאָן מען פאַרשטעהן וואָס איז דער אור וואָס ער איז שייכות צו דער כלי און פון דעם אור קאָן מען פאַרשטעהן וואָס פאַר אַ כלי מ'דאַרף האָבן צו אַזאַ אור, וואָרום אור וכלי האָבען דאָך אַ שייכות זה לזה.\nפאַרשטיין קאָנען מיר דאָס פון דעם וואָס מיר זעהען במוחש באור וחיות הנפש ואברי הגוף שהם אור וכלי, הרי אברי הגוף הם לפי ערך כחות הנפש, וגילוי הכחות הם לפי אופן הכלים שהם האברים, דכללות האדם נחלק בב' בחינות כוללים, מוחין ומדות, ובפרטי' נחלק לג' חלקים כוללים, מוחין ומדות ומחדו\"מ, ובפרטיות יותר לרמ\"ח אברים ושס\"ה גידים, אשר כשם שהוא מתחלק באברי הגוף, כן הוא גם באברי הנפש שהם כחות.\nוהנה במוחין אנו רואים שנחלקים לג' חלקים הנקראים חב\"ד שהם ג' מוחין וכמאמר<sup data-n=\"816\">112</sup> תלת חללין אינון דכל חלל וחלל שבראש, הוא כמו חדר וקופסא, אשר בו מונח מוח פרטי, מוח החכמה, מוח הבינה ומוח הדעת, דכל אחד מהם הוא כלי פרטי לחלק א' מכח השכל, והיינו דכשם שהמוח שבראש מתחלק לג' מוחות פרטים שהם ג' כלים פרטים, כן כח השכל שהוא האור של המוח שבראש הוא ג\"כ מתחלק לג' כוחות פרטים כח החכמה, כח הבינה וכח הדעת.\nוכה גדלה התיחסותם של הכלים (הם המוחות) אל האורות (הם הכחות) עד כי מן מזיגת המוח, שהוא הכלי, והרכבתו, אנו יודעים את גדרי האור, וכן מן גודל בהירות האור ואופן פעולתו, אנו מבינים להעריך ערך מעלת הכלי וענינה.\nולזאת הנה מוח החכמה הוא קר ולח, הוא כלי לכח החכמה שהוא נקודה, ובדביקות דוקא, דטבע הנקודה להתעלם אבל נקודת החכ' היא מאירה, ורק דוקא בכלי החכמה שהוא קר ולח, ומוח הבינה דמזיגתו והרכבתו הוא חם ויבש זהו כלי אל כח הבינה שהוא לפרט ולברר כל דבר בריבוי סברות, ומוח הדעת שהוא מורכב מעין מזיגה בלולה משניהם, הוא כלי אל כח הדעת, שהוא העמקות וההתקשרות בכל דבר השכלה והשגה.\nלד. והנה הג' חילוקים דחכמה ובינה ודעת, הגם שזהו ענין שכלי, ושכל עמוק מאד, ומ\"מ אנו יודעים זאת מן הגשמיות, היינו מהחיים הגשמיים, אין וועלט זעהן מיר אַז מענשען ריידען אויף דעם לשון, דער איז אַ חכם, אויף דעם צווייטען",[["816","112","ראה זח\"ג (אד\"ר) קלו, א. וראה סה\"מ ה'שי\"ת ע' 257. ע' 282."]]],[4301600300,"זאָגט מען דער איז אַ מבין, און דער איז אַ דעת'ן, זעהן מיר דאָך אַז אפילו אין דעם פּשוט'ן שכל אנושי'דיקן לעבען, הערט זיך אויך אָן, און עס פיהלט זיך, חילוקים אין שכל, דער טעם הדבר איז וויילע אור וכלי זיינען איינער בערך דעם אַנדערן, איז דערפאַר קאָן מען פון איינעם פאַרשטיין דעם אַנדערן.\nאין משיח'ס ענטפער וואָס ער ענטפערט אויף דער פראַגע פון מורנו הבעש\"ט נ\"ע אימתי קאתי מר, לכשיפוצו מעיינותיך חוצה, איז קלאָהר פאַרשטאַנדיג, אַז תורת הבעש\"ט נ\"ע איז דאָס די כלי צו דעם אור פון גילוי המשיח, בב\"א.\nעס איז אַ כלל ידוע אַז לבד זאת וואָס כל התהוות איז דורך אור<sup data-n=\"817\">113</sup>, איז התהוות הכלים ע\"י האור<sup data-n=\"818\">114</sup>, דער אור מאַכט די כלי, און כלי איז מקבל דעם אור ווי מיר זעהען במוחש אין שכל אַז דער שכל איז מהווה אותיות, יעדער שכל האָט זיך זיינע אותיות, וואָס דער שכל איז דער אור און די אותיות זיינען די כלים.\nאיז בכדי מיר זאָהלן פאַרשטיין וואָס איז חסידות, דאַרפען מיר פריהער פאַרשטיין וואָס איז דער אור וגילוי פון משיח, ווי געזאָגט אַז פון דעם מהות מעלת האור, קאָנען מיר נאָכדעם פאַרשטיין דעם תוכן ענין פון דעם כלי צו דעם אור.\nוויסן אַ זאַך איז, אַז מי ווייס זיין מהות, דאָס הייסט מה הוא, וואָס איז ער, דער אמת'ער מיין אין דער שאלה מה הוא, איז אַ רוחניות'דיקע פראַגע, וואָס איז ער מכיל, דאָס הייסט וואָס ענטהאַלט ער אין זיך.\nאָבער דער מהות הרוחני איז אַ עצמי, וואָס דער גראָבער קערפער מיט זיינע געוויינהייטן קאָן דאָס ניט בעגרייפן, ער קאָן מער ניט ווי נאָך­פאָלגן אין אַ קליינעם בעגרעניצטן אופן, די פיהרונג און ווירקונגען פון דעם עצמי, וואָס דאָס קאָן איהם אין אַ געוויסען זין מאַכן נעהנטער צו בעגרייפען, לכל הפחות, די אַלגעמיינע שטריכן פון דעם עצמי.\nלה. אויף דעם אדם זאָגן מיר מהות אדם, איז די מציאות זיינע ווייס מען, אַז עס איז אַ גוף מיט נפש ווי אַלע בעשעפענישן, נאָר ער האָט דעם יתרון פון שכל, וואָס דער שכל פיהרט אָן מיט די אַלע אברים פון דעם גוף, אַז יעדער פון זיי זאָהל ריכטיג דורכפיהרן זיין אויפגאַבע.\nדער שכל איז דער נשיא המנהיג פון דער גאַנצער אברים געזעלשאַפט, ער שטעלט צוזאַמען זייערע אַרבעט אויף אויסצופיהרן געוויסע זאַכן וואָס געהערן צו זיי אַליין, און צו דעם גייסט און קערפּער פון דעם פּערזאָן אַליין, און אויך פון זאַכן וואָס זיינען מחוץ דעם פּערזאָן פון דעם מענשען, הן בנוגע נאָך אַ יחיד אָדער אַ רבים.\nאיז אַז מיר זאָגן מהות האדם, בעצייכענט דאָס, אַ עצמי וואָס האָט אַ געוויסע ווירקונגס קראַפט אין פּערזענלעכן און אין אַלגעמיינעם וועלט לעבען.\nקלערער געזאָגט, אַז דער מהות הדבר, דאָס הייסט דער מהות המהות פון מהות האדם ווייסן מיר ניט, נאָר דעם מציאות המהות פון מהות אדם",[["817","113","ראה אגה\"ק ס\"כ (קל, ב). וראה סה\"מ שבהערה הבאה. ובכ\"מ."],["818","114","עץ חיים שער העקודים פ\"ג. סה\"מ עת\"ר ע' לג. תרפ\"ט ע' 256. ה'שי\"ת ע' 66. ובכ\"מ."]]],[4301600301,"ווייסן מיר, וואָס דאָס ווייסן מיר פון זיינע פּעולות און הנהגות.\nדי ידיעה אין אַ מהות עצמי, וואָס מי ווייס דאָס פון די פּעולות און הנהגות, הגם דאָס איז ניט קיין ידיעה אמיתית, אָבער דאָס איז שוין אַרויס פון העדר הידיעה, און עס איז שוין אַ קליין טיהרעלע צו ידיעה.\nמשיח איז אַ אור עצמי, מיר נבראים שוכני בתי חומר<sup data-n=\"819\">115</sup>, און ווער רעדט די וואָס פיהלן זיך ניט אַלעס שכנים, נאָר טאַקע איינגעוואַקסענע בעלי חומר, זיינען קליין צו בעגרייפען וואָס איז אור בכלל, און אור עצמי בפרט, איז מובן וויפל מיר זיינען ווייט פון הבנה וואָס משיח איז, נאָר פון דער הנהגה און פּעולה קאָנען מיר האָבן עפּעס אַ קצת ידיעה, וואָס איז דער ענין המשיח.\nלו. אויף דעם ענין פון משיח געפינען מיר אין פסוק, וואָס ער זאָגט אונז, וואָס איז זיין מהות, און ווי איז זיינע הנהגות און פּעולות, ווי געזאָגט אַז משיח איז אור, איז אַז מיר וועלן פאַרשטיין דעם מהות האור, און דעם אופן ההנהגה והפעולה של האור וועלן מיר אויך פאַרשטיין דעם מהות הכלי, דאָס הייסט חסידות, וואָס דאָס איז די כלי פון גילוי אור המשיח.\nמיר ווייסן אַז חסידות איז שכל אלקי, און מיר ווייסן אויך אַז שכל אלקי איז אָפּגעטיילט אין זיינע גדרים<sup data-n=\"820\">116</sup>, פון די גדרים פון שכל אנושי<sup data-n=\"821\">117</sup>, אָבער וואָס איז דער מהות פון שכל אלקי ווייסען מיר ניט, אָבער אַז מיר וועלן פאַרשטיין דעם מהות האור, במילא וועלען מיר פאַרשטיין וואָס איז דער מהות הכלי און ווי עס איז דער אופן ההנהגה און פעולה פון דער כלי.\nאויף משיח'ן שטייט<sup data-n=\"822\">118</sup>, ונחה עליו רוח הוי' רוח חכמה ובינה, רוח עצה וגבורה, רוח דעת ויראת ד', והריחו ביראת ד' ולא למראה עיניו ישפוט ולא למשמע אזניו יוכיח, ושפט בצדק דלים והוכיח במישור לענוי ארץ [גו'], והי' צדק אזור מתניו והאמונה אזור חלציו. אין די פיר פסוקים זאָגט אונז דער אויבערשטער ב\"ה, וואָס איז דער מהות פון משיח'ן, און ווי איז זיין הנהגה און פּעולה.\nדער מהות פון משיח'ן איז אַז, ונחה עליו רוח הוי' רוח חכמה ובינה רוח עצה וגבורה רוח דעת ויראת ד', דאָס וואָס ער זאָגט אַז ונחה עליו רוח הוי' דאָס פאַרנעמט אונזער שכל און פאַרשטייט וואָס דאָס איז, הוי' איז דאָך הי' הוה ויהי' כאחד<sup data-n=\"823\">119</sup>, למעלה מן הטבע, העכער ווי נאַטור, נאַטור איז דאָך איינגעטיילט אין עבר הוה ועתיד, משיח איז העכער ווי די זאַך פון נאַטור, למעלה מן הטבע.\nאָבער אַז ער הויבט שוין אָן רעכענען פרטים, חכמה בינה, עצה וגבורה, דעת ויראת ד', דאָס איז דאָך אַלץ זאַכן וואָס זיי זיינען מהותים פרטים, וואָס יעדער מהות פון זיי איז מוגדר אין אַ גדר פרטי פון זיין מהות, וואָס ווען אפילו אַז אין געוויסע זאַכן האָבן זיי אַ איינשלוס און זאגאר אַ ווירקונג איינער אויף דעם",[["819","115","איוב ד, יט."],["820","116","ראה לעיל סעיף כד. כו ואילך (ע' 106 ואילך. 108 ואילך)."],["821","117","ראה לעיל סעיף כג (ע' 105 ואילך)."],["822","118","ישעי' יא, ב­ה."],["823","119","זוהר ח\"ג רנז, סע\"ב. פרדס שער א (שער עשר ולא תשע) פ\"ט. שעהיוה\"א פ\"ז."]]],[4301600302,"צווייטן, אָבער אויך זיינען זיי הפכים איינע פון די אַנדערע.\nלז. די כחות חכמה און בינה, האָבן אַ געוויסן עקזיסטענץ איינשלוס, און אַ ווירקונגס און איינפלוס קראַפט איינער אויף דער צווייטער, און אין איין און דער זעלבער צייט זיינען זיי הפכים.\nחכמה איז נקודה, אַ ברק המבריק, אַ שכל בליץ. בינה איז התפשטות, התיישבות בעטראַכטונג און איבער­לייגונג. דערפאַר איז חכמה מעין און בינה איז נהר<sup data-n=\"824\">120</sup>, אַ נהר איז ריבוי המים און מיט אַ שטראָם און אַ מעיין איז טיפין טיפין, עס קאָן ניט זיין קיין נהר וואו ער האָט ניט קיין מעיין, און פון מעיין ווערט נהר.\nדאָס גלייכן אין דער שכל וועלט, קאָן ניט זיין קיין פאַרשטאַנד וואו עס זאָל ניט זיין דער חכמה פונקט (נקודת החכמה) וואָס צו פאַרשטיין, און פון יעדער חכמה פונקט ענטוויקלט זיך אַ פאַרשטאַנד טייך.\nנקודה און התפשטות זיינען הפכים בעצם מהותם, דאָס הייסט אַ חוץ דעם וואָס יעדער פון זיי האָט זיך זיינע הגדרות, וואָס די הגדרה איז נאָר זיינע אַליין, איז אין זיי פאַראַן אַ צד התנגדות און אַ פאַרקערט פון דעם אַנדערן.\nחכמה און בינה זיינען ביידע שכל, שכל אַליין הגם דאָס איז ניט דער אמת'ער רוחני, אָבער לגבי גשמי וחומרי איז ער רוחני שבגשמי. איז אין חכמה און בינה אַליין אונז שווער צו בעצייכענען זייער התנגדות און הפכים, זעהען מיר דאָס אויספיהרליך און קלאָר אין זייערע כלים, דאָס הייסט אין די מוחות, דער מוח החכמה איז קר ולח און דער מוח הבינה איז חם ויבש.\nמוח איז דער מאַרך, די פעטס און די זאַפט פון דער גאַנצער זאַך, דאָס הייסט אַז דאָס איז דער גאַנצער תוך, דער גאַנצער מהות המהות פון דער זאַך.\nמוח איז גשמי, נאָר עס איז אַ גשמי וואָס איז די כלי פון אַ רוחני, דעם מהות המהות פון דעם מוח ווען ער איז אַ כלי צו דעם רוחני פון שכלי, קאָן מען ניט פעסטשטעלן, ווען ער איז אין דער אַרבעט קאָן מען איהם בעטראַכטן און מבקר זיין (אויספאָרשן) און, ר\"ל, בצאת הנפש מן הגוף, פעלט זיך דער מהות המהות זיינער, און עס בלייבט מער ניט ווי דער מציאות המציאות.\nאיז פון וואָס קאָנען מיר וויסן דעם מהות המציאות פון דעם מוח, דורך דער ידיעה פון מציאות המציאות פון שכל, די ידיעה פון מציאות המציאות פון שכל זיינען די אותיות השכל, וואָס זיי זאָגן אונז צוויי זאַכן, דעם מציאות המציאות פון שכל, און דעם מהות המציאות פון מוח.\nאותיות פון חכמה זיינען קורץ און האָבן אַ קלעפּ. און דאָס גיט אונז אַ אַלגעמיינעם בעגריף אויף דעם שכל החכמה, אַז ער איז אַ נקודה מיט אַ בליץ, און עס דייט אונז אָן, אויף דעם מוח החכמה אַז ער איז קר ולח.\nאותיות פון בינה זיינען בהבנה והסבר, וואָס דאָס בעטאָנט אונז אַז דער שכל הבינה איז דאָס אַ התפשטות און אַ ערקלערונג אויף אַ זאַך, און בעצייכנט אַז דער מוח הבינה איז חם ויבש.\nוואָס פון דעם אַלעם זעהען מיר דאָך, אַז חכמה ובינה האָבען אויך צדדי ההתנגדות וההפכים איינער פונם",[["824","120","לקו\"ת שבהערה 107. ובכ\"מ."]]],[4301600303,"אַנדערן, איז ווי זאָגט דער פסוק, רוח חכמה ובינה און איז זיי כולל אינ­איינעם, ער האָט לכל הפחות געדאַרפט זאָגן רוח חכמה ורוח בינה, פאַנאַנדער­טיילן זיי, און מ'זאָגט דאָס אינאיינעם.\nלח. רוח עצה וגבורה, עצה איז דער טייטש ראַט, ישוב הדעת, וואָס דאָס נעמט אַרום די אַלע דריי אָפּטיילונגען וואָס אין שכל, קלוגשאַפט פאַרשטאַנד, טיעפזיניקייט, דאָס הייסט אַ אויס­פיהרונג פון אַ זאַך ווי זי ווערט בעאַרבעט פון די אַלע דריי שכל קוועלן.\nעס איז געוויס אַ גרויסער חילוק אין וואָס פאַר אַ זאַך די עצה איז, צי אין אַ גייסטיקע זאַך, צי אין אַ קערפּערליכע זאַך, אָבער אין אַלע פאַלן איז די זאַך פון עצה איז אַ ראַט דורך אַ טיפן שכל, ווי איינער פרעגט באַ דעם צווייטען אַן עצה ער זאָל אים געבן אַ גוטן ראַט און אַ שכל'דיגן אויסוועג.\nגבורה איז דער טייטש קראַפט, מאַכט, עס איז געוויס אַ גרויסער חילוק מיט וואָס די קראַפט און די מאַכט איז באַזירט, עס איז דאָ דער שכל­קראַפט און מאַכט, ווי די גמרא זאָגט (סנהדרין דצ\"ג ע\"ב) גבור שיודע להשיב, און עס איז דאָ אַ זרוע גבור, אַלענפאַלס איז גבורה בעדייט שטאַרקייט וואָס עצה און גבורה זיינען צוטיילט אין זייערע גדרים. גדר העצה איז חכמה ושכל, און גדר הגבורה איז תוקף און שטאָלץ.\nרוח דעת ויראת ד', דעה איז טיפע קלוגשאַפט און פאַרשטאַנד, אַז יעדער זאַך וואָס ער טוט איז דאָס שטאַרק טיף, גרונטיק אַרום געטראַכט, און יראת הוי' איז תמימות'דיגע יראת שמים, אַז ער טוט נאָר וואָס דער אויבערשטער ב\"ה הייסט, און וויל ניט אַריינגיין אין קיינע פּשרות, און אין קיינע השכלה'דיגע ערקלערונגען, ער איז אַ ירא אלקים, און וויל ניט וויסען קיינע חכמות פון קולות, דאָס הייסט ער איז זיך מוסר נפש אויף מקיים זיין אָט דאָס וואָס עס שטעהט אין שולחן ערוך, און דעת איז קלוג, און עס איז אַ מאמר העולם, אַז קלוג איז ניט פרום, און לדאבון לבבנו, זעהען מיר דאָך דאָס אין לעבן, אַז די אַלע חכמות איז ווי אַרומגעהען דעם יראת שמים.\nאָבער אויף משיח'ן זאָגט דער פסוק ונחה עליו רוח הוי' רוח חכמה ובינה וגו', איז דער מיין און בעגריף פון דעם פסוק איז, אַז דער מהות פון משיח'ן איז אויך די זאַכן פון חכמה ובינה, עצה וגבורה דעת ויראת ה', נאָר די אַלע זאַכן איז באַ משיח'ן אַנדערש ווי באַ אונז.\nבאַ אונז איז חכמה ובינה צוויי בעזונדערע זאַכן, אויך עצה וגבורה און דעת ויראת ה' זענען געטיילט, און באַ משיח'ן איז חכמה ובינה אין איינעם, עצה וגבורה אין איינעם, דעת ויראת הוי' אין איינעם. וויילע דאָס איז דאָך די זאַך, פון העכער ווי נאַטור, אַז דאָס שליסט איין צוויי הפכים, וויילע ביידע נעמען זיך פון איין מקור און זיינען בגילוי ווי זיי זיינען במקורם.\nלט. די הנהגה פון משיח'ן איז, והריחו ביראת הוי' ולא למראה עיניו ישפוט ולא למשמע אזניו יוכיח, דער משפט זיינער וועט זיין, ניט נאָר לויט דעם וואָס ער וועט זעהען מיט די אויגען, און דער מוסר זיינער וועט זיין ניט נאָר לויט דעם וואָס ער וועט הערן מיט די אויערן, נאָר וואָס דען וועט זיין דער משפט פון משיח'ן און ווי וועט זיין דער מוסר זיינער? אויף דעם זאָגט דער"],[4301600304,"פסוק ווייטער, ושפט בצדק דלים והוכיח במישור לענוי ארץ.\nדי זאַך איז זעהר וואונדערליך, ער וועט ניט משפט'ן נאָכדעם וואָס ער וועט זעהען מיט זיינע אויגען, און ער וועט ניט מוסר'ן נאָכדעם ווי ער וועט הערן מיט זיינע אויערן, נאָר ער וועט משפט'ן מיט גערעכט די אָרעמע און וועט מוסר'ן די וואָס זיינען ביי זיך געפאַלן.\nאון דאָס איז די הנהגה פון משיח'ן, אַ הנהגה פון העכער ווי נאַטור.\nדער דין ומשפט פון בני אדם איז נאָר וואָס בעיניו יראה און באזניו ישמע, איינער אַז ער משפט דעם צווייטען הן ווען דאָס איז אַ משפט גלוי ברבים און הן ווען דאָס איז אַ משפט וואָס ער משפט דעם צווייטען ביי זיך אין האַרצען, איז די יסודות פון דעם משפט און די יסודות פון דעם מוסר, איז מעהר ניט נאָכדעם, נאָך וואָס ער זעהט מיט די אויגען און הערט מיט די אויערן. ער געהט ניט אַריין אין דעם לעבן פון דעם וועלכן ער משפט. ער רעכנט זיך ניט מיט זיין אומשטאַנד און מיט דעם וואָס רינגלט אים אַרום, דאָס הייסט, ער געהט ניט אַריין אין זיין אינערליכן לעבען און פאַרטיפט זיך ניט אין די סיבות וואָס האָבען איהם געבראַכט צו אַזאַ לעבן. ער משפט איהם מעהר ניט נאָכדעם וואָס ער זעהט און הערט, און ניט נאָכדעם וואָס יענער, דעם וואָס ער משפט לעבט דורך.\nאַזאַ משפט איז ניט קיין אמת'ער משפט, אַזאַ משפט איז זעהר אַ טרוקענער, געבויט אויף זעהר גרינגע יסודות. דער אמת'ער משפט איז, אַז דער וואָס משפט דעם צווייטען דאַרף זיך אַליין שטעלען אויף דעם אָרט פון דעם וואָס ער משפט, ער דאַרף און מוז וויסן די אַלע סבות וואָס האָבען יענעם געבראַכט צו אַזאַ צושטאַנד<sup data-n=\"825\">*120</sup>.\nדי גרויסע הלל'ס אזהרה<sup data-n=\"826\">121</sup>, אל תדין את חברך עד שתגיע למקומו, אַז דו האָסט געזעהן אַז איינער איז דורכגעפאַלען, וואָס ער האָט ניט געקאָנט ביישטיין אַ נסיון, זאָלסטו איהם ניט פאראורטיילען ביז דו וועסט אַליין ניט דורכמאַכן אַזאַ זאַך, די גרויסע אזהרה איז אַ מאמר השם.\nמשפט'ן קאָן מען נאָר דאַמאָלט, ווען מ'שטעלט זיך אַנידער אויף יענעמ'ס אָרט, און מ'לעבט עס דורך.\nמ. די וועלט קוקט אויף אַ משפט ווי אויף אַ עונש, אַ שטראָף. דאָס איז ניט ריכטיג. אַ משפט איז ניט נאָר אַ עונש און אַ שטראָף, אַ משפט איז אַ געוויסע לעהרנונג ווי אַזוי מ'דאַרף זיך פיהרען, אַז ס'זאָל נישט צוקומען צו אַזאַ שלעכטע פיהרונג אין לעבען, אַז מ'זאָל איהם נאָכדעם דאַרפען משפט'ן און דאָס קאָן נאָר זיין דאַמאָלסט ווען דער וואָס משפט ווייס די סבות, וואָס האָבען מיטגעבראַכט דעם שלעכטען לעבען, די שלעכטע פיהרונג.\nעס פרעגט זיך זעהר אַ גרויסע קשיא, וואָס איז די סיבה וואָס אַ איד קומט גאָר צו דעם ער זאָל עובר זיין אויף די דרכי התורה והמצוה, תורה איז אַזאַ שעהנע קלאָרע לעהרנונג ווי דער מענטש זאָל זיך פיהרען אין די שענסטע וועגען פון לעבען אין אַלע זאַכען, הן אין דעם גייסט לעבען און הן אין פאַמיליען און געזעלשאַפטלעכן לעבען, איז ווי און פון וואַנען נעמט זיך דאָס אַז",[["825","*120","ראה ד\"ה והניף ידו וד\"ה ויאמר לו יהונתן תשי\"א (סה\"מ תשי\"א­תשי\"ג ע' 41. ע' 46)."],["826","121","אבות פ\"ב מ\"ד."]]],[4301600305,"דער איד זאָל אויף דעם קענען עובר זיין?\nדי סיבה אויף דעם איז דער יצה\"ר. ער רעדט איין דעם מענטש'ן און פיהרט איהם אַראָפּ פון דער ריכטיגער שעהנער וועג, ווי די גמרא זאָגט אין שבת (דק\"ה ע\"ב) כך הוא אומנתו של יצה\"ר, היום אומר לו עשה כך, עד שאומר לו עבוד עבודה זרה, והולך ועובד.\nדער יצה\"ר איז אַ אומן, ער איז אַ פאַכמאַן אין זיין זאַך. דער יצה\"ר קומט ניט צום ערשטען מאָל זאָגן דעם מענטש'ן, אַז ער זאָל ניט לייגן קיין תפילין, אָדער ניט היטען טהרת המשפחה, אָדער עסן טרפה און מחלל שבת זיין, ניין, אַזעלכע זאַכען טוהט ער ניט צום ערשטען מאָל, דאָס איז אַ צו גראָבע אַרבעט, ער — דער יצה\"ר — ווייס גאַנץ גוט, אַז ער וועט קומען צו אַ אידן זאָגען איהם אַז ער זאָל ניט לייגען קיין תפילין, מחלל שבת זיין וכו' וועט דער איד — איהם — דעם יצה\"ר — געוויס ניט פאָלגען.\nדער יצה\"ר איז אַ אומן, אַ קינסטלער אויף קאָנען צוגיין צו יעדער מענשן לויט זיין מהות און זיין מצב, און די ערשטע אַרבעט פון דעם יצה\"ר איז אַריינצונעהמען דעם מענטשען אין האַנט, אין זיין רשות, אַז דער מענטש זאָל איהם אין אַלעס פאָלגן.\nמא. די קונסט פון דעם יצה\"ר איז, וואָס ער האָט פאַר יעדער סוג מענטש אַ שפראַך ווי צוצוגיין צו יעדערן, און געפינט וועגן ווי אַזוי אַריינצובעקומען דעם מענטשן אין זיין רשות<sup data-n=\"827\">122</sup>.\nווי נעמט אַריין דער יצה\"ר דעם מענטשן און ווי ווערט דער יצה\"ר אויף דעם מענטשן אַ בעל דעה און אַ פיהרער? אָט אין דעם באַשטייט די אומנות פון דעם יצה\"ר און זיין פעהיגקייט — קענען אויף יעדערן ווירקען.\nדער ערשטער צוטריט פון דעם יצה\"ר צו דעם מענטשן איז מיט דברים המותרים, דער יצה\"ר רעדט איין דעם מענטשן אַז ער זאָל זיך נאָכגעבן אין אַלץ וואָס מ'מאָג על פי התורה, אין עסען און טרינקען און פאַרשידענע פאַרגעניגענס, ביז ער ווירקט אויף דעם מענטשן אַז ער ווערט צולאָזן, דער יצה\"ר פיהרט אַריין דעם מענטשן אין די וועלטן פון פאַרגעניגען און תאוות מאַכט איהם אַ צעלאָזענע האַרץ אויף וועלען נאָכגעבען זיך, וואָס מיט דעם עפענט ער אויף דעם מענטשן אַ טיהר אין דער פאַרברעכער וועלט, אין וועלט פון עבירות פון פאַרברעכעריי, ביז דער מענטש הויבט זיך אָן רחמנא לצלן, צו גליטשען פון די טרעפּ און פאַלט אַריין אין גאַנצען אין רשות פון דעם יצר הרע, וואָס וועבט שוין אַרום דעם געפאַנגענעם בעל תאוה'דיגען מענטשן מיט פאָדים פון פאַרברעכעריי, אַז ער פאַרלירט שוין גאָר דער מענשליכען שכל'דיגען באָדען, און ער ווערט פאַרענדערט אין בהמות'דיגען קערפּער­ליכען לעבען אַז נמשל כבהמות נדמו<sup data-n=\"828\">123</sup>.\nאון אַזוי אַרום עפענט זיך אויף פאַר דעם זינדיגען בעל תאוה אַן אָפּגרונט פון שאול תחתית, אַז ער ווערט ווי אַ חי' רעה און ווערט שוין פאַרדאָרבען אין אַלע זיינע מדות (זיטען), אַז ער ווערט אַ",[["827","122","ראה גם סה\"מ תרפ\"ט ע' 124 ואילך."],["828","123","תהלים מט, יג. שם, כא."]]],[4301600306,"גנב, אַ גזלן, אַ רוצח, אַלץ צוליב דעם ער זאָל קענען לעבען אַ קערפּערליכען פאַרגעניגען לעבען.\nטויזנטער מענטשן בעלי תאוות און בעלי הנאה ווייסן אַז מיט זייערע שלעכטע געפערליכע תאוות ציהען זיי אויף זיך די שווערסטע שטראָפן, און דאָך קאָנען זיי זיך ניט העלפען, וויילע דער יצה\"ר האַלט זיי אין זיין רשות, ר\"ל.\nמב. וואָס זיינען די ערשטע טרעפּ צו דעם טייוועלשען פּאַלאַץ? וואָס איז די ערשטע סבה צו דעם ביטערען פינסטערן סוף פון דעם בעל תאוה'דיגען מענטשן? ווער איז דער מלאך המות פון דער שענסטער באַשעפעניש, פון דעם מענטשען?\nדי ערשטע טרעפּ פון דער גרויסער ביטערער ירידה, איז דער נאָכגעבן זיך אין וואָס מ'מאָג, דער זוכן דעם פאַרגעניגען נאָר אין גשמיות, פאַרגרעבט דעם מענטשן און ברענגט איהם דערצו, אַז דער פליישיגער קערפּערליכער לעבען ווערט באַ דעם מענטשן אָן אַ וואָג און אָן אַ מאָס, און עס ברענגט איהם צו פערשידענע פאַרברעכענס.\nדי משנה זאָגט (סנהדרין פ\"ח מ\"ה) בן סורר ומורה נדון על שם סופו, אַ בן סורר ומורה ווערט געמשפט מיט טויט שטראָף (מיט אַ געוויסע אויספאָרשונג צי איז ער ריכטיג אַ בן סורר ומורה, און אין אַ געוויסען סדר, וואָס פריער צום ערשטען מאָל משפט מען איהם מיט קליינע שטראָפן, צום צווייטען מאָל מיט אַ גרעסערע שטראָף, פריהער מעהר ניט ווי אַ בית דין פון דריי דיינים, נאָכדעם פון אַ בית דין פון דריי און צוואַנציג דיינים<sup data-n=\"829\">124</sup>) פאַר דעם וואָס וועט זיין. דאָס הייסט, כאָטש איצטער איז ער נאָך ניט אַזוי שלעכט, נאָר וויבאַלד אַז ער פיהרט זיך אויף אַ שלעכטן וועג, וועט ער דאָך, סוף כל סוף, ווערן אינגאַנצן פאַרדאָרבן, משפט מען איהם איצטער אויף דעם וואָס ער וועט זיין.\nוואָס איז דער חטא פון אַ בן סורר ומורה? ער פאָלגט ניט די לעהרנונג און גוטע ערציהונג פון פאָטער און מוטער און איז אַ זולל וסובא, זולל איז דער טייטש אַ פאַרשווענדער, סובא איז דער טייטש זויפען, דאָס הייסט, אַ פאַר­שווענדער אויף פרעסען און זויפען.\nדער אבן עזרא<sup data-n=\"830\">125</sup> זאָגט אַז אַ זולל וסובא דאָס איז אַן אַלגעמיינער נאָמען פאַר די וואָס גיבען זיך אָפּ צו קערפּערליכע פאַרגעניגענס, און זוכט אין יעדער זאַך דעם תאוה'דיגען פאַרגעניגען.\nדער מענטש וואָס ער איז אַ זולל וסובא, איז ער אַ בן סורר ומורה, סורר איז דער טייטש קעהרט אָפּ פון וועג<sup data-n=\"831\">126</sup>, מורה איז דער טייטש ווידערזעצליך זיין, אַז דער וואָס איז אַ זולל וסובא געהט אַראָפּ פון דעם ריכטיגען וועג.\nדער חטא פון אַ זולל וסובא איז, אַז ער עסט אויף אַ געוויסע וואָג פלייש און טרינקט אויס אַ געוויסע מאָס וויין<sup data-n=\"832\">127</sup>, פרעגט זיך דאָך אַ גרויסע קשיא, צי איבער דעם וואָס אַ מענטש עסט מעהרער אַ שטיק פלייש און טרינקט מעהרער אַ ביסעל וויין, איז",[["829","124","סנהדרין עא, סע\"א."],["830","125","תצא כא, יח."],["831","126","פרש\"י תצא שם."],["832","127","סנהדרין ע, א."]]],[4301600307,"דערפאַר ווערט ער אַזוי שטרענג באַשטראָפט?\nנאָר דער וואָס לערנט דעם דין אין זיין מקור, בש\"ס ופוסקים, זעהט ער<sup data-n=\"833\">128</sup>, אַז נישט פאַר דעם גרעסערן שטיק פלייש וואָס ער עסט אָדער פאַר דעם מעהרער ביסל וויין וואָס ער טרינקט, ווערט ער ביטער געשטראָפט. ניין, די שטראָף איז פאַר דעם וואָס ער לאָזט זיך אין דעם אַריין, פאַר דעם וואָס ער זוכט פאַרגעניגן נאָר אין דעם, פאַר דעם וואָס ער עפענט אַ טיהר צו טיפע פינסטערע אָפּגרונטען, פאַר דעם וואָס ער איז מחלל די שיינקייט פון מענטשהייט, פאַר דעם וואָס ענדליך וועט ער ווערען אַ גנב, אַ גזלן, אַ רוצח, און וועט נאָך מענטשן פאַרפיהרען.\nמג. אַזוי איז דער דרך היצה\"ר, ער נעמט אַריין דעם מענשען אין זיין רשות, דורך תאוות היתר, דאָס הייסט וואָס ער רעדט איין דעם מענשן צו זוכן פאַרגעניגען אין די זאַכען וואָס מ'מאָג, און אַזוי מאַכט ער דעם מענשן צעלאָזן, ביז וואַנען דער מענש פאַרלירט די מענשליכע שכל'דיגע שטאַרקייט, אַז ער קומט צו אַ זאַך וואָס מ'טאָר ניט, קאָן ער זיך שוין ניט אָפּהאַלטען.\nדער יצה\"ר מאַכט דעם שטאַרקען, טיפזיניקען מענשן פאַר אַ קל הדעת (לייכט­זיניקן) און אַזוי פיהרט ער דעם מענטשן אַ טרעפּ נידעריגער און נידעריגער ביז ער פאַרלירט די מענשליכע געפיהלען צום צווייטען מענש, ער ווערט איבערגעגעבען אינגאַנצען צו זיינע פאַרגעניגענס און ווערט אַזוי פאַרדאָרבען, ביז דער מענטש ווערט געפערליכער פאַר דער גרעסטער ווילדער חי'.\nעס איז פאַראַן מענשען וואָס זיינען געפאַלען קרבנות פון דעם יצר הרע'ס איינריידען, אַזעלכע וואָס",[["833","128","ראה סנהדרין עב, א. חינוך מצוה רמח. ועוד."]]],[4301600308,"זיי קענען לערנען און ווייסען אַז דאָס וואָס זיי ווילן טאָן, אָדער זיי טוהען טאָר מען ניט, און דערפון וואָס זיי טוהען דאָס וואָס מ'טאָר ניט, איז זיי ניט גוט אויפן האַרצען, און עס איינגט זיי, אָבער זיי זענען אַזוי שוואַך געוואָרען אין זייער דעה, און זיינען אַזוי נעבעך נידער געפאַלען אין די שמוציגע וועלטן און פאַרפּלאָנטערט מיט די פעדים פון קערפּערליכען און פליישיגען פאַרגעניגען, אַז זיי האָבען אין זיך ניט די מענטשליכע שטאָלץ, די ריכטיגע שטאַרקייט אויף אַרויסרייסען זיך פון דעם גרויסען, ברייטען עולם הזה'דיגען טייך פון פאַרגעניגען, און דער טומעל פון דער וועלט און דער רעש פון די פאַלשע רייכטימער פאַרבלענדעט זיי און פאַרטומלט זיי אינגאַנצען, אַז וועלנדיג ניט וועלנדיג, ווערען זיי פאַרשלעפּט אין דעם גרויסען שטראָם פון ים החיים אָהן אַ רעכענונג און אָהן אַ באָדען פון אמת און יושר.\nמד. וואָס איך זאָג די פאַלשע רייכטימער איז דאָס אויף אַ יסוד פון אַ סיפור וואָס עס האָט פּאַסירט באַ דעם זיידען כ\"ק מוהר\"ש.\nאין ליובאַוויטש אויף די ירידים פלעגען קומען פיהל גרויסע סוחרים, צווישען זיי זיינען געווען שקלאָווער און מינסקער סוחרים פון מתנגדישער אָפּשטאַמונג.\nדי גרעסטע סוחרים פלעגן אַריינגיין צום זיידען, געווען אַזלעכע וואָס פלעגען ריידן אין לערנען, און אַזעלכע וואָס פלעגן פרעגן געשעפטליכע עצות.\nאיינער פון די גרויסע סוחרים איז געווען אַ גביר און אַ למדן, ער האָט פאַרבראַכט ביי דעם זיידן אַ גאַנץ היפּשע צייט, און האָט גערעדט וועגען זיינע געשעפטען. איידער ער איז אַוועקגעגאַנגען פרעגט ער דעם זיידען, פאַר וואָס איז, אַז עס גייט צו אים — צום זיידען — אַריין אַ אָרימאַן, ענטפערט ער איהם גלייך אָפּ, און עס דויערט אַ פּאָר מינוט, און אַז עס גייט אַריין אַ גביר גידויערט צייט ביז ער — דער זיידע — ענטפערט איהם.\nהאָט איהם דער זיידע געענטפערט, אַז עס גייט אַריין אַ אָרימאַן, דערציילט ער דעם מצב זיינעם אין איך ענטפער אים גלייך אָפּ, אָבער אַז עס גייט אַריין אַ גביר און הויבט אָן דערציילן וואָס מיט אים טוט זיך, גייט אַוועק די צייט ביז ער זאָגט אַרויס דעם אמת, אַז ער — דער דרויסענדיגער גביר — איז אַ אָרימאַן.\nדאָ אין אמעריקע זענען פאַראַן אפילו דרויסנ'דיקע גבירים, מען איז צעטראָגען און מען איילט גאָר ווי די גרויסע גבירים, השי\"ת זאָל זיי העלפען אַז ביי זיי זאָל זיין תוכם כברם, דער אינעווייניק ווי דער דרויסען — אַז זיי זאָלען זיין אמתע גבירים.\nמה. אָבער די אידישע פּינטעלע, דער זיק היהדות ווערט ניט פאַרטרונקען און פאַרלאָשען.\nדי נקודה ליגט טיף אין דער אידישער האַרץ, דאָס איז די געוויסע בושה וואָס יעדער איד שעהמט זיך פאַר זיך אַליין, און דערפאַר איז פאַראַן מענטשן וואָס זיי באַרוהיגען זיך אַליין מיט פּוסטע היתרים און נאַרישע תירוצים.\nדי גוטע זאַך אין די היתרים און תירוצים איז, אַז דאָס איז אַ באַווייז, אַז זייער ניט גוטער אויפפיהרונג אַרט זיי, אַז דאָס דריקט זיי, נאָר זיי זיינען נעבאַך זעהר שוואַך אין שכל'דיגע שטאַרקייט אויף אַרויס פון זייער געוואוינהייט, אָבער דער תוך זייערער איז נאָך גאַנץ, און אין אַ גוטער סביבה קאָן ער האָבן די בעסטע ווירקונג.\nדער רחמנות פון די מענטשן איז זייער גרויס, זיי האָבען אַן אינערליכען קאַמף, זיי האָבען מלחמה מיט זיך אַליין, זיי פיהלן אַליין זייער רחמנות, און זיי ווייסען גוט זייער ניט גוט וואָס עס קאָן זיין, אָבער זיי קאָנען ניט ביישטעהן און ווערן באַזיגט פון יצר הרע.\nאון דאָס דאַרף זיין די אויפגאַבע פון אגודת חסידי חב\"ד בארצות הברית וקאנאדע, אויף איינאָרדענען אין געוויסע צייטען, וואָס זאָל פּאַסטען פאַר די חברים, חסידות'שע שמועסן און ערקלערונגען, און דייטלעך אַרומרעדן פערשידענע ענינים אין חיזוק המצוות און חיבת התורה, וואָס דאָס וועט זיין אַ מזון רוחני פאַר פיהל פון גזע החסידים.\nמו. די זאַך פון משפט איז טאַקע אַז מ'דאַרף חלילה שטראָפן די זינדיגע, אָבער די הויפּט זאַך פון משפט איז למען ישמעו ויראו ולא יזידון עוד<sup data-n=\"834\">129</sup>, אַז דער עונש זאָל ווירקען אַז עס זאָל ניט זיין קיין זינדיגער. ניט דער עונש איז דער משפט, נאָר דער משפט איז אַ",[["834","129","שופטים יז, יג. וראה גם אגרות­קודש כ\"ק אדמו\"ר שליט\"א חי\"א ע' תד. לקוטי שיחות חלק ל ע' 1 ובהערה 6."]]],[4301600309,"געוויסע לערנונג וואָס עס דאַרף ווייזען מענשען ווי צו פיהרען זיך.\nדי משנה זאָגט (מכות פ\"א מ\"י) די סנהדרין וואָס האָט אַרויסגעטראָגען אַ טויט אורטייל איין מאָהל אין זיבען יאָהר, ראב\"ע זאָגט, אַז איין מאָהל אין זיבעציג יאָהר, ווערט די סנהדרין אָנגערופען חובלנית, קטלנית, אַ סנהדרין וואָס טויט מענשען.\nדי זאַך איז זעהר וואונדערליך, דער עם ישראל איז געווען זעהר גרויס, אַז אין דער שטאָט ירושלים עיר הקדש ת\"ו איז גיווען שצ\"ד בתי דינין (כתובות ק\"ה ע\"א) פון סנהדרי קטנה (צי כ\"ג דיינים) איז אַז די סנהדרין האָבען איין מאָהל אין זיבעציג יאָהר אַרויסגעטראָגען אַ טויט אורטייל, רופט מען די סנהדרין קטלנית, פאַרוואָס איז דאָס?\nנאָר דער אמת איז, אַז די זאַך פון די סנהדרין איז לערנען די אידען, געבען זיי אַ ריכטיגען חינוך והדרכה<sup data-n=\"835\">130</sup>, הן מסדר זיין דעם חינוך הבנים והבנות ביי גוטע מלמדים און מדריכים און הן דער סדר אין השגחה אויף דער הנהגה פון בני ובנות ישראל, זעהען אַז זיי זאָלען ניט צו קומען צו שלעכטע וועגען, און דערפאַר איז די סנהדרין וואָס האָט אפילו מעהר ניט ווי איין מאָהל אין זיבעציג יאָהר אַרויסגעטראָגען אַ טויט אורטייל, ווערט זי אָנגערופען קטלנית.\nוויילע אָט דאָס וואָס עס געפינט זיך אַזאַ זינדיגער, וואָס איהם קומט טויט שטראָף, איז דאָס אַ באַווייז, אַז די סנהדרין האָט ניט געטאָן ריכטיג דאָס וואָס איהר חוב איז צו טאָן, ערקלעהרען און געבען צו פאַרשטעהן ווי דער מענטש דאַרף זיך פיהרען, אויף צו זיין איינגעהאַלטען פון נאָכגעבען די האַרץ אפילו אין די פאַרגעניגענס וואָס מ'מאָג.\nדער נאָכגעבען זיך אין פאַרגעניגן דאָס בריינגט דעם מענטשן צו די גרעסטע שלעכטע זאַכען, די קערפּער­ליכע פערגעניגענס צוברעכען דעם מענשענס'ס לעבען.\nדער משפט פון משיח'ן איז, אַז לא למראה עיניו ישפוט ולא למשמע אזניו יוכיח, משיח'ס משפט וועט ניט זיין ווי אַ מענטשליכער משפט, אַז מעהר ניט וואָס ער זעהט און הערט.\nמשיח'ס משפט וועט זיין אַז ער וועט קוקען זעהען און פיהלען אויך די סבות וואָס האָבן מיטגעבראַכט דעם זינדיגער אויף זינדיגען, ער וועט אויך פיהלען ווי דער זינדיגער האָט דאָס ניט געוואָלט טאָהן, אָבער ער האָט זיך ניט געקאָנט גובר זיין אויף זיין תאוה.\nמז. אַז משיח וועט קומען בב\"א וועט זיין תחיית המתים און דאַמאָלסט וועט זיין אַ דין ומשפט ווער עס זאָל אויפשטעהן צו תחיית המתים. אויך די וואָס וועלן דערלעבען און זוכה זיין צו זעהען ווי משיח וועט קומען, וועט אויף זיי אויך זיין אַ דין ומשפט<sup data-n=\"836\">131</sup>.\nדעם דין ומשפט וועט משפט'ן משיח אַליין, און אויף דעם זאָגט דער פסוק, אשר לא למראה עיניו ישפוט ולא למשמע אזניו יוכיח, נאָר ער וועט אַריינגיין אין דעם שווערען לעבען פון אידען אין גלות, און וועט אויף זיי מעורר רחמים זיין און געפינען אַ זכות,",[["835","130","להעיר מתדבא\"ר פי\"א. לקוטי שיחות חלק טז ע' 378 ובהערות שם. חלק יז ע' 213."],["836","131","ראה אגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"ב ע' עו. ועוד."]]],[4301600310,"אַז זיי האָבען ניט געוואָלט זינדיגען, נאָר זיי האָבען זיך ניט געקאָנט מתגבר זיין אויפן יצר הרע.\nער משיח, וועט זעהען די גוטע זייט, דערפאַר אידן טוהט תשובה, האָט חרטה אויף די ניט גוטע זאַכען, די תשובה און די חרטה וועט העלפען אויף זוכה זיין צו גילוי המשיח.\nדי הנהגה פון משיח'ן וועט זיין ושפט בצדק דלים, והוכיח במישור לענוי ארץ, אַ דל איז ניט די מדריגה פון אַ עני ואביון<sup data-n=\"837\">132</sup>, אַ דל איז ניט ווייט פון אַ עשיר בדעה<sup data-n=\"838\">133</sup>, נאָר ער איז אַ דל וואָס אין ידו משגת<sup data-n=\"839\">134</sup> צו טאָהן דאָס וואָס ער פערשטעהט.\nאַ עשיר בדעה איז דער, וואָס פערשטעהט וואָס גוט איז, טאָהן גוטע זאַכען מיט דעם צווייטען און והדומה דאָס טוט ער, און דאָס וואָס ניט גוט איז, כמו תאוה, ריידען רכילות אָדער שקר והדומה, טוט ער ניט.\nאַ דל איז, וואָס אין ידו משגת, דאָס הייסט ער ווייס אויך וואָס עס איז גוט אין וואָס עס איז שלעכט, נאָר דאָס אַלץ פאַרשטעהט ער אין קאָפּ; אָבער אין ידו משגת ער האָט ניט די שטאַרקייט ביי זיך אויף צו ברענגען דאָס אין לעבען, טאָן וואָס עס איז גוט צו טאָן, און ניט טאָן דאָס וואָס ניט גוט איז.\nאון דעם דל וואָס אין ידו משגת להעמיד על עצמו וועט איהם משיח משפט'ן אָבער דער משפט וועט זיין בצדק, ער וועט אויף איהם מלמד זכות זיין.\nמח. והוכיח במישור לענוי ארץ, ענוי ארץ זיינען ווערט אַז מען זאָל זיי מוסר'ן, וואָרום יעדער מענטש דאַרף זעהען דערוועקען אויך דעם צווייטען אויפצוטאָהן גוטע זאַכען, אָבער אַז ער ווערט ביי זיך אַ עניו און זאָגט, וואָס בין איך פאַר אַ וועקער דעם צווייטען, וואָס בין איך פאַר אַ זאָגער, דאָס איז זעהר אַ שעדליכע ענוה, דאָס ברענגט צו, צו ניט גוטע זאַכען, און דערפאַר זיינען די ענוים ווערט אַ גרויסען מוסר.\nאין לעבען זעהען מיר אַז איינער רעדט מיט דעם צווייטן און ער וועקט איהם צו טאָהן אַ גוטע זאַך, קובע זיין עתים לתורה, טאָהן אַ מצוה, געבען צדקה, העלפען די וואָס לערנען תורה והדומה, איז אַז מ'רעדט אין דעם, מאַכט דאָס אַ ווירקונג.\nעס איז אַ חובת גברא אויף יעדן אידען, אַז איינער זאָל דעם צווייטען מעורר זיין און אָפט צוזאַמענקומען און ריידען מכח לערנען תורה, און מחזיק זיין לומדי תורה ועוד, אָבער דער וואָס זאָגט, וואָס בין איך פאַר אַ מעורר, וואָס בין איך פאַר אַ זאָגער, מיט דעם איז ער גורם ביטול תורה, ביטול החזקת התורה און אויך אַנדערע זאַכען, איז משיח וועט זיי משפט'ן אָבער ער וועט אויף זיי געפינען אַ לימוד זכות.\nוהי' צדק אזור מתניו והאמונה אזור חלציו, מתניו און חלציו איז דאָס די ביינער וואָס האַלטען אויף דעם גאַנצען קערפּער, מתניו איז דער טייל קערפּער וואָס מ'רופט פּלייצע, חלציו איז דער טייל קערפּער וואָס באַם ענדע חוט השדרה און עס הויבען זיך אָן די ביינער פון די פיס, דאָס הייסט אַזוי, אזור מתניו, דאָס איז די קראַפט וואָס האַלט אויף דעם מענטשנ'ס קערפּער",[["837","132","להעיר מויק\"ר פל\"ד, ו. ועוד."],["838","133","ראה כתובות סח, א: עשיר בדעת."],["839","134","ע\"פ לשון הכתוב — מצורע יד, כא."]]],[4301600311,"אַליין. אזור חלציו, דאָס איז די קראַפט, וואָס מענטשען גיבען איבער קינדער, דערפאַר ווערען קינדער אָנגערופען יוצאי חלציו<sup data-n=\"840\">135</sup>.\nדאָס איז אַלץ מדריגת המשיח, וואָס ווערט אָנגערופען מדריגת האור, די אַלע זאַכען איז פאַראַן אין דער כלי פון דעם אור, דאָס הייסט אין חסידות, וואָס חסידות איז שכל אלקי ועבודת השי\"ת.\nמט. דער<sup data-n=\"841\">136</sup> שכל פון חסידות איז אַ שכל אלקי, וואָס דאָרטען איז דער ענין פון התכללות דחכמה היא נקודה ובינה היא היכלא<sup data-n=\"842\">137</sup> וצריכים להיות שניהם<sup data-n=\"843\">138</sup>, דגם בהשגה דבינה יהי' הביטול דחכמה, וזהו ג\"כ עצה וגבורה דהעצה דחו\"ב יבא בעבודה בפועל בגבורה, ותוקף המדות שבלב ואז הוא דעת ויראת ה', שהו\"ע ערום ביראה<sup data-n=\"844\">139</sup> לפעול הבירור וזיכוך דכל עניני עולם והוא ע\"י העבודה.\nדי וועלט האָט אַ טעות און מיינט אַז עבודה איז נאָר וואָס מ'געהט אין וואַסער פאַרן דאַוונען, מ'דאַווענט פינף אָדער זעקס שעה מיט חיות, מ'פאַסט, מ'לערנט אַ סך תורה. ניין, עס איז אַ טעות. עבודה ווערט אָנגירופען, אַז אַ איד געהט אין גאַס דאַרף דער שטיין דערהערען אַז אַ איד האָט אויף אים געטראָטען<sup data-n=\"845\">140</sup>, עס דאַרף ווערען ריינער דער אויר<sup data-n=\"846\">141</sup>, עס דאַרף ווערען ליכטיגער די וועלט.\nאון בכדי עס זאָל אַזוי זיין, אַז די וועלט זאָל ליכטיגער ווערען, דאַרף מען אָט די אַלע זאַכען, וואָס מ'האָט געזאָגט, מ'דאַרף לערנען חסידות, מ'דאַרף דאַוונען באריכות און מיט אַ חיות, מ'דאַרף עוקר מן השרש זיין די אַלע מדות רעות און מ'דאַרף האָבען מדות טובות, און דאַמאָלסט ווערט ליכטיג די וועלט.\nאון דאָס איז והי' צדק אזור מתניו והאמונה אזור חלציו, די אמונה דאָס איז דער גאַרטעל וואָס עלטערען גיבען איבער קינדער. אַלע ווייסען גאַנץ גוט אַז קיין זאַך אין דער וועלט קאָנען עלטערען אַ קינד ניט איבערגעבען, די אַלע גשמיות'דיגע ירושות זיינען ניט זיכער און ניט פעסט.\nדי אַלע גשמיות'דיגע זאַכען נעהמט דער מענטש ניט מיט מיט זיך אין קבר (ווי מ'זאָגט אין דעם געוויסען קאַפּיטל תהלים<sup data-n=\"847\">142</sup>, דער אויבערשטער זאָל העלפען אַז ובלע המות לנצח<sup data-n=\"848\">143</sup>, און אַלע אידען זאָלען לאַנג לעבען) און דאָס איז אויך ניט קיין זיכערע ירושה פאַר קינדער.\nדי אמת'ע זיכערע ירושה וואָס עלטערן גיבען איבער קינדער איז, כחות הנפש און אמונה. און דאָס איז והאמונה אזור חלציו, דאָס איז די הויפט זאַך וואָס דער מענטש גיט יוצאי חלציו.\nדי גאַנצע וועלט מענטשן, איז זייער",[["840","135","ראה מלכים­א ח, יט. דברי הימים­ב ו, ט. ועוד."],["841","136","ראה לעיל סל\"ו­לח (ע' 115 ואילך)."],["842","137","ראה זח\"א ו, רע\"א. אגה\"ק ס\"ה (קז, א). לקו\"ת ר\"פ ראה (יח, ב)."],["843","138","לקו\"ת שם. ובכ\"מ."],["844","139","ראה ברכות יז, א."],["845","140","ראה \"היום יום\" טו אדר א. לקמן ס\"ע 155 ואילך. ועוד."],["846","141","ראה אגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"א ע' קו­קז. ע' רלה ואילך. ועוד."],["847","142","מט, יח."],["848","143","ישעי' כה, ח."]]],[4301600312,"האָפענונג איז, אַ קינד און דאָס איז דער תקות אדם, יעדער מענטש אָהן אונטערשייד, רייך אָדער אָרעם ח\"ו, איז דער עיקר אַ קינד. דער טעם הדבר בשרשו איז, וויילע דאָס איז דאָך דער כח אין סוף אין נבראים. דער בנין עדי עד, דער נברא וואָס ער איז דאָך בעצם אַ מוגבל, איז דערפאַר באַ איהם דער עיקר אַ קינד, וואָס דאָס איז דער בלי גבול פון נבראים<sup data-n=\"849\">144</sup>.\nאון דאָס איז די ירושה וואָס עלטערען גיבען איבער קינדער, די אמונה, דאָס איז אַן אייביגע זאַך.\nנ. אין פסוק שטעהט והאמונה, ער האָט דאָך געדאַרפט זאָגען ואמונה, פאַרוואָס זאָגט ער והאמונה? אָט די אמונה דוקא, דאָס איז שייך צו זאָגען נאָר אויף אַ זאַך וואָס עס איז דאָ עטליכע מינים, זאָגט מען דאַמאָלט, די זאַך, און ניט קיין אַנדערע. אמונה איז איינע, אַלע אידען זיינען מאמינים בני מאמינים, איז וואָס זאָגט ער והאמונה?\nאמת, אַלע אידען זיינען מאמינים בני מאמינים<sup data-n=\"850\">145</sup>, אַלע אידען גלויבען אין דעם אויבערשטען ב\"ה, שם שמים איז שגור בפי כל, געלויבט איז דער אויבערשטער, איז דער ערשטער וואָרט וואָס יעדער איד, אנשים נשים וטף, זאָגען.\nאַז איינער פרעגט דעם אַנדערען: וואָס מאַכסטו? ענטפערט איהם דער צווייטער: געלויבט דער אויבערשטער, אָדער אַ דאַנק. . .\nאידען גלויבען אין דעם אויבער­שטען ב\"ה וואָס ער איז העכער ווי טבע, ווי מיר זעהען אין טעגליכען לעבען, איינער ח\"ו האָט ניט קיין עסק און קיין כלי צו פרנסה, ענטפערט איהם דער צווייטער: זאָרגט ניט, דער אויבער­שטער העלפט; אַז איינער איז רחמנא ליצלן אַ גרויסער חולה, דאָקטוירים זאָגען חלילה אָפּ, טרייסט מען, דער אויבערשטער וועט רחמנות האָבען, ער זאָל רחמנות האָבען, ער איז דאָך דער רופא חולים, און דער אויבערשטער ב\"ה האָט דאָך רחמנות.\nדער טעגליכער אידישער לעבען און די הונדערטער טויזנטער מסירות'נפש'ן און קידוש­השם'ן וואָס אידען, אנשים נשים וטף, האָבען דורכגעטראָגען און טראָגען דורך אין פערשידענע מדינות אין פערשידענע אופנים, איז דאָס אַ בעווייז אויף דער אמונה טהורה, וואָס ביי אידען יחיו איז, אַז די אמונה איז ביי זיי איינגעוואָרצעלט אין דער טיפעניש פון זייער לעבען.\nאָבער אמונה איז מקיף<sup data-n=\"851\">146</sup>, דערפאַר קאָן זיין אין דעם מענשענ'ס פיהרונג צוויי זאַכען וואָס זיינען הפכים, למשל, איינער געהט גנב'ענען און בעט דעם אויבערשטען ב\"ה אַז ער זאָל איהם העלפען אַז די גניבה זאָל איהם געלינגען, מ'זאָל איהם ניט כאַפּען<sup data-n=\"852\">147</sup>. ער גלויבט אין דעם אויבערשטען ב\"ה און טוט אַ זאַך וואָס דאָס איז נגד דעם",[["849","144","לקו\"ת שה\"ש לט, ד ואילך. מאמרי אדמו\"ר האמצעי ויקרא ח\"ב ע' תרעא ואילך. סה\"מ תרנ\"ד ע' רסד ואילך. תרנ\"ז ע' קעט. עטר\"ת ע' תיד. תרפ\"ו ע' רכו ואילך."],["850","145","שבת צז, א."],["851","146","ראה תו\"א הוספות לפ' תשא קיא, א ואילך. סה\"מ עטר\"ת ע' רסז ואילך. תרפ\"ז ע' קיג ואילך. ד\"ה כי תשא תשי\"א (סה\"מ תשי\"א­תשי\"ג ע' 19 ואילך)."],["852","147","ראה ברכות סג, א (לפי גירסת העין יעקב). מקומות שצויינו בהערה הקודמת."]]],[4301600313,"אויבערשטענ'ס ב\"ה אַ צוזאָג, לא תגנוב<sup data-n=\"853\">148</sup>.\nדער וואָס גלויבט אין דעם אויבערשטען ב\"ה און בעט דעם אויבערשטען ב\"ה אַז ער זאָל איהם העלפען, דאַרף ער דאָך גלויבען אַז דער אויבערשטער ב\"ה וועט איהם געבען זיין פרנסה כשר, פאַרוואָס טוט ער אַזאַ זאַך וואָס איז געגען דעם אויבערשטענ'ס ב\"ה צוזאָג.\nנאָר וויילע אמונה איז מקיף, דער ענין פון מקיף איז אַז די ווירקונג איז אַ כללות'דיקע. אמונה איז טאַקע איינגעוואָרצעלט ביי יעדען אידען אין טיפען האַרצען, אָבער דאָס איז מעהר ניט וואָס עס נעהמט איהם אַרום במקיף, און די פעולה פון מקיף איז אַ כללות'דיקע, דערפאַר קאָן זיין דבר והיפוכו, ער גלויבט בהשי\"ת אַז ער ב\"ה איז דער זן ומפרנס<sup data-n=\"854\">149</sup>, און טוהט די עבירה פון גניבה, אָדער אַנ'אַנדער עבירה.\nדי הייליגע און גרויסע אמונה דאַרף דער איד אַריינטראָגען אין לעבען פאַרווירקליכען זי אין אַלע זיינע פיהרונגען. און דאָס איז דער מיין פון פסוק וואָס ער זאָגט והאמונה, די באַוואוסטע אמונה וואָס מ'טראָגט זי אַריין אין טעגליכען לעבען, אַז אַלע זיינע פירונגען זאָלען זיין לויט דער ליכט פון דער אמונה.\nדערפאַר זאָגט ער והאמונה, ניט ואמונה, וואָרום אמונה הייסט די געבירטליכע אמונה, וואָס יעדער איד ווערט מיט איהר געבוירען, אָבער דאָס קאָן זיין דבר והיפוכו, ער גלויבט בהשי\"ת און פונדעסטוועגען טוט ער אַ עבירה.\nאָבער מיט דעם וואָס ער זאָגט והאמונה, מיינט ער אָט די געבירטליכע אמונה, וואָס מ'טראָגט זי אַריין אין טעגלעכען לעבען, דאָס הייסט, אַז דער טעגלעכער לעבען זאָל זיין לויט דער בעלייכטונג פון דער אמונה. יעמאָלט אַז די אמונה לייכט אין אַ פנימיות, קאָן ניט זיין דבר והיפוכו.\nאון דאָס איז והאמונה אזור חלציו, אַז די אמונה וואָס ער פיהרט דעם טעגליכען לעבען נאָך דער אמונה דאָס איז די ריכטיגע ריינע ירושה און אידישע קראַפט, וואָס עלטערען גיבען קינדער און יוצאי חלציהם לדורי דורות.\nנא. די גרויסע הייליגע איבערגעבונג אַז די אמונה זאָל בעלייכטען דעם טאָג טעגליכען לעבען, איז אין דער האַנט פון די עלטערען, ווי זיי פירען זיך אַליין. דער חינוך פון די קינדער איז אָנגעהאָנגען אין דעם אופן לעבען און פירונג פון די עלטערען.\nדי אידען וואָס ווילען אַז זייערע קינדער זאָלען זיין אידען, דאַרפען זיי לערנען זייערע קינדער אויפן אַלטן סדר, קמץ א אָ, אָהן מעטאָדעס דאָס נעהמט אַראָפּ די גאַנצע הייליגקייט פון אותיות התורה<sup data-n=\"855\">150</sup>.",[["853","148","יתרו כ, יג. ואע\"פ דפסוק זה מיירי בגונב נפשות (סנהדרין פו, א), מצינו שהשתמשו בו גם לענין גניבת ממון — ראה תורה שלימה עה\"פ. וש\"נ. וראה גם רא\"ם משפטים כא, ו. לקוטי שיחות חלק יא ע' 89 הערה 6."],["854","149","מדרש תהלים קלו, ח. מדרש משלי לא, ה. זח\"ב קע, א. ברכה ראשונה דברכת המזון."],["855","150","ראה לעיל ע' 44. וש\"נ."]]],[4301600314,"מ'דאַרף ניט נתפעל ווערען וואָס אַ סאַך באַנוצען זיך מיט די מעטאָדעס. די עהרליכע אידען וועלען זיך לבסוף כאַפּען אויפ'ן גרויסען פעהלער וואָס זיי זיינען באַגאַנגען. דער חינוך פון קינדער מוז זיין נאָר אַזוי ווי ער איז געווען, און מ'דאַרף לערנען גמרא.\nצוליב דעם חינוך פון די קינדער מוז די פיהרונג אין שטוב זיין אַ אידישע. אַז דער פאָטער געהט אין מנין דאַוונען און געהט הערן די שיעורים וואָס מ'לערנט, און די מוטער היט אָפּ אידישקייט, און דער שבת איז אַ שבת, איז דער אויר אין שטוב אַ גוטער, און דאָס ווירקט אויף די קינדער אַז עס וואָרצלט זיך איין אין זיי אידישקייט.\nאון דאָס איז והאמונה אזור חלציו, דאָס וואָס עלטערען קאָנען געבען קינדער און גיבען איבער קינדער, איז די אמונה.\nאידען, פיהרט זיך אויף ווי געזאָגט אין חינוך און הנהגה, וועט איהר זוכה זיין זעען בנים ובני בנים עוסקים בתורה ובמצוה.\nבכדי אַז אַ איד זאָל זעען בנים ובני בנים עוסקים בתורה ובמצוה, דאָס הייסט אַז די קינדער זאָלען זיין אידען, וויל איך אייך זאָגען אַ פּאָר ווערטער אין דעם. מיר איז זייער שווער צו רעדען באריכות, איך וויל זאָגען קורץ אייניגע ווערטער, און יעדערער זאָל דאָס גוט הערען און דערהערען. די ווערטער זאָלען אַריין יעדערען אין האַרצען. איך וועל זאָגען מועט המחזיק את המרובה.\nבויען דעם דור ובית ישראל ע\"פ התורה, דאַרפען טאַטע און מאַמע ביידע צוזאַמען מיט איין דעה, מיט איין שטימע, מיט איין שטרעבונג, איינער פון זיי קאָן ניט טאָהן, דאָס מוזען זיי ביידע צוזאַמען מיט איין דעה, און מיט איין פיהרונג.\nדי מוטער איז די עקרת הבית<sup data-n=\"856\">151</sup>, די וואָס בנתה ביתה<sup data-n=\"857\">152</sup>, זי שטעלט די יסודות פון דער הויז מיט איהר גוטער אידישער פירונג, און דאַמאָלסט איז זי די עקרת הבית. אָבער ווען די מוטער היט ניט קיין אידישקייט, דאַמאָלסט איז זי די עוקרת הבית, דאַמאָלסט רייסט זי אויס איהר הויז פון דער אידישער תורה און פון דעם אידישען פאָלק, דאַמאָלסט מאַכט זי דעם חורבן פון איהר הויז.\nמעהר קאָן איך איבער דעם ניט ריידען, און איך קעהר זיך צו יעדערען וואָס האָבען געהערט וואָס איך האָב דאָ געזאָגט די עטליכע ווערטער, מיט אַ טיפער, נפש'דיקע בקשה, אַז יעדערער זאָל די ווערטער גוט געדענקען, און אויף איהם ליגט אַ חוב קדוש ממלא זיין מיין הערצליכע בקשה, איבערגעבען די ווערטער זיינע בעקאַנטע, און ערקלערן דעם ריכטיגען זין פון די ווערטער, וואָרום אין דעם היינגט אָפּ דער בנין פון בית ישראל. און דער וואָס וועט ממלא זיין מיין בקשה, זאָל השי\"ת איהם באַגליקען אין אַלעס גוטעס, ברוחניות ובגשמיות.\nנב. איצטער וועלען מיר פערשטעהען דעם ענטפער וואָס משיח האָט געענטפערט לרבינו הבעש\"ט נ\"ע אויף זיין פראַגע, ווען וועט ער קומען, לכשיפוצו מעינותיך.\nאונזערע טאַטעס און זיידעס פון עדת",[["856","151","ראה ב\"ר פע\"א, ב. זח\"א קנד, א. אוה\"ת נ\"ך ח\"ב ע' תתעא."],["857","152","משלי יד, א."]]],[4301600315,"החסידים, אַלע חסידי חב\"ד אויף דעם גאַנצען כדור הארץ, זיינען ווי איין משפחה, וואָרום די יסודות פון חסידות וחסידים איז אחדות, אהבה ואחוה.\nדי טאַטעס און זיידעס פון משפחת החסידים האָבען געהאָרעוועט אויף חסידות און הנהגות במדות חסידות.\nחסידות איז חיות, אמת ואור. אַ ליכטיגער אמת'ער לעבען, אַלץ וואָס מ'טוהט זאָל זיין מיט חיות, מיט אַן אמת, דאַוונען מיט אַ חיות, טאָן אַ מצוה מיט אַ חיות, לייען אַ גמ\"ח דעם צווייטען מיט אַ חיות, דאַוונען און וויינען ר\"ה ויוהכ\"פ מיט אַ חיות. אַלץ וואָס מ'טוט זאָל זיין מיט חיות.\nאויף דעם האָבען די טאַטעס און זיידעס פון משפחת עדת החסידים געהאָרעוועט און געלייגט דעם לעבען, דאָס הייסט, זיי האָבען זיך מוסר נפש געווען אויף דעם והאמונה, אַז די אמונה זאָל אַריין אין לעבען, דייטלעכער און קלערער געזאָגט, אַז זייער מסירות נפש איז געווען אַז דער טעגליכער לעבען זאָל זיין נאָך דער בעלייכטונג פון דער אמונה.\nאַזוי האָבען זיי זיך אַליין געפיהרט, און אַזוי האָבען זיי מחנך גיווען זייערע קינדער. יעדערער האָט געזאָרגט פאַר זיך און פאַר זיין קינד. ער האָט געטאָהן אַלץ אין דער וועלט אויף בריינגען זיין קינד אין דער חסידישער מסיבה. ער האָט אַוועקגעגעבען געוויסע צייט אויף צו פאַרבריינגען מיט זיין קינד אין דער שטימונג פון חסידות און מדות חסידות, ערקלערט דעם קינד אַז זיין מוח'ל זאָל דאָס פאַרנעמען. . .\nער האָט געזעהען, אַז די שטוב זיינע זאָל זיין אַ בית ועד לחסידים, מ'זאָל זיך ביי איהם צוזאַמענקומען. אין דער חסידישער מסיבה, האָט מען גערעדט וועגען תורה וועגען עבודה שבלב, ווי מ'דאַרף דאַוונען, וועגען מדות טובות, ווי מ'דאַרף זיין אַ חסיד, וואָס איז אהבת ה', וואָס איז יראת ה', וואָס איז אהבת ישראל.\nעס פלעגט זיין מסיבות ביי חסידים וואָס מ'פלעגט זיך מיישב זיין און מטכס עצה זיין אין פערשידענע עניני חסידות. אין אַזאַ מסיבה פלעגט מען יונגעלייט ניט אַריינלאָזען. די טיהרען זענען געווען פאַר זיי פאַרשלאָסען, ניט דער וואָס וויל האָט געקאָנט אַריין, מ'האָט געדאַרפט זיין ראוי אַז מ'זאָל אַריינגעהן אין אַזאַ מסיבה, מ'האָט געדאַרפט האָבען געוויסע הכנות.\nאין דער עדת החסידים האָבען זיך געפונען אָט די, וואָס האָבען זיך אָפּגעגעבן מיט די יונגעלייט, מיט זיי גערעדט ווי מ'דאַרף זיין, זיי האָבען זיי געלערענט, זיי האָבען זיי מוכיח געווען, אַז מ'האָט געזעהען ניט קיין גוטע מדה פון שקר, רכילות, גאוה והדומה, האָט מען דאָס אויסגעריסען מיטן וואָרצעל, ביטול היש ניט נאָר אויפן פּאַפּיר, נאָר טאַקע אין לעבען.\nיונגע לייט פון עדת החסידים פלעגען זיך וואַלגערן אַרום די טיהרען, אַרום די פענסטער, טאָמער וועלען זיי הערן עפּעס אַ וואָרט, אַ מעשה. יעדערער האָט געגאַרט הערן און זעהען ווי חסידים פאַרבריינגען, יעדערער פון די יונגעלייט האָט געוואוסט אַז אָט דאָס איז דער קוואַל פון וואַנען עס נעהמט זיך גוטע זאַכען פון יראת שמים ומדות טובות.\nאון אָט דאָס איז והאמונה, לעבען אין טעגליכען לעבען מיט דעם חסידות'"],[4301600316,"­דיגען חיות און התלהבות, וואָס די אמונה האָבען די זיידעס און טאַטעס פון משפחת עדת החסידים איבערגעגעבען בירושה זייערע קינדער און אייניקלעך.\nנג. און דאָס איז דער ענטפער פון משיח'ן, לכשיפוצו מעינותיך חוצה, אָט די והאמונה וואָס די זיידעס און די טאַטעס האָבען געלאָזט בירושה זייערע קינדער און אייניקלעך, איז אין דעם גלות שטראָם צעשפּרייט און צעזייט געוואָרען במרחבי תבל און מדינות שונות.\nאון אויך<sup data-n=\"813\">109</sup> באַ אַזעלכע וואָס איבער פארשידענע סבות זיינען זיי פאַר­שטויסען געוואָרען אין חוצה, אַז מען איז אָפּגעריסען פון אידישקייט, אַז עס רעדט זיך ניט וועגען חסידות און הנהגות פון חסידים, עס רעדט זיך מכח טהרת המשפחה, הנחת תפילין, שמירת שבת, מאכלות כשרות.\nאלס איינער פון גזע ובא כח הוד כ\"ק אבותינו רבותינו הקדושים זצוקללה\"ה נבג\"מ זי\"ע פאַל איך ביי זיך ניט אַראָפּ מיט די גזע החסידים וואָס זיינען אַוועק חוצה, וויסנדיק אַז אין זיי פליסט די בלוט פון זייערע עלטערן און אור עלטערן.\nאון דאָס זאָגט משיח, אַז אין דעם חוצה איז פאַראַן מעינותיך, די האָבען אין זיך אויך די גרויסע ירושה פון זייערע זיידעס און טאַטעס און אין זיי קאָן זיך אויפוועקען די פּינטעלע פון דעם והאמונה, וואָס זייערע עלטערען האָבען זיך מוסר נפש געווען.\nמשיח'ס ענטפער איז, יפוצו מעינותיך חוצה, די תורת רבינו הבעש\"ט נ\"ע און די עבודה טהורה בבירור וזיכוך המדות וועט זיך סוף כל סוף צעשפרייטען, אַז אַלע וועלען דערקאָנען דעם אמת, און אויך אפילו די וואָס געפינען זיך אין חוצה איז דער מסירות נפש פון זייערע עלטערען און זיידעס וועט זיי אויפוועקען, אַז זיי זאָלען זיך בענוצען אין פערגעניגען פון הנהגות טובות מיט דעם קלאָהר ריינער ירושה, וואָס זייערע זיידעס און טאַטעס האָבען זיי איבערגעלאָזען.\nדער אויבערשטער זאָל אונז העלפען, בתוך כלל ישראל מיט אַ גליקליכען יאָהר אין אַלץ, און מיר זאָלען זעען ווי די עדת החסידים איז ממלא זייער חוב בתורה ועבודה, און די צווייגעלעך פון דעם אילנא דחיי, גזע החסידים, זאָלען אויפלעבען. און מיר אַלע בתוך כלל אחב\"י שי' זאָלען זוכה זיין זעהען בנים ובני בנים עוסקים בתורה ובמצוות.",[["813","109","ראה לקוטי שיחות חלק טו ע' 287. וראה שם ע' 282. ועוד."]]],[4301600317,"<h3>יום ג', כ\"ב כסלו תר\"ץ<sup data-n=\"859\">1</sup></h3>\nבבואי<sup data-n=\"860\">2</sup> כל הנאספים עומדים ומובילים אותי אל הבימה מושב הפרעזידום<sup data-n=\"861\">3</sup>, כולם עוטרים אותי בנתינת שלום והיו\"ר הרב סילווער<sup data-n=\"862\">4</sup> מאריך בדרוש תהלה, אח\"כ פונה אלי כי אדבר",[["859","1","מיום א' י\"ג כסלו עד יום א' י\"ב טבת הי' רבינו בפילאדעלפיא. בכ\"ב כסלו נסע רבינו ליום אחד לניו יארק לאסיפת רבנים — ראה לעיל ב\"מבוא\" ע' נג."],["860","2","מיומנו של רבינו."],["861","3","{6} הנשיאות."],["862","4","הרב אליעזר סילווער, יו\"ר אגודת הרבנים."]]],[4301600318,"אל הועידה. בעמדי לדבר, עמדו כל הנאספים כשמונה מאות איש, וברכתי את כולם בנענוע ראש, וישבו כולם על מקומם השקט. השקיטה והחרישות הרעישה אותי במאד, ופתחתי נאומי הקצר בשפה ברורה ת\"ל.\nראשית כל אברך את ד' אשר זיכני לראות כנסי' גדולה, כן ירבו, אשר זכיתי לראות כמותו אין דער אַלטער היים, הזכרה לרבותינו הגאונים, כ\"ק אאמו\"ר, הרה\"ג ר\"ח שי'<sup data-n=\"863\">5</sup>, ויבדלו לחיים טובים הגח\"ח<sup data-n=\"864\">6</sup> והגרח\"ע<sup data-n=\"865\">7</sup>. אי אפשר להאריך בדיבור, ולבאר מצב אחינו בני רוסיא האטעלען<sup data-n=\"866\">8</sup>, אמעריקאן, לאנדון וכו', מיר ווערין געבארין<sup data-n=\"867\">9</sup>, און אויף אַלע געביטען, איך בעט און רוף דעם עם ישראל דורך זיינע נשיאים הרבנים ומוסדות שונות, אגוה\"ר, עזרת תורה, לבוא לעזרת אחיהם, בכל עיר יהי' קאָמיטעט און דאַן קאָנען אונזערע ברידער געהאָלפן ווערן. איך באַגריס דעם אגוה\"ר און ווינטש זיי ערפאָלג אין חיזוק התורה יהדות ומצב הרבנות וואָס דאַן וועט דער עם ישראל שטיין אין חיזוק התורה אויף דער העכסטער שטופע פון גליק.",[["863","5","הגאון ר' חיים סאלאוויטשיק מבריסק."],["864","6","הגאון בעל החפץ חיים."],["865","7","הגאון ר' חיים עוזר גראדזענסקי מווילנא."],["866","8","אוצ\"ל: לעטעלען; לעטלאנד; לטביא."],["867","9","אוצ\"ל: גיבראכן."]]],[4301600319,"<h3>יום ועש\"ק, ט' שבט תר\"ץ<sup data-n=\"868\">1</sup></h3>\n.. . מהו<sup data-n=\"869\">2</sup> חסידות, אַ אמת ליכטיקער לעבעדיקייט. תניא הוא לקוטי עצות, רפואה לתחלואי הנפש, חיבור הבא ממעלות אנשים וחסרונם, ואינו דומה לחיבור של מחבר.\nטאָן וואָס מ'הייסט, יעמולט וועט מען צוקומען פאַרשטיין וואָס מען טוהט.",[["868","1","מיומנו של רבינו."],["869","2","ראשי פרקים ממה שדיבר עם אחד האנשים שביקר אותו."]]],[4301600320,"<h3>יום ג', י\"ג שבט תר\"ץ<sup data-n=\"870\">1</sup></h3>\nא' מדווינסק סיפר לי אשר שמע מהוד כ\"ק אדמו\"ר מהר\"ש נבג\"מ זי\"ע שאמר בשם א' מיראי אשכנז, פי' הכתוב<sup data-n=\"871\">2</sup> הנמצא כזה איש אשר רוח אלקים בו, ולפי סגנון הלשון הי' לי' למימר הנמצא איש אשר רוח אלקים בו כזה. אך ידוע דפרעה עשה עצמו לבן אלקי' ומכוער גדול הי', ונתפרסם בי ההמון דרוח אלקים מפעם רק בתוככי בעלי הכיעור בגוף, ואמר הנמצא איש כזה שיהי' יפ\"ת ויפ\"מ ואשר רוח אלקים יהי' בו.\nהמא' הנ\"ל שמע בדווינסק בשנת תר\"מ בדרך עברו מווארשא לוויטעבסק.",[["870","1","מיומנו של רבינו."],["871","2","מקץ מא, לח."]]],[4301600321,"<h3>ליל ש\"ק פ' יתרו אור לכ\"ד שבט תר\"ץ<sup data-n=\"872\">1</sup></h3>\nדיבור בסעודה המעשה דהמגיד נ\"ע דבר כוונת התפלה אַז מען דאַרף סחורה דאַרף מען דאָרטן זיין<sup data-n=\"873\">2</sup>.",[["872","1","מיומנו של רבינו."],["873","2","ראה גנזי נסתרות — אור נערב — ע' כא: הרב המגיד הי' שוהה בתפלתו כמה שעות, והי' בסביבה שלו איש א' למדן וי\"ש ומתפלל ע\"פ כוונת אריז\"ל ולא הי' מאריך כ\"כ והי' לו לפלא, האיש הנ\"ל הי' עשיר והי' נוסע פעם בשנה ללייפציג ושוהה כדי מסחרו וחוזר לביתו ויושב כל השנה על התורה ועבודה.\nפעם א' עבר לרגל מסחרו דרך מעזריטש ונשאר שם לראות התפלה של המגיד. ונכנס אליו ושאל ממנו שהוא מתפלל ג\"כ ע\"פ כוונת האריז\"ל ואינו מוכרח להאריך כ\"כ. שאל לו המגיד ממה הוא מתפרנס. וא\"ל שיש לו מעט סלעים ונוסע פעם בשנה על יריד ומביא סחורות הידועים לו ומוכר אותם בעירו תיכף ומהריוח מתפרנס. שאל לו [הרב המגיד] ומהיכן תדע שהרווחת, א\"ל אני כותב הסך שהוצאתי על הסחורה וההוצאות וכאשר אני מוכר אני כותב כמה פדיתי ואני מנכה הקרן וההוצאות מסך הנפדה ומה שנשאר הוא הריוח. א\"ל הרב המגיד ולמה לך לבלות זמן לנסוע על היריד ולבוא, תכתוב על הנייר הקרן וההוצאות ותכתוב הפדיון ותנכה הקרן וההוצאות מן הפדיון. והתחיל הסוחר לצחק, וכי מן הכתיבה יבוא הריוח בלא נסיעה וקני', ובהכרח צריך לנסוע ולקנות ולבלות זמן ולמכור ואז יוכל להיות ריוח. א\"ל המגיד הכוונות הם ג\"כ כמו הסחורה, אם לא תהי' קשור בדעתך כאלו אתה שם, הוא כאלו כותב הקרן והריוח, אשר מזה לא יש שום תועלת, אבל אם תקשור נפשך שמה ויהי' שהות לקנות דבר חפץ אז תרויח בהכוונות, וע\"כ צריך ע\"ז שהות זמן בעת התפלה.\nובשיחת קיץ תרצ\"ז (\"רשימות\" חוברת קפג ע' 5): לענין מענה הרב המגיד שאם חפצים להביא סחורה דאַרפען דאָרטען זיין — סיים אדנ\"ע: דאָס האָט אויפגעטאָן חסידות אַז מיט אַ מחשבה עיונית איז מען דאָרט."]]],[4301600322,"<h3>ליל ש\"ק פ' משפטים אור לבדר\"ח אדר, תר\"ץ<sup data-n=\"874\">1</sup></h3>\nדיבור וביאור דבר העבודה מאנ\"ש בימי קדם, ביאור הפסוק ואלה המשפטים, ההפרש בין אלה ו' פעמים ו'<sup data-n=\"875\">2</sup> מדות בלא פועל, ואלה ז' פעמים ו' פועל ממש, משפטים עדות וחקים.",[["874","1","מיומנו של רבינו."],["875","2","לקו\"ת פקודי ד, ג. ובכ\"מ."]]],[4301600323,"<h3>חג הפסח, תר\"ץ<sup data-n=\"876\">1</sup></h3>\nכ\"ק אדמו\"ר שאל את רז\"ה<sup data-n=\"877\">2</sup> אם הי' בנאות דשא עם כ\"ק אאמו\"ר בקיץ תרנ\"ט<sup data-n=\"878\">3</sup>. וסיפר:\nבקיץ שנת תרנ\"ט כשהי' כ\"ק אאמו\"ר בנאות דשא התאכסן אצל בעה\"ב איש פשוט, אך שומר תורה ומצוות, והוא הי' דואג לכ\"ק אאמו\"ר בכל מאודו.",[["876","1","נדפס בשינויים קלים ב\"המשפיע\" (ירושלים, תשמ\"ב) ע' קלג. שמועות וסיפורים ח\"ג ע' 195."],["877","2","החסיד ר' שלמה זלמן האוולין (ראה אודותו ספר השיחות תר\"פ­תרפ\"ז ע' 17 ובהערה 33. וש\"נ).\nרז\"ה הי' אז בארה\"ב לאסוף כספים עבור הישיבה תורת­אמת — ראה אגרות­קודש ח\"ב ריש ע' יט ובהנסמן שם. \"המשפיע\" ע' קד ואילך."],["878","3","בשמועות וסיפורים שם: תרנ\"ח."]]],[4301600324,"בימים ההם הי' מלמד אחד מחסידי עיר בעשענקאָוויטש ור' דובער שמו. ר' דובער החליט ללכת לליובאַוויטש לשמוע חסידות. ועזב את עבודתו וכתת רגליו עד שבא לליובאַוויטש. בבואו לליובאַוויטש נודע לו שכ\"ק אאמו\"ר נמצא בנאות דשא. והלך לשם ג\"כ ברגל. כשהגיע לשם נודע לו שכ\"ק אאמו\"ר לא יאמר חסידות. וכמובן שהצטער מאד, כי כל הטרחה שטרח היתה כדי לשמוע מאמר חסידות מכ\"ק אאמו\"ר. עצב ומדוכא התהלך ר' דובער עד שפגש בו בעל האכסניא הנ\"ל. והוא מדבר על לבו שישים בטחונו בה' וכו' מבלי שידע מהי סיבת עצבותו.\nלשבת הי' ר' דובער אורחו של אותו בעה\"ב, ובכל סעודות השבת ניסה הבעה\"ב לדובב את ר' דובער שישיח לו דאגתו אולי יכול לבא לעזרתו, אך ללא הועיל. בסעודה שלישית נשבר ר' דובער, ובעיניים דומעות אמר לו שלא חסר לו מאומה, אלא שרוצה לשמוע מאמר מכ\"ק אדמו\"ר, והתייגע כ\"כ עד שהגיע לכאן, ולבסוף לא השיג את מבוקשו.\nהבעה\"ב — כיון שהי' כבן בית אצל כ\"ק אאמו\"ר — נכנס מיד לכ\"ק אאמו\"ר, ואמר לו: יש כאן אורח שיש לו צער גדול על שאינו יכול לשמוע חסידות מפי כ\"ק אדמו\"ר. כשאני רואה יהודי שרוי בצער וביכולתי לעזור — אני עוזר. והרי כ\"ק אדמו\"ר יכול לעזור ליהודי זה ולומר חסידות.\nכעבור שעה קלה, הודיע כ\"ק אאמו\"ר שיאמר חסידות. לאחר ששמע ר' דובער המאמר האָט זיין פנים געלויכטן והי' בשמחה רבה. וכשראה זאת הבעה\"ב נכנס שנית לכ\"ק אאמו\"ר, וסיפר שהמאמר גרם תענוג גדול לר' דובער, ושאל את כ\"ק אאמו\"ר אם בגן עדן יהי' לו שמחה ותענוג כזה שהי' לר' דובער לאחר ששמע המאמר. והשיבו כ\"ק אאמו\"ר: אין זה מוכרח. אלא, תדע שעבור כל פעם שאומרים תהלים בעולם הזה, מלמדים אותו בגן עדן פירוש חדש בספר תהלים. כשיצא מכ\"ק אאמו\"ר התחיל מאז לומר תהלים בהתלהבות עצומה."],[4301600325,"<h3>[שלהי תמוז, תר\"ץ<sup data-n=\"879\">1</sup>]</h3>\n.. . ביז איצט זייט איהר געווען נאָר געבער, און מיט אַ ברייטער האַנט האָט איהר געזוכט צו אונטערשטיצען תורה­מוסדות אין אייראָפּע. פון איצט אָן דאַרפט איר ווערן אויך נעהמער. . . איהר דאַרפט נעהמען פון די תורה­צענטערס אין אייראָפּע דעם דרך פון פאַרשפּרייטען דעם למוד התורה און חזוק היהדות און איינפיהרען עס אין אַמעריקע, וועלכע דאַרף און מוז אַליין ווערען אַ מקום תורה. . .",[["879","1","הועתק מקובץ ליובאוויטש שנה ב חוברת הע' 74, ושם לפנ\"ז: בעפאר זיין צוריק­רייזע נאך אייראפע, האט ער זיך געזעגענט מיט'ן אמעריקאנער אידענטום מיט פאלגענדן רוף: [ההמשך בפנים]."]]],[4301600326,"<h3>מוצש\"ק ט' מנ\"א ר\"ץ. יהפך לשמחה, ברלין<sup data-n=\"880\">1</sup>.</h3>\nהייתי אצל כ\"ק מו\"ח אד\"ש<sup data-n=\"881\">2</sup>. שכב על הספה. ספר ע\"ד אמירת ההפטרה בשבת ר\"ח מנ\"א (אם לאמר השמים כסאי או שמעו). פעם אמר אדנ\"ע \"השמים כסאי\", אבל כעבור שנים אחדות, ואירע עוד הפעם שר\"ח מנ\"א. אמר \"שמעו\". ואמר אדנ\"ע שמתחרט על אשר מלפנים אמר השמים כסאי<sup data-n=\"882\">3</sup>.\nשאלני, איך אתנהג בהנחת תפלין למחר. עניתי: עפ\"י המבואר בשו\"ע<sup data-n=\"883\">4</sup>, להניח במנחה. ויאמר לי שאניח בצנעא גם בבוקר (ובלבד שלא ירגישו בדבר) תפלין דרש\"י. וכן הי' נוהג אדנ\"ע, להניח בחדרו שלא יראו. ובעת שהתפללו — אמר תילים וכיו\"ב<sup data-n=\"884\">5</sup>.\nפעמים רבות שאלוני — את כ\"ק מו\"ח אד\"ש — עד\"ז, ולא גיליתי זה. הטלית — רק במנחה<sup data-n=\"885\">6</sup>.\nראה את אדנ\"ע לומד דא\"ח בט' באב, וכנראה למיגרס בעלמא<sup data-n=\"886\">7</sup>. פעם<sup data-n=\"887\">8</sup> אירע ערב ט' באב בש\"ק<sup data-n=\"888\">9</sup>. ואמר מאמר דא\"ח, אחר חצות היום. אלא שאז אמר עוד הפעם מאמר, שכבר אמרו, שכנראה לא הבינו אותו השומעים כל צרכו, בפעם הא'<sup data-n=\"889\">10</sup>.",[["880","1","מרשימות כ\"ק אדמו\"ר."],["881","2","בעת ההיא שהה רבינו בברלין, בדרך מסעו מארה\"ב לביתו בריגא (ראה אגרות­קודש ח\"ב ע' רנו. לעיל ב\"מבוא\" ע' עב)."],["882","3","קטע זה הועתק (בשינויים קלים) באגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"ג ע' שלב. ומסיים שם: \"ויעוין השקו\"ט בזה, בשו\"ע או\"ח סתכ\"ה ובנ\"כ. שערי אפרים ש\"ט סכ\"ב\". וראה גם לקוטי שיחות חלק יג ע' 278. וש\"נ. שיחת ש\"פ מסעי, ר\"ח מנחם­אב תשמ\"א."],["883","4","או\"ח ר\"ס תקנה."],["884","5","ראה ספר המנהגים ע' 47."],["885","6","בספר המנהגים שם: \"(משיחות כ\"ק מו\"ח אדמו\"ר): כ\"ק אאמו\"ר אדמו\"ר (מהורש\"ב) נ\"ע הי' לובש הטלית — בבוקר ופושטו, ואח\"כ לובש התפילין ומתפלל בהם כו'\". ובהערת כ\"ק אדמו\"ר שם: \"אולי י\"ל הטעם בלבישת הטלית גדול, אף שלא הי' מתפלל בו (ומצות ציצית הרי יוצא בט\"ק שעליו) — עפ\"י מ\"ש בשער הכוונות ענין ציצית דרוש ב' ודרוש ה' שגם ט\"ג צריך להניח קודם תפלין. ועיין שו\"ע או\"ח סכ\"ה ס\"ב ובב\"י שם בשם גדולי מקובלי ספרד. — ומה שבהנחת תפלין לק\"ש קטנה אין מקפידין על זה, י\"ל מפני שאז הנחת התפלין הוא רק בכדי שלא יהי' קורא ק\"ש בלא תפלין כו'. משא\"כ בשחרית ת\"ב שהי' מתפלל בהם כל התפלה\"."],["886","7","ראה רשימת היומן של רבינו בספר השיחות תורת שלום ע' 202: \"יום א' [י' מנ\"א] תשעה באב (נדחה) [תרע\"ד] בשעה 4 נכנסתי לכ\"ק אאמו\"ר הרה\"ק שליט\"א מצאתיו כותב דא\"ח, וכפי שראיתי התעסק אז בתיקון הדרושים שהגיד, והיינו לא שכתב כדרכו בהתעסקות בהענין שעומד בו, כ\"א בקונטרס ההגהות, ואפשר דהוי דבר האבוד\"."],["887","8","בין השנים תרמ\"ג­תרע\"ט — חל ערב ט' באב בש\"ק בשנות: תרמ\"ג. תרנ\"ו. תרנ\"ט. תרס\"ג. עת\"ר (ואמר אז מאמר ד\"ה איכה ישבה בדד — נדפס בסה\"מ עת\"ר ע' ריג ואילך)."],["888","9","כמו בקביעות שנה זו (תר\"ץ)."],["889","10","ראה עד\"ז בספר המנהגים ע' 46: \"בתשעה באב שחל בשבת ונדחה — אמר כ\"ק אדמו\"ר (מהורש\"ב) מאמר דא\"ח בזמן הרגיל (בליל שבת). נכנסו אליו ל\"חזור\" המאמר אחר סעודה המפסקת, ונמשכה החזרה בלילה\" (ובהערה 11 שם, שהמאורע הי' בשנת תרע\"ד, והמאמר, ד\"ה ציון במשפט, הוא מההמשך דזמן ההוא<sup data-n=\"e39\">*</sup> ואינו מדבר בעניני ת\"ב וכיו\"ב<sup data-n=\"e40\">**</sup>)."],["e39","*","נדפס בהמשך תער\"ב ח\"א ע' תקסד ואילך."],["e40","**","מאמר זה — אמר כ\"ק אדמו\"ר בשבת ערב תשעה באב תשמ\"א, וכן בשבת תשעה באב נדחה תשכ\"ד, לאחרי חצות היום. וביאר השייכות דתוכן המאמר — בענין האור — לת\"ב נדחה, לפי שדחיית וביטול הגלות הוא ע\"י אור (סה\"מ מלוקט ח\"ה ע' של)."]]],[4301600327,"ליל ט' באב כמעט שלא הי' אדנ\"ע ישן כל הלילה."],[4301600328,"<h3>ליל שבת פ' נצבים, ר\"ץ. ריגא. בסעודה<sup data-n=\"890\">1</sup>.</h3>\nספר: פעם הייתי מטייל עם אאדנ\"ע בשדה הי' זה בקייץ בדאַצע (כמדומני שאמר בבאַלעוקי. הכותב). הייתי אז כבן טו'. אאדנ\"ע הלך תפוש ברעיונותיו. פתאום חייך ואמר: וואָס אַ אנגעל אז. דער זיידע — הצ\"צ — כשהי' נער (כמדומה שאמר שהי' עוד קודם הברמ\"צ. הכותב) בכה פעם אחת בכי רב אַף דערוף אַז כל עשיותיו יהיו לש\"ש. והפסיק מעט — אאדנ\"ע — והמשיך דבורו: אויך אַ מדרגה! התנועה היתה — מדברי כ\"ק מו\"ח אד\"ש — שמילתא\nזוטרתא היא זה. אחרי הטיול באתי לעליתי, ששם הייתי לומד. ועפ\"י סדר הקבוע שהי' לי — הי' אז זמן קריאת זוהר. והפיסקא היתה מתחלת<sup data-n=\"891\">2</sup>: ר' יוסף ור' חייא הוו אזלי באורחא, ונמוגותי בדמעות<sup data-n=\"892\">3</sup>, בקראי<sup data-n=\"893\">4</sup>.",[["890","1","מרשימות כ\"ק אדמו\"ר."],["891","2","זוהר ח\"ג צג, ב."],["892","3","להעיר מזוהר שם: א\"ל את חמי ואנא חמינא מפומי' דר' שמעון שמענא מלה ובכינא."],["893","4","בשיחת ש\"פ חיי שרה תשט\"ו סיפר כ\"ק אדמו\"ר סיפור דומה ששמע מאדמו\"ר מהוריי\"צ בריגא, שבהיותו עם אביו כ\"ק אדמו\"ר מהורש\"ב נ\"ע במענטאן, הלכו לטייל על שפת הים, ואביו דיבר עמו בעניני חסידות, ולאחרי הטיול למד (אדמו\"ר מהוריי\"צ) מאמר הזהר ר' יוסי ור' חייא הוה אזלי על כיף ימא, והתמוגג בדמעות.\nובמכתב רבינו משנת תרפ\"ה (אגרות­קודש חי\"ד ע' תלז ואילך. רשימות כ\"ק אדמו\"ר — ילקוט — חוברת ט ע' 4 ואילך) דבחורף תרע\"ג כשהי' כ\"ק אדמו\"ר מהורש\"ב נ\"ע במענטאן \"נסעתי<sup data-n=\"e41\">*</sup> אז שם לבקרו. . והי' הסדר שהיינו הולכים על שפת הים, הרחק מאדם, יושבים בחול אשר על שפת הים, מדברים בענינים היותר עיונים. . והגיד לי כי שפת הים הוא מסוגל לענינים עיונים ביותר, והאריך לבאר מאה\"ז [=מאמר הזוהר] (בענין שמ\"ע [=שאו מרום עיניכם] בהקדמת הזוהר בתחלתו) רזא דא לא אתגליא בר יומא חד דהוינא על כיף ימא וכו'\"."],["e41","*","ראה שיחת יג תמוז תרצ\"ב."]]],[4301600329,"<h3>הנהגות<sup data-n=\"894\">1</sup></h3>\nסליחות ר\"ה עשי\"ת יוהכ\"פ סוכות שמע\"צ וש\"ת. רצ\"א ריגא.\n<b>הסליחות</b>\nהא' — במוצאי מנוחה — במוצש\"ק אחר חצות<sup data-n=\"895\">2</sup>. זכור ברית — באשמורת הבוקר. בער\"ה אין נופלים.\n<b>ר\"ה.</b>\nיה\"ר שאומרים על אכילת התפוח מתוק בדבש — אומרו בין הברכה לאכילה<sup data-n=\"896\">3</sup>.\nבברכת בפה\"ע שעל התפוח מכון להוציא גם הקאָמפאָט<sup data-n=\"897\">4</sup>.\nמלבד יה\"ר זה אין אומרים יה\"ר גם לא על אכילת הרמון.\nהר' הוא יחדש עלינו את השנה בברהמ\"ז הי' אדנ\"ע אומרו אבל בלחש<sup data-n=\"898\">5</sup>.\nברהמ\"ז בלא כוס<sup data-n=\"899\">6</sup>.\nבליל א' אינו מדבר מאומה — וכן הוא המנהג בכל שנה<sup data-n=\"900\">7</sup>.\nקודם תפלת מעריב (לילה הא') אמר תהלים בביהמ\"ד.\nתקע ר\"פ זאלמאנאוו<sup data-n=\"901\">8</sup> נ\"י. וכ\"ק מו\"ח אד\"ש אמר הפסוקים והברכות. לא הי' מַקריא — התקיעות — בדבור, רק מראה באצבע בסדור<sup data-n=\"902\">9</sup>.\nאחרי התפלה ואמירת תהלים (הנחלק לל' יום) בצבור<sup data-n=\"903\">10</sup> — צוה לתקוע הסדר דמיושב<sup data-n=\"904\">11</sup>.\nככל סדר זה גם ביום ב'.\nהעובר לפני התיבה במנחה ומעריב בלי טלית<sup data-n=\"905\">12</sup>, ואפי' בר\"ה (לבד מעריב",[["894","1","מרשימות כ\"ק אדמו\"ר."],["895","2","\"כנראה מפני שאומרים במוצאי מנוחה. ואין אומרים סליחות וי\"ג מדות קודם חצות לילה (מג\"א סתקכ\"ה סק\"ה)\" — הערת כ\"ק אדמו\"ר בספר המנהגים ע' 54."],["896","3","נתבאר בארוכה באגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"ג ע' קמ ואילך."],["897","4","כ\"ה גם בשיחת ליל א' דר\"ה תש\"ח (ומ\"ש בספר השיחות תש\"ב ע' 4. תש\"ה ע' 4 — ראה \"הערות וביאורים\" — ברוקלין, תשנ\"ג — גליון מב (תרמ) ע' 15 ואילך)."],["898","5","מנהגו של כ\"ק אדמו\"ר — כשמזמן בסעודת יום ב' דר\"ה — לומר \"הרחמן הוא יחדש כו'\" בקול רם ועונין אחריו אמן. וראה גם שיחת יום ב' דר\"ה תשט\"ז. ודלא כמ\"ש בשער הכולל פרק לד סי\"ד."],["899","6","להעיר מ\"היום יום\" יד כסלו."],["900","7","ראה ע\"ד הנהגת רבותינו נשיאינו בזה — שיחת כ' כסלו תרצ\"ג סעיף יד. ספר השיחות: תש\"א ע' 26 ואילך; תש\"ב ע' 2; תש\"ד ע' 3 ואילך; תש\"ה ע' 3."],["901","8","= ר' (שרגא) פייוויש (זאלמאנאוו). ראה אודותו לעיל ע' 33 ובהערה 28."],["902","9","ברשימת כ\"ק אדמו\"ר (\"היום יום\" חלק שני): \"אם מאיזה טעם אין אדמו\"ר התוקע אזי הוא ה\"מקריא\", אבל לא בדיבור, כי אם ע\"י הוראה באצבע בסידור\". וראה גם אגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"ה ע' קט."],["903","10","כפי תקנת רבינו ביום שמח\"ת תרפ\"ז (ספר השיחות תר\"פ­תרפ\"ז ע' 116). וש\"נ."],["904","11","ראה ספר המנהגים ע' 57."],["905","12","בנוגע לתפלת ערבית \"י\"א שישנה סכנה בדבר — הדעות בשע\"ת או\"ח סי\"ח. וראה ג\"כ פרמ\"ג שם. שו\"ת שם משמעון (סאטמאר, תרצ\"ב) מהדו\"ק או\"ח סי' א­ב\" (ממכתב כ\"ק אדמו\"ר שנעתק בספר המנהגים ע' 25 בהערה. אגרות­קודש שלו ח\"ה ע' צא ואילך. וראה לקמן הערה 23. וראה גם אגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"ט ע' ריד. חי\"ג ע' רכז. חט\"ז ע' צז ואילך. חי\"ט ע' רמט)."]]],[4301600330,"דיוהכ\"פ<sup data-n=\"906\">13</sup>. וכן הי' מנהג ליובאַוויטש.\nיו\"ט של ר\"ה שחל להיות בשבת אמרו ג\"כ יגמה\"ר (לקריאת התורה).\nתשליך — ביום ב'<sup data-n=\"907\">14</sup> (אחר המנחה קודם השקיעה) ואחר התשליך נער שוליו (כמדומה של הט\"ק<sup data-n=\"908\">15</sup>. מ\"מ).\n<b>אחר ר\"ה</b>\nאין אומרים סליחות<sup data-n=\"909\">16</sup>. כל עשי\"ת בקדיש \"לעילא\"<sup data-n=\"910\">17</sup>. בנעילה \"לעילא ולעילא\"<sup data-n=\"911\">18</sup>.\n<b>עריוהכ\"פ</b>\nשחרית הלך כ\"ק מו\"ח אד\"ש לא\"ז<sup data-n=\"912\">19</sup> הרבנית תי' בקש לעֶקאַח<sup data-n=\"913\">20</sup> וגם אכלו.\nיוהכ\"פ\nלפני תתקבל דקדיש האחרון דנעילה. אחר אמירת ד' הוא הא', מנגנים כל המתפללים נגון מעין מאַרש<sup data-n=\"914\">21</sup>.\nפתיחת הארון דנעילה מתחילת אשרי עד אחרי כל התפלה<sup data-n=\"915\">22</sup>.\nהתקיעה צ\"ל לפני תתקבל. בדוקא לפני תתקבל.\nאמר לי: בכריעה: תחלה כריעה על ברכיו וגודלי רגליו. אח\"כ על גודלי ידיו וההשתחואה (מתקומם מברכיו.",[["906","13","לכאורה צ\"ל כאן סיום החצאי­עיגול."],["907","14","כשיום א' דר\"ה חל להיות בשבת. — ראה בארוכה שיחת ו' תשרי תש\"ל דאף שאדה\"ז (הן בשלחנו [או\"ח סתקפ\"ג ס\"ז], והן בסידורו) אינו מחלק בין ר\"ה שחל בחול או בשבת, וכותב שביום אדר\"ה הולכים לתשליך, בכ\"ז בדורות האחרונים — כשראו שישנם כאלה שהלכו לתשליך בשבת ומתוך שכחה או קלות הדעת, הביאו עמם סידור — הפסיקו את המנהג ללכת בתשליך בשבת.\nראה פרמ\"ג (משצב\"ז) או\"ח סתקפ\"ג סק\"ג. ועוד."],["908","15","וכ\"ה (שולי הט\"ק) בספר המנהגים ע' 57. ובהגהות כ\"ק אדמו\"ר מהורש\"ב נ\"ע לסידור תורה אור (נעתק בספר המנהגים שם בהערה): כתוב בפע\"ח שער השופר פ\"ה וינער שולי הבגדים כשאומרים ותשליך במצולות ים כו' ובסדור האריז\"ל מהר' שבתי ז\"ל כ' דדוקא בגד ציצית כי היא בגד השכינה וכן בסי' שער השמים מהשל\"ה כ' דדוקא בגד ציצית וכן מנהגינו, לנער את הט\"ק אך אחר שגומרים את סדר התשליך וכ\"נ מסדור השל\"ה ז\"ל."],["909","16","ראה גם לקמן ע' 144."],["910","17","בספר המנהגים ע' 60 \"לעילא מן כל — כמו בכל השנה\" ובהערת כ\"ק אדמו\"ר שם: \"הגהת הצ\"צ בסידורו (נדפס בסי' תורה אור)\"."],["911","18","\"הוראת כ\"ק מו\"ח אדמו\"ר וכ\"כ בד\"ה היתה כאלמנה תרל\"ד [סה\"מ תרל\"ד ע' רפד]\" — הערת כ\"ק אדמו\"ר בספר המנהגים שם (וראה לקמן הערה 22)."],["912","19","= לאמי זקנתי (של כ\"ק אדמו\"ר. הרבנית הצדקנית מרת שטערנא שרה ע\"ה ז\"ל, אמו של כ\"ק אדמו\"ר מהוריי\"צ. — רשימתו אודותה נדפסה בספר השיחות תר\"פ­תרפ\"ז ע' 13 הערה 12)."],["913","20","ע\"ד מנהג זה — ראה לעיל ע' 26. ספר השיחות: קיץ ה'ש\"ת ע' 11. תש\"ה ע' 21. תש\"ז ע' 64. שיחת ערב יוהכ\"פ תשי\"א (התוועדויות תשי\"א ח\"א ע' 9). ש\"פ האזינו תש\"נ (התוועדויות תש\"נ ח\"א ע' 83 ואילך. וש\"נ)."],["914","21","בשיחות תשרי תרצ\"ג (ברשימות כ\"ק אדמו\"ר): \"בשנת נט' התחילו לנגן. . נאַפּאָלעֶאָנס מַרש. תמיד היו מנגנים במקום זה, אצל אדה\"ז וכו'. . אלא שבשנת נט' צוה אדנ\"ע שינגנו מַרש זה\". וראה רשימת רבינו בספר השיחות תורת שלום ע' 210."],["915","22","בספר המנהגים ע' 64: לנעילה פותחין הארון ונשאר פתוח עד לאחר כל התפלה, כן אומרים בקדיש לעילא ולעילא כנ\"ל. ובהערת כ\"ק אדמו\"ר שם: \"הוראת כ\"ק מו\"ח אדמו\"ר. — וכיון שסילוק שכינה הוא בהתקיעה — נראה לי שעד התקיעה חלים שתי הוראות אלו\"."]]],[4301600331,"במצחו מגיע עד הרצפה ונשאר עומד על אצבעות רגליו וגודלי ידיו. מ\"מ).\nמוציוהכ\"פ.\nקדוש לבנה בסדור ובחגירת האבנט.\nתפלת המעריב — בשליאַפּעֶ<sup data-n=\"916\">23</sup>.\nברהמ\"ז דסעודת מוציוהכ\"פ — על כוס של יין. אמר שבברכתו על הכוס ש\"ב — בפה\"ג — אין יוצאים השומעים. וכ\"א יברך לעצמו (מלשונו הי' משמע שכן הוא תמיד בברכת כוס של ברכה<sup data-n=\"917\">24</sup>. הכותב).\nאין מברכין שעש\"ל כל צרכי עד למחרתו<sup data-n=\"918\">25</sup>.\nאמר לי: במוציוהכ\"פ היו מדברים ע\"ד הסוכה<sup data-n=\"919\">26</sup>. \"זאָגען מענדל'ן אַז מ'דאַרף וכו'[\"].\nסוכות.\nבלילה הראשונה נתן לי ב' אתרוגים מקאַלאַברי וא\"י<sup data-n=\"920\">27</sup>. באמרו: כן נתנו גם לי. וצוני לברך בתחלה על הקאל'<sup data-n=\"921\">28</sup> ואח\"כ לנענע עוד הפעם גם בשל א\"י<sup data-n=\"922\">29</sup>. ולא לפרסם עד\"ז עכ\"ל.",[["916","23","בספר המנהגים ע' 59: תפלת מעריב והבדלה, בקיטעל וטלית, אבל בכובע (ולא ביארמולקע) והטלית על הכתפים. ובהערת כ\"ק אדמו\"ר שם: \"מובן עפמש\"כ בשער הכוונות ש\"ו תפלת מנחה ד\"א<sup data-n=\"e42\">*</sup>: אם הי' רואה (האריז\"ל) שכבר שקעה החמה הי' מוריד הטלית בין כתפיו משום דלילה לאו זמן ציצית הוא וכשהוא בין כתיפיו אין חשש אם הוא לילה. וראה נ\"כ השו\"ע או\"ח סי\"ח\". וראה גם לעיל הערה 12."],["917","24","להעיר מאגרות­קודש כ\"ק אדמו\"ר שליט\"א חי\"ד ס\"ע כט: \"ובפרט כשהעם רב — וכמו בכוס של ברכה בסעודה, התוועדות וכיו\"ב — שמפני אריכות הזמן בין שמיעת הברכה לשתיית הכוס ע\"י כל השומעים קשה להזהר מהפסק. ולכן יש להנהיג דוקא מנהג ההוא, ז.א. שכל אחד ואחד יברך לעצמו ברכת הנהנין\"."],["918","25","ראה גם לקמן ע' 147."],["919","26","ראה גם התוועדויות תש\"נ ח\"א ע' 105."],["920","27","= וארץ ישראל."],["921","28","בספר המנהגים ע' 65: מברכים על אתרוג מקאלאברי (הנק' ג\"כ \"יאנאווער\"). ובהערת כ\"ק אדמו\"ר שם: \"קבלה בידינו מאדמו\"ר הזקן — בעל התניא והשו\"ע — להדר אחר אתרוגי קאלאברי — יאנאווע \"מטעם הידוע לו\". ואמר: כאשר אמר הקב\"ה למשה ולקחתם לכם פרי עץ הדר גו' הושיבו שלוחים על ענן ושלחום להביא אתרוגים מקאלאבריא (ראה ג\"כ שיחת שמע\"צ שמח\"ת ה'שי\"ת [סעיף ז] הנדפסת בקונטרס פה [סה\"מ תשי\"א ע' 101]).\nוראה בשו\"ת חת\"ס חאו\"ח סר\"ז: דינו של אתרוג כדין עוף טהור שאינו נאכל אלא במסורת ע\"כ אותם הבאים מיאנאווא שמסורת בידינו מאבות אבותינו ורבותינו חכמי הצרפתים אשר מעולם יושבי מדינת אשכנז יוצאים ידי חובתם באתרוגים הבאים מיאנאווא, הן הנה הכשרים וא\"צ שום סימן כו'. ובשו\"ת בכורי שלמה סכ\"ח אשר הרה\"צ מטשע­כאנאוו הי' מברך רק על אתרוג מיאנאווא וכ\"כ בס' תולדות שלמה על המהרש\"ק\". וראה גם שיחות תשרי תרצ\"ג (ברשימות כ\"ק אדמו\"ר). ספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 294. וש\"נ. אגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"ג ע' רפ. ח\"ד ע' כד. ועוד."],["922","29","ראה שיחות תרצ\"ג שם. ובשיחת יום שמח\"ת ה'שי\"ת שם: אפילו אין די ימי המהפכה רח\"ל, וואס עס איז געווען שווער צו באקומען א אתרוג, האט מען געלייגט גרויס השתדלות אויף א קאלאברער, און מען האט זיך אויך משתדל געווען אויף א ארץ ישראל אתרוג. ובאגרות­קודש אדמו\"ר מהורש\"ב ח\"א ע' סג: ואתרוג א\"י [=ארץ ישראל] הי' אצלו [אצל אדמו\"ר מהר\"ש] פ\"א ולא בירך עליו כ\"א בעת הלל נטלו. ולהעיר ממכתב אדה\"ז להרה\"ק רלוי\"צ מבארדיטשוב מיום ד' לך תקס\"ד (אגרות­קודש שלו ח\"א ע' ריג): שמעתי שכ\"ק י\"נ קבל מא\"י תוב\"ב ב' אתרוגים על החג העבר מאוד נפלא בעיני על אשר לא שלח לי א' כדרכו בקודש."],["e42","*","בכמה דפוסים: ענין תפלת שחרית בסופה."]]],[4301600332,"בליל ב' — שהחיינו ואח\"כ לישב בסוכה<sup data-n=\"923\">30</sup>.\nהבדלתי על היין וציוני לברך גם לישב בסוכה (אלא שהי' בדעת — וכן הי' — לאכול אח\"כ סעודת הערב).\n[הבדלתי על השכר וציוני לא לברך לישב בסוכה (אטואצק רצ\"ז)].\nבקדוש היום מברך לישב בסוכה על היין<sup data-n=\"924\">31</sup> וגם בשבת חהמ\"ס עושה כן.\nהד' סעודות של יו\"ט ברהמ\"ז בכוס של ברכה.\nכשמברך בעשרה מתקומם מעט מכסאו באמרו \"אל'\" שאכלנו משלו וכו'.\nאוחז הכוס מורם בידו עד אחרי \"ירושלים אמן\" ואח\"כ מעמידו על השולחן.\nבש\"ק ג\"כ נ\"כ אבל לא יגמה\"ר לבד בר\"ה ויוהכ\"פ.\nבמענה על שאלתי: כשנותנין לאחר — הד\"מ — לברך לאמר בפירוש שנותן במתנה עמלה\"ח<sup data-n=\"925\">32</sup>. \"ובפרט ביום א'. והוא תועלת לנותן ולמקבל\"<sup data-n=\"926\">33</sup>.\nאוגד הלולב בסוכה דוקא<sup data-n=\"927\">34</sup>. ומקפיד לאוגדו עיו\"ט.\nעל הלולב ב' כריכות ואוגדו עוד בג' מקומות ביחד עם ההדסים וערבות. ס\"ה בה' מקומות<sup data-n=\"928\">35</sup>.\nאמר לי: באורך הלולב מהדרים שיהי' לכה\"פ יא' טפחים<sup data-n=\"929\">*35</sup>.\nאינו שותה חוץ לסוכה<sup data-n=\"930\">36</sup>.\nב' הכריכות מכוסים בהדסים וערבות. גם העליונה במעט עכ\"פ.\nגם כל חוהמ\"ס לבוש משי<sup data-n=\"931\">37</sup>.\n[הנענועים<sup data-n=\"932\">38</sup>: מ' — לאמצע המזרח. דו\"צ — לקרן מזרחית דרומית ומז' צפ',",[["923","30","\"ראה הגהות כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע שנדפסו בסידור תורה אור (ברוקלין, תש\"א) ע' רלג, ובסידור עם דא\"ח. וראה הדעות בזה בנ\"כ השו\"ע סתרס\"א. שד\"ח מע' סוכה סימן א ס\"ק ה\" — הערת כ\"ק אדמו\"ר בספר המנהגים ע' 67. וראה גם שיחת ליל ב' דחגה\"ס תרפ\"ט ס\"א (לעיל ע' 29). אגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"ה ס\"ע ו ואילך."],["924","31","ראה גם ספר השיחות תרצ\"ו — חורף ה'ש\"ת ס\"ע 295."],["925","32","= על מנת להחזיר."],["926","33","\"ראה או\"ח סתרנ\"ח. חו\"מ סרמ\"א. והספרים שהובאו בשד\"ח אסיפת דינים מע' ד' מינים סימן ג ס\"ק יט\" (הערת כ\"ק אדמו\"ר בספר המנהגים ע' 66)."],["927","34","ראה ספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 294. תש\"ח ע' 193. ד\"ה נשא תשמ\"א. לקו\"ש חכ\"ב ע' 129 הערה 55."],["928","35","\"ראה ט\"ז ריש סתרנ\"א. השלמת שו\"ע רבינו הזקן (למהר\"ן מדובראוונע) שם. ס' חיים וברכה ס\"ק רפח\" (הערת כ\"ק אדמו\"ר בספר המנהגים שם)."],["929","*35","ברשימות דברי רבינו מתשרי תרצ\"ז: מה שאמרתי לך בשיעור הלולב יא' טפחים אינו בגשמיות."],["930","36","בלקו\"ש חכ\"ט ע' 211 מציין על זה: ראה משנה סוכה כו, ב. רמב\"ם הל' סוכה פ\"ו ה\"ו. טושו\"ע או\"ח סתרל\"ט ס\"ב. שו\"ע אדה\"ז שם סי\"ב."],["931","37","ע\"ד לבישת בגדי משי בשבת ויו\"ט — ראה לקמן ע' 145 ובהערה 17. וש\"נ."],["932","38","בספר המנהגים שם: הנענועים: דרום וצפון — לקרן דרומית מזרחית, קרן צפונית מזרחית. למזרח — לאמצע המזרח. למעלה — בהובאה מורידים תחילה מעט \"המשכה בעולם\", ואח\"כ מביאים אל החזה. למטה — בהובאה מעלים תחילה מעט \"העלאת העולם\", ואח\"כ מביאים אל החזה. מערב — שתי פעמים הראשונות לקרן מערבית דרומית. בפעם השלישית — לאמצע מערב.\nכל זה (י\"ז נענועים), בכלים. בנענוע האחרון — אור. יחוד שכינה במערב.\nבמשך כל הנענועים האתרוג מכוסה בידו — לבד בנענוע האחרון שמגלהו קצת."]]],[4301600333,"ולא לצדדין. למעלה — בהובאה תחילה מורידים מעט המשכה בעולם ואח\"כ אל החזה. למטה — בהובאה תחלה מעלים מעט. העלאת העולם. ואח\"כ אל החזה. מערב — ב\"פ לקרן דר' מע'. כ\"ז בכלים<sup data-n=\"933\">39</sup>. האחרונה — לאמצע מערב. אור, יחוד שכינה במערב. ומגלים מעט מהאתרוג (בהג') שרק הוא מכוסה. הלולב מחברו לשליש העליון של האתרוג. באמת<sup data-n=\"934\">40</sup> הי' צ\"ל על האתרוג אלא שמפני טעם אין עושים כן.\nלקח יג' הדסים<sup data-n=\"935\">41</sup>. רצ\"ה].\n<b>שחוהמ\"ס.</b>\nאמר לי: במוצשחוה\"מ אין אומרים ויתן לך. וכן אין אומרים שלום עליכם, אחעט\"ב<sup data-n=\"936\">42</sup>, מזמור לדוד ודא היא סעודתא בין בשחוה\"מ, בין בשבת ויו\"ט<sup data-n=\"937\">43</sup>. עיין לקמן<sup data-n=\"938\">44</sup> מוצשחוהמ\"ס.\n[רצ\"ג אמר תהלים — ליל הו\"ר — באבנט. וכן רצ\"ה.\nבהו\"ר קודם הלל<sup data-n=\"939\">45</sup> מסירין ב' האגודות — שעל הלולב, ונשארין רק הג' שעל הג' מינים<sup data-n=\"940\">46</sup>.\nבליוב' הי' מסיימין תילים במשך 54<sup data-n=\"941\">*46</sup> שעה ואדנ\"ע הי' מסים כל קאפיטל קודם הש\"ץ].\n<b>שמע\"צ.</b>\nהסדר של הנאספים: קדוש מעריב הקפות והסעודה. ליל שמח\"ת מאמר דא\"ח, מעריב קדוש פאַרברייֵנגעֶן הקפות והסעודה.\nיום שמח\"ת: תפלה, הקפות בקצור, מוסף, קדוש, מנחה, הסעודה.\nאתה הראית: שמע\"צ — ג' פעמים. ליל שמח\"ת — ב' פעמים. יום שמח\"ת — א'<sup data-n=\"942\">47</sup>.\nבב' הלילות הולך בהקפה הא' והז'<sup data-n=\"943\">48</sup>.\nביום מקיפים התיבה רק שלשה פעמים ובפעם הד'<sup data-n=\"944\">49</sup> רוקדים (אומרים כל סדר ההקפות גם ביום). ההולכים להקפה הא' מקיפים כל הג\"פ.",[["933","39","= כל זה (י\"ז נענועים), בכלים. — כבהערה הקודמת."],["934","40","בהערת כ\"ק אדמו\"ר בספר המנהגים שם מציין על זה: \"משיחות כ\"ק מו\"ח אדמו\"ר בריגא\"."],["935","41","ע\"ד הוספה על שלשה הדסים, ושינויי המספרים בזה — ראה ספר המנהגים ע' 65 ובהנסמן שם. שיחות תשרי תרצ\"ג. תרצ\"ז (ברשימות כ\"ק אדמו\"ר). ספר השיחות תש\"ד ס\"ע 13. שיחת ערב חג הסוכות תשכ\"ח (לאנשי כפר חב\"ד). שיחת ש\"פ האזינו, י\"ג תשרי תשנ\"ב. וראה גם ר\"ד בעת סעודת ליל א' דחג הסוכות תשכ\"ט (ספר \"המלך במסיבו\" ח\"א ע' רנ. וש\"נ)."],["936","42","= אשת חיל (עטרת בעלה. — הסיום הוא כנראה מצד שייכות תוכן הענין)."],["937","43","אבל ב\"היום יום\" י\"ט ניסן; י\"ז תשרי (ובספר המנהגים ע' 38. ע' 56) — שאומרים כל זה בלחש."],["938","44","ע' 151."],["939","45","\"ודלא כמשמע בסי' היעב\"ץ\" (הערת כ\"ק אדמו\"ר בספר המנהגים ע' 68)."],["940","46","נתבאר בשיחת ליל שמח\"ת תשח\"י (נדפסה בהוספות ללקו\"ש ח\"ד ע' 1368)."],["941","*46","בספר השיחות תש\"ח ע' 171: אמירת תהלים בליובאוויטש נמשך. . לערך שעה ורבע."],["942","47","להעיר שבביהכנ\"ס של כ\"ק אדמו\"ר — \"בית רבינו שבבבל\" — נוהגים לומר אתה הראת ג' פעמים, הן בשמע\"צ והן בשמח\"ת."],["943","48","ראה ספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 77, שכך נהג אדמו\"ר הזקן."],["944","49","כנראה הכוונה להחצי פעם הנוספת — כבספר המנהגים שם: \"ביום שמחת תורה — שלש פעמים וחצי\". ובהערת כ\"ק אדמו\"ר שם: \"ראה נמוקי או\"ח סתרס\"ט אשר מנהג בהכ\"נ הישנה בקראקא — שנודע יושנה בערך תשע מאות שנה — ומנהג ביהכ\"נ רמ\"א, לעשות ג' הקפות וחצי (הן בלילה הן ביום)\"."]]],[4301600334,"בשנה זו הי' חתן בראשית.\n[רצ\"ג — חתן בראשית (לא חכה אצל הבימה עד שעלה המפטיר. ואולי מפני שהי' חלוש).\nבעליתו לתורה מורה ונוגע בטליתו לא רק בתחילת הפרשה שיקראו אלא גם במקום סוף הקריאה<sup data-n=\"945\">50</sup>. וכן עושה גם בש\"ק].",[["945","50","ראה \"היום יום\" ד אלול. \"ודלא כיש נזהרים (הובאו דבריהם בס' שערי תמים ובס' שערי חיים על השערי אפרים שער ד' ס\"ק ג וס\"ק יז) לנגוע רק בגליון היריעה\" (הערת כ\"ק אדמו\"ר בספר המנהגים ע' 13)."]]],[4301600335,"<h3>ר\"ה רצ\"א. ריגא<sup data-n=\"946\">1</sup>.</h3>\nספר: מהרשנ\"ע הי' מהדר לתקוע ארבעים ושנים שברים­קטנים בתרועה<sup data-n=\"947\">2</sup>. והשברים שלשה לכל היותר ארבעה<sup data-n=\"948\">3</sup>.\nהרוזיִנער הי' הולך לתשליך לא בר\"ה כ\"א י\"ג מדות (ד' דעשי\"ת). בהיותי בארצה\"ב — ניו יארק — אשתקד הלכתי לתשליך ימים אחדים לפני ר\"ה, במוצאי ר\"ה ולי\"ג מדות<sup data-n=\"949\">4</sup>.\nהצ\"צ הי' אומר י\"ג מדות. הרבנית נ\"ע<sup data-n=\"950\">5</sup> (אשת מהרשנ\"ע) היתה אומרת ג\"כ והי' בשבילה מנין מיוחד. כי אדנ\"ע לא הי' בא אל המנין לאמר (אם אמר ביחידות, א\"י. אבל כנראה מדברי כ\"ק מו\"ח אד\"ש מבין השיטין, שגם ביחידות לא אמרו סליחות אחרי ר\"ה)<sup data-n=\"951\">6</sup>.",[["946","1","מרשימות כ\"ק אדמו\"ר."],["947","2","בספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 253: ידוע הי' לאאזמו\"ר (אדמו\"ר מהר\"ש) א לאנגער אטעם לנגינה, ער פלעגט קענען מאכן ביז 53 תרועות מיטן גרויסן שופר. ובספר השיחות תש\"א ע' 28: הוד כ\"ק אאזמו\"ר מוהר\"ש פלעגט בלאזן א תרועה 42 טרומייטן [בספר התולדות אדמו\"ר מהר\"ש (קה\"ת, תש\"ז) ע' 67 מעתיק שיחה הנ\"ל דשנת תש\"א בשינויים, וז\"ל: בא דעם רבי מהר\"ש פלעגט מען בלאזען א תרועה 42 טרומייטן און בא דעם אלטן רבי'ן פלעגט מען בלאזען 63]. ובספר השיחות תש\"ד ע' 136 (הועתק בספר התולדות שם ס\"ע 73): הוד כ\"ק אאזמו\"ר מוהר\"ש האט געהאט א לאנגען אטעם. בא תקיעת שופר פלעגט ער אין די תרועה מאכן 72 קולות. וראה שו\"ע אדה\"ז סתק\"צ ס\"ד: בתרועה יכול להאריך בטרומיטין כמה שירצה. . יכול לעשות כמה שירצה."],["948","3","מנהגו של כ\"ק אדמו\"ר — לתקוע שלשה שברים ומחצה. וראה אגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"כ ע' לט."],["949","4","ברשימת רבינו ממוצאי ראש השנה תר\"ץ: \"נוסעים אנחנו אל חוף הים, כי לילך אל נהר לתשליך לא הי' אפשר מפני ריחוק המקום, וחפצתי לראות מים חיים במוצאי ר\"ה, ולתשליך ניסע ביום ה' בשלש עשרה מדות\". וברשימתו מיום ה', ו' תשרי תר\"ץ: \"הנני נוסע אל חוף הים, תשליך\". ראה גם לעיל ב\"מבוא\" ע' מד."],["950","5","הרבנית הצדקנית מרת רבקה נ\"ע. ראה אודותה לעיל ע' 26 הערה 13."],["951","6","באגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"ב ע' רנב: \"הנני מעתיק בזה מרשימותי תשרי תרצ\"א ריגא, ותשרי תש\"ח ברוקלין\", ולאחרי העתקת ב' הקטעים הנ\"ל (משיחות ר\"ה תרצ\"א) מוסיף ומעתיק משיחות תשרי תש\"ח (נדפס גם בספר השיחות תש\"ח ע' 164:\n\"אשת מהרשנ\"ע, חמותה אשת הצ\"צ וכן אשת אדהאמ\"צ היו אומרות סליחות בעשי\"ת, אבל לא האנשים.\nסיפר אאזמו\"ר (מהרשנ\"ע) לאאמו\"ר, אשר פעם בראותו שאמו הלכה לסליחות — בעשי\"ת — ואביו (הצ\"צ) זיצט און לערנט, שאל אותו עד\"ז. ויענהו הצ\"צ: עס איז דא א צייט ווען מען דארף זאגען און עס איז דא א צייט ווען מ'דארף טאן.\nבמענה על שאלתי שכתוב לאמר סליחות בצו\"ג, ענה כ\"ק מו\"ח אד\"ש: צום גדלי' איז דאך פון די ד' צומות\"."]]],[4301600336,"<b>מוצאי ר\"ה, בסעודת הלילה.</b>\nספר: כשהייתי בן ח' שנה הייתי בקי בסדרי זרעים ומועד<sup data-n=\"952\">7</sup> תורה<sup data-n=\"953\">8</sup> נביאים ראשונים וישעי'. יחזקאל הי' קשה לי לחזרו ע\"פ. בירמי' הייתי ממעט מפני שהוא \"מ\"ש<sup data-n=\"954\">9</sup> עצבות\". אדנ\"ע הי' בוחן אותי והוא רואה בספר.\nהאײַנפיִרעֶן איִן חדר<sup data-n=\"955\">10</sup> — ואני בן שלשה.\nכשבא אאדנ\"ע מנסיעתו (על משך שנים אחדות לחו\"ל) לא הכרתיו<sup data-n=\"956\">11</sup>.\nמוצאי ר\"ה רס\"א, היו מאמרי דא\"ח תקעו ומן המיצר<sup data-n=\"957\">12</sup>, נכנסתי אל אאדנ\"ע. אמר לי \"מ'דאַרף דאָך וויִסען\". \"מאָרגעֶן איִן דעֶרפריִ, וועֶסט מיִר ברייֵנגעֶן אַ הַנחפּה. איִך וויִל גאָרניִט וויִסעֶן\" וכתבתי ההנחות כל הלילה.\nפעם<sup data-n=\"958\">13</sup> אחת קראני אאדנ\"ע — (והי' אז כבן ד' וה'. הכותב) וצוני לברך על הציצית. עניתי שכבר ברכתי. האָט עֶר מיִר<sup data-n=\"959\">14</sup>. . . התחלתי לבכות, באמרי: פאַר וועמעֶן דאַרפען בעֶנצ'עֶן ציצית. פאַר דעם אויבעֶרשטעֶן, אָדער פאַר דעם טאַטען. . . אויב דו וועֶסט מיִר זאָגען, אַז פאַר דעם טאַטען, וועל איִך בעֶנצ'ען. . . באותו מעמד, לא ענה לי דבר ע\"ז. אבל כעבור איזה ימים, איני זוכר בבירור כמה, אבל שבת ודאי היתה באמצע. אמר לי: בעֶנצ'ען דאַרפען פאַר דעֶם אויבעֶרשט' אָבעֶר ביִז וואַנעט מעֶן וועֶרט אַ בַר­דַעת, איִז דער טאַטע אַ מַשגיִח. און פון אַ מַשגיח טאָר מען גאָרניִט באַהאַלטעֶן. און דאָס האָב איִך דיִר<sup data-n=\"960\">15</sup> ניִט פאַר דעם בעֶנצ'ען, נאר פאַר ניִט פאלגעֶן דעֶם מַשגיִח.\nמהרשנ\"ע הי' לומד לפרקים עם אאדנ\"ע. ובלבד שלא ירגישו בדבר, מפני קנאת אחים<sup data-n=\"961\">16</sup>. פעם אחת בחורף בליל מוצש\"ק, שעה ה' לערך. כשנכנס אליו אאדנ\"ע. אמר לו מהרשנ\"ע: אַביִסעל שפּעטעֶר. אַז מעֶן וועט אויפהעֶרען אַרומדרייֵען זיִך. ויצא אאדנ\"ע לחדר הסמוך לחכות. והוא עודנו בבגדי שבת, בגדי משי וכובע עגול — (על שאלתי בזה: מתחיל מהברמ\"צ, היו לובשים בגדי משי, בשבת<sup data-n=\"962\">17</sup>. ומהחתונה — כובע עגול.",[["952","7","ראה גם רשימת היומן של רבינו מיום ד', ה' תשרי תרנ\"ב (סה\"מ תשי\"א ע' 295 ואילך)."],["953","8","ראה לקמן ע' 220 ובהערה 101."],["954","9","= מרה שחורה."],["955","10","ראה — ע\"ד ה\"הכנסה לחדר\" של רבינו — ספר השיחות תש\"א ס\"ע 29. ובספר השיחות קיץ ה'ש\"ת ע' 67 ע\"ד ה\"הכנסה לחדר\" של אדמו\"ר הצ\"צ."],["956","11","ראה רשימת המאסר (ספר השיחות תר\"פ­תרפ\"ז ע' 241): \"משנת תרמ\"ז עד תרמ\"ט לא ראיתי את הורי, כי נסעו לחו\"ל למעינות שונים, והתעכבו שם כל משך זמן זה מסיבות שונות, מצד הבריאות וביותר מסיבות בייתיות. ורק לפעמים באו על ימים אחדים. ותנאי חיי במשך שתי השנים השביתו מלבי זכרון אבא מקדם\"."],["957","12","נדפסו בסה\"מ תרס\"א ע' קסא ואילך (ושם: המאמרים דר\"ה הם תקעו וכבוד מלכותך, ומן המיצר בש\"ת)."],["958","13","ראה גם לקו\"ש ח\"ב ע' 504. תורת מנחם — התוועדויות ה'שי\"ת ע' 4."],["959","14","כאן הושמטה תיבה."],["960","15","בכי\"ק יש כאן מקום חלק."],["961","16","ראה גם שיחת ב' ניסן תש\"ח (סה\"מ תש\"ח ס\"ע 175. ספר השיחות תש\"ח ע' 196)."],["962","17","ע\"ד לבישת בגדי משי בשבת ויו\"ט — ראה המשך תער\"ב ח\"ב ס\"ע תתעב ואילך. תרס\"ב ע' רלא בשוה\"ג (וסיום הענין שם ס\"ע שמז). ד\"ה זה יתנו תש\"כ (סה\"מ תש\"כ ע' 87). ר\"ד יום ה', כד תשרי תשי\"א (תורת מנחם התוועדויות תשי\"א ח\"א ע' 53. וש\"נ). שיחת פורים תשט\"ו."]]],[4301600337,"הכותב). — וחכה שם כל הלילה. מפני קלקול התנור בחדר זה, לא היו מסיקים שם. בבוקר בשעה חצי השמינית, כשפתח מהרשנ\"ע דלת חדרו, לשמוע אם כבר התחילו אנשי המנין להתאסף. ראה את אאדנ\"ע, וישאלהו מה זה. ויענהו: האָסט געזאָגט, איִך זאָל אַביִסעל צו וואַרטעֶן.. .\nבגדי משי לבן הי' לובש גם מהרשנ\"ע, ובלבד לעתים מיוחדים. בש\"ק רק פעמים מספר.\n<b>אור לח' תשרי.</b>\nספר: בתניא דפוסים הישנים, נדפס אגה\"ת מהד\"ק<sup data-n=\"963\">18</sup>. ישנו כי\"ק מהרי\"ל<sup data-n=\"964\">19</sup> אחי אדהזנ\"ע עם הג' ותקונים מאדהזנ\"ע, אבל איני זוכר אם מהד\"ק או מהד\"ת<sup data-n=\"965\">20</sup>.\nהתניא מתר\"ס הוגה ע\"י אאדנ\"ע בעצמו<sup data-n=\"966\">21</sup>.\n<b>שחרית עיוהכ\"פ.</b>\nהלכתי עמו לא\"ז הרבנית תי'. בקש ממנה \"לעקאַח\"<sup data-n=\"967\">22</sup> וגם אכלו.\nספר<sup data-n=\"968\">23</sup>: בליובאַוויִץ אור לעיוהכ\"פ, משעה 8­8 בערב, לא הי' צריך להיות איש מאנשים זרים בביתי. בפ'עֶרעֶדניעֶ<sup data-n=\"969\">24</sup> היו אנשים, אבל לא בחדרים.\n9 לערך, אכלו ארוחת הערב. 3­2 הי' אאדנ\"ע קם משנתו. כפרות הי' 520 לפנות בוקר, כל אותם השנים שהנני זוכר, בזה הזמן.\nבקומו — 3 בלילה — הי' לומד פרע\"ח השייך ליוהכ\"פ, וגם שותה כוס תה. למודו הי' מסיים — פאַרבײַסעֶן — בעץ חיים. יושב בקרעסלא<sup data-n=\"970\">25</sup> וחושב הרבה.\nבשעה 6­6, אחרי הכפרות, השו\"ב הי' נכנס לחדרו — כנראה, שהי' נותן לו כסף, וגם משוחח עמו —\nהולך אל המקוה. — (רק פעם אחד במשך כל היום<sup data-n=\"971\">26</sup>. רק שנה אחת, אני זוכר, שהלך שתי פעמים).\nמתפלל. ובכלל עריוהכ\"פ שחרית הי' שמח. פרייֵליִך.\nבשחרית, אחרי הכפרות, הי' לובש בגדי משי וגם מצוה לי ללבוש.\nבשעה 12 הי' אומר תילים.\nמלקות לפני מנחה.\nמנחה וכל הסדר.",[["963","18","בהוצאות: זאלקווא, תקנ\"ט. זאלקווא, תקס\"ה. לעמבערג, תר\"ך. וראה ביבליוגרפי' לספר התניא (קה\"ת, תשמ\"ב) ע' 16, ובהמצויין שם."],["964","19","ראה אודותו לעיל ע' 68 הערה 31."],["965","20","צילום הכי\"ק נדפס בליקוט פירושים וכו' לאגה\"ת (קה\"ת, תשמ\"ו) בתחילתו. וע\"פ מ\"ש כאן שהוא כי\"ק מהרי\"ל — יש לתקן מ\"ש בביבליוגרפי' לספר התניא (ע' 18) ובליקוט פירושים שם שהוא, כנראה, כי\"ק של אדמו\"ר האמצעי."],["966","21","ראה ספר השיחות קיץ ה'ש\"ת ס\"ע 109: \"הגהת התניא בערך שנה ומחצה. הותחל תרנ\"ח נדפס תר\"ס\". וראה גם אגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"ה ע' ער. רצה."],["967","22","ראה לעיל ע' 140. וש\"נ."],["968","23","בהבא לקמן — ראה גם שיחות תשרי תרצ\"ג (ברשימות כ\"ק אדמו\"ר). שיחת חג הפסח תרצ\"ד סעיף כג. ספר השיחות תרצ\"ו — חורף ה'ש\"ת ס\"ע 155. קיץ ה'ש\"ת ע' 10. תש\"ב ע' 87. תש\"ה ע' 21."],["969","24","= חדר כניסה (פרוזדור)."],["970","25","= כורסה."],["971","26","ראה ספר השיחות תש\"ה שם. תש\"ז ע' 63. וראה גם רשימת רבינו בספר השיחות תורת שלום ס\"ע 209 ואילך."]]],[4301600338,"בודוי שלפני כניסת יוהכ\"פ מאריך קצת.\nליל יוהכ\"פ — בכלל, שמח<sup data-n=\"972\">27</sup>. ובשנים הראשונות, לפעמים גם מחייך — אַ שמייֵכעל טאָן בביהכ\"נ לתנועות החזנים וכיו\"ב.\n830­820 בלילה, הי' בא לביתו (מלבד הד' קאַפי' תילים הראשונים, הי' אומר מעט תילים עם הצבור והולך לביתו).\nשנה אחת האריכו בתפלה ונמשך עד 9 והי' זייֵער ניִט צופריִעֶדען מזה.\nבק\"ש שעהמ\"ט לא הי' מאריך, ובלא אמירת ע\"ח<sup data-n=\"973\">28</sup>. ומיד הולך לישון. בחדרו, ולא בחדר המטות, על קאַנאַפ<sup data-n=\"974\">29</sup>, ולפעמים היו מכניסים לחדרו את מטתו. לא הי' פושט כל בגדיו, רק את הסיורטוק.\nבשעה 11 הי' קם משנתו. לומד עד שעה 2. ישן עד שעה 3­3. ולומד עד שעה 6 וישן עוד הפעם, כשעה לערך.\nנוטל ידיו רק עד קשרי אצבעותיו<sup data-n=\"975\">30</sup>.\nהלימוד בלילה בלא טלית.\n[רצ\"ה\nבנ\"א וכו' ולשלום ג\"פ.\nבלכתנו לביה\"ט לוה ממני אבנטי הקטן בבואנו החזירו לי.\nספר<sup data-n=\"968\">23</sup>: ליל עריוהכ\"פ הי' אדנ\"ע הולך לישון בשעה 9. קם 1. לומד גמרא, קבלה — לאו דוקא מס' יומא — בקול, אויפגעלייגט, פרייֵלאַך. 2 הייתי נכנס אליו לכפרות אומר לפדות הכפרות, לזרוק הבני מעים, ללבוש איזה דבר חדש, לאכול ביד ממש, לאכול בב' ידים בעריוהכ\"פ<sup data-n=\"977\">31</sup> לא הי' נוהג אדנ\"ע].\n<b>מוציוהכ\"פ.</b>\nספר: פתיחת הארון דנעילה, מתחילת אמירת אשרי, עד אחרי כל התפלה. ויש מעשה ע\"ז מאדה\"ז נ\"ע (לא ספרה. הכותב).\nעל שאלתי אם לברך שעש\"ל כל צרכי בנעה\"ס<sup data-n=\"978\">32</sup> במוציוהכ\"פ, ענני: לייֵג אָפּ אַף מאָרגעֶן. כשהייתי ילד שאלתי שאלה זו את אאדנ\"ע וענני בלשון זה, לייֵג וכו'. וכשגדלתי, ספר לי, ששאלה זו שאל את מהרשנ\"ע, וגם זה שאלה אצל הצצנ\"ע והצצנ\"ע אצל אדהזנ\"ע. וכולם ענו כנ\"ל.\nיוהכ\"פ קומט אויס צו פאַסטען 26 שעה. ואאדנ\"ע שאל פעם: וקוצו ש\"י? כי הרי זהו כנגד שם ד'<sup data-n=\"979\">33</sup>.\nעריוהכ\"פ, העבודה היא חרטה על העבר. ביוהכ\"פ — קבלה על להבא<sup data-n=\"980\">34</sup>.",[["972","27","נתבאר בשיחת ש\"פ וילך תשכ\"ט."],["973","28","ראה אגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"ג ע' ט: א\"א תחנון וע\"ח בק\"ש שעהמ\"ט ביוהכ\"פ גם אם לא חל בש\"ק — ואמר כ\"ק מו\"ח אדמו\"ר ע\"ח יוהכ\"פ זאגט מען נאר וויפל מ'דארף."],["974","29","= ספה."],["975","30","נתבאר בארוכה באגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"ג ס\"ע קמז ואילך."],["968","23","בהבא לקמן — ראה גם שיחות תשרי תרצ\"ג (ברשימות כ\"ק אדמו\"ר). שיחת חג הפסח תרצ\"ד סעיף כג. ספר השיחות תרצ\"ו — חורף ה'ש\"ת ס\"ע 155. קיץ ה'ש\"ת ע' 10. תש\"ב ע' 87. תש\"ה ע' 21."],["977","31","ראה בית רבי חלק א פרק כח (פט, ב) שבערב יוהכ\"פ הי' דרכו של אדמו\"ר הזקן ליטול האכילה ושתי' בב' ידיו. ובלקו\"ש חכ\"ט ע' 319, שכן הי' נוהג אביו של כ\"ק אדמו\"ר — הרה\"ג והרה\"ח המקובל ר' לוי יצחק ז\"ל שניאורסאהן. וראה גם ר\"ד בעת סעודת ליל ב' דחה\"פ תש\"ל (ספר \"המלך במסיבו\" ח\"ב ע' קיב ואילך. וש\"נ)."],["978","32","= שעשה לי (כל צרכי) בנעילת הסנדל."],["979","33","בספר השיחות תש\"ה ריש ע' 21, שצום יוהכ\"פ הוא כ\"ו שעות, והטעם ידוע. ובהערת כ\"ק אדמו\"ר: \"כנגד שם הוי' — מרשימות שיחות כ\"ק מו\"ח אדמו\"ר\". וראה גם אגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"י ריש ע' רצז. שיחת ש\"פ האזינו תשכ\"ה."],["980","34","הועתק ב\"היום יום\" ט תשרי. נתבאר בד\"ה ויגד לך תעלומות חכמה שנאמר בסעודת מוצאי יוהכ\"פ זה (דשנת תרצ\"א. נדפס בסה\"מ קונטרסים ח\"א קלז, סע\"א ואילך)."]]],[4301600339,"<b>ליל אדחוהמ\"ס.</b>\nספר: עד<sup data-n=\"981\">*34</sup> שנת רנ\"ה<sup data-n=\"982\">35</sup> הי' אאדנ\"ע פארברייֵנגען שמחת ביה\"ש לילה א' ולפעמים ב' לילות ויותר. שותה הרבה משקה, מנגן נגונים וגם רוקד, שעות אחדות ולפעמים כל הלילה. מבאר ענין בחסידות, אבל בלא התחלת פסוק.\nבכלל, אפשר לומר שהתחיל לנהוג נשיאותו לגמרי<sup data-n=\"983\">36</sup> מר\"ה רנ\"ד. כי ער\"ה זה לסליחות, התפלל על מקומו הוא בביהכ\"נ<sup data-n=\"984\">37</sup>. באותו ער\"ה שהה על האוהל הרבה יותר מרגילותו בכל ער\"ה. וכשבא לתפלת המעריב, הלך ישר למקום מהרשנ\"ע, כל הנאספים ראו כן תמהו.\nאאדנ\"ע דבר דא\"ח עוד בשנת רמ\"ג<sup data-n=\"985\">38</sup>.\nהרבה מאמרים שדבר לא העלה על הכתב<sup data-n=\"986\">39</sup>.\nבטבעו הי' מ\"ש ביותר<sup data-n=\"987\">40</sup>, אבל שינה טבעו בזה. ומעולם לא ראו עצבות ע\"פ. אבל, אחרי כ\"ז, אף בעת שמחה ופאַרברייֵנגעֶן, אפשר הי' להכיר בפניו רגש של יאוש. של בדידות. לאמר: אין איש עם מי לדבר.\nמהרשנ\"ע אמר<sup data-n=\"988\">41</sup>: מ'דאַרף נעמעֶן דעם מתנגד אײַנוויקלען אין אַ מאַשיִנאוועֶן טליִת, געבען אַ קרפירער אתרוג<sup data-n=\"989\">42</sup>, באַגיסען מיִט פסח'דיִגע בראָנפעֶן<sup data-n=\"990\">43</sup>.. .\nאאדנ\"ע אמר: אני מיצר ודואג על שאין אנו דרין בפולין<sup data-n=\"991\">44</sup>. פוליִשע חיצוניות (לענין הלבושים).\nרמ\"ט דיבר אאדנ\"ע דא\"ח — אחרי מות<sup data-n=\"992\">45</sup>. תהו ותקון — ביום חול ביחוד<sup data-n=\"993\">46</sup> לפני חיים בער ע\"ה (וילנסקי, מקרעמנצוג)<sup data-n=\"994\">47</sup>.",[["981","*34","ב' הקטעים דלקמן — הובאו ברשימת כ\"ק אדמו\"ר דשמחת בית השואבה תרצ\"ב (\"רשימות\" חוברת ז ע' 7)."],["982","35","ראה ספר השיחות תש\"ד ס\"ע 18 (אודות השנים: תרנ\"א­תרנ\"ג; תרנ\"ד)."],["983","36","לגמרי דייקא, כי הענין דהנהגת נשיאות בכללותו התחיל כבר באמירת דא\"ח עוד בשנת רמ\"ג, כדלקמן בפנים (וראה בארוכה שיחת ש\"פ וירא וש\"פ חיי שרה תשמ\"ג (התוועדויות תשמ\"ג ח\"א ע' 469 ואילך))."],["984","37","ראה גם ספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 50. וש\"נ. וראה שיחת שמע\"צ תרצ\"ה סעיף א."],["985","38","נדפסו בסה\"מ תרמ\"ג (קה\"ת, תשמ\"ג. תשמ\"ט)."],["986","39","ראה ספר השיחות תר\"פ­תרפ\"ז ע' 17: \"כפי האמור הנה במשך השמונה שנים תרמ\"ג, תרמ\"ד, תרמ\"ה, תרמ\"ו, תרמ\"ז, תרמ\"ח, תרמ\"ט, תר\"ן, ישנם שבעים ושבעה מאמרים שכתבם הוד כ\"ק אאמו\"ר הרה\"ק הכ\"מ, ואצל החסיד ר\"א חוזר היו הנחות בכתב ידו, שני מאות תשעה ושלשים מאמרים, הרי כי מאה ששים ושנים מאמרים לא כתבם הוד כ\"ק אאמו\"ר הרה\"ק הכ\"מ\"."],["987","40","ראה גם ספר השיחות תורת שלום ס\"ע 15."],["988","41","ראה גם אגרות­קודש אדמו\"ר מהורש\"ב ח\"ב ריש ע' תתקכו."],["989","42","ע\"ד אתרוגי קורפו — ראה (בנוסף להמצויין בהערה 41) אגרות­קודש אדמו\"ר מהורש\"ב ח\"א ע' סג. ע' קיב."],["990","43","ע\"ד יי\"ש של פסח — ראה שו\"ת צ\"צ או\"ח סנ\"א. שער המילואים ס\"ו (בהוצאה החדשה — או\"ח סק\"ד). אוצר מנהגי חב\"ד — ניסן ע' נד ואילך."],["991","44","ראה גם ספר השיחות תר\"פ­תרפ\"ז ס\"ע 46 ואילך."],["992","45","נדפס בסה\"מ תרמ\"ט ע' רלג ואילך."],["993","46","ראה אגרות­קודש ח\"ב ע' תו. שיחת שמח\"ת תרצ\"ה סעיף יב (לקו\"ד ח\"א קצח, א). ספר השיחות תר\"פ­תרפ\"ז ע' 14. קונטרס \"חנוך לנער\" ס\"ע 11 ואילך."],["994","47","ראה אודותו במקומות שנסמנו בפר השיחות תר\"פ­תרפ\"ז שבהערה הקודמת."]]],[4301600340,"<b>חוהמ\"ס.</b>\nספר: ר\"ש מונקעֶס<sup data-n=\"995\">48</sup> — שהי' נקרא כן ע\"ש אביו שמואל, כי הי' יתום — דר בעיר אצל פאלאָצק, כמדומה. בגליל ההוא היו ב' מכשפים. — א\"י<sup data-n=\"996\">49</sup> — והיו מצירים הרבה ליהודים. בכלל, היו משתדלים להתקרב ליהודים, כי שמחים היו בזה שיהודי ישב שעה א' בלי כובע וכיו\"ב. אבל לא עם רש\"מ.\nפעם אחת הראו להם על רש\"ם, כי הוא זה. ויחלו לדבר אתו ע\"ד וכוח דתי. ומענין לענין התחילו לדבר אודות כשוף. ויאמר רש\"מ — והי' כ\"ז בקרעֶטשמע ובמעמד כמה אנשים, יהודים וא\"י — כי הוא מכשף יותר גדול מהם. ויחלו המכשפים לעשות מעשה כשוף. ורש\"מ אינו עושה מאומה. ויציעו לו כי יקחו כוס יי\"ש, יתנו לאיש לטעום. למען יראו כי אינו סם וכו' הם ילחשו על הכוס והוא ישתה אח\"כ את הכוס. רש\"ם הסכים לזה. ובתנאי שאח\"כ ישתו הם כוס יי\"ש שיתן הוא להם. ויתרצו המכשפים גם לזה. ויקחו כוס יי\"ש, ויתיצבו בפנה, לחשו על הכוס ויתנוהו לרש\"ם. הלזה לקח את הכוס ברך עליו שהנ\"ב וישתהו. בראות המכשפים שלא הצליחו בכשפיהם נבהלו עד מאד, ולא חפצו לשתות הכוסות שנתן רש\"ם לכאו\"א מהם. אבל המסובים והעומדים שם הכריחום ע\"ז. וישתו. האחד מת באותו יום. והב' — למחרתו.\nכ\"ז הי' בקייץ.\nבר\"ה הי' רש\"ם בלאזני (איני זוכר ברור. ולברר אם דר אז אדה\"ז בלאזני או בליאדי<sup data-n=\"997\">50</sup>. הכותב) אצל אדה\"ז. ולאחר ר\"ה הלך לו. ליוהכ\"פ הלך עוד הפעם לליאזני. והנה בדרכו, ולא יכול בשו\"א ליכנס העירה. כי בהיותו בשדה ועל כל צעד ואָראָנעֶס שחורים פודיִן ווײַז<sup data-n=\"998\">51</sup> נופלין עליו ואין מניחין אותו ללכת. רש\"ם קצר בתפלת המנחה, הולך הולך וא\"י להגיע העירה.\nבביהמ\"ד של אדה\"ז כבר הגיע העת לאמר כל נדרי. ויפנה אדה\"ז אל אדהאמ\"צ ויאמר לו: שמואל הולך ואינו יכול דעֶרגייֵן. גייֵ עֶם אַרויס אײַנקעגעֶן (איני זוכר אם אמר לו ג\"כ שיקח עוד אנשים עמו. הכותב). וילכו אדהאמ\"צ, ר\"א האָמלעֶר<sup data-n=\"999\">52</sup>, ר\"פ רייֵזעֶס<sup data-n=\"1000\">53</sup> (לא הבנתי אם הלכו עוד אנשים או לא. הכותב). כעבור איזה זמן יצא ג\"כ אדה\"ז מביהכנ\"ס איִן גאַס ויחזור לביהכנ\"ס.\nבראות רש\"מ את הבאים לקראתו, התחיל לצעוק על ר\"פ רייֵזעס: מי בקש זאת מכם, שיצאתם לקראתי. דעֶר רבי האָט מיִר געשיִקט יאָלאָפעֶס<sup data-n=\"1001\">54</sup>.. .",[["995","48","ראה אודותו לעיל ע' 67 הערה 28. וש\"נ."],["996","49","= אינם יהודים."],["997","50","ב\"שלשלת היחס ור\"פ מתולדות בית רבינו\" שבהתחלת \"היום יום\", כותב כ\"ק אדמו\"ר שאדה\"ז נסע לליאדי בי\"א מנ\"א תקס\"א (לאחרי המאסר (השני) בשנה ההיא), ועפ\"ז, אירע סיפור זה כשאדה\"ז דר עדיין בליאזני. וראה גם לקמן ע' 170 ובהערות 14­13. ע' 171 ובהערה 29."],["998","51","= עורבים שחורים בכמויות גדולות."],["999","52","הרה\"ג והרה\"ח ר' יצחק אייזיק בר' מרדכי הלוי עפשטיין מהאמיל. מחסידי אדמו\"ר הזקן, אדמו\"ר האמצעי ואדמו\"ר הצ\"צ. אודותו — ראה ספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 4. וש\"נ. שם ע' 237 ואילך. ובארוכה — \"תולדות הרה\"ח ר' יצחק אייזיק\" (קה\"ת — אה\"ק, תש\"מ. תשמ\"ז)."],["1000","53","הרה\"ג והרה\"ח ר' פנחס רייזעס משקלאוו. ראה אודותו — מאמרי אדה\"ז הנחות הר\"פ ע' קצא. וש\"נ. ספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 55, ובהנסמן שם הערה 14; תר\"פ­תרפ\"ז ע' 236 ואילך."],["1001","54","= כסילים, טפשים."]]],[4301600341,"ביוהכ\"פ לא בא רש\"מ לביהכ\"נ (הגיע העירה אבל לא בא לביהכנ\"ס של אדה\"ז. הכותב).\nאדה\"ז האט עם שטאַרק אויסגעֶרעֶדט.\nבאותה שנה תפסו את אדה\"ז.\nעל שאלתי אם ישנה שייכות בין ב' הספורים (מעשה המכשפים ותפיסת אדה\"ז) ענני שתמיד היו מסיימים מעשה הנ\"ל (דמכשפים) \"באותה שנה\" וכו'.\nרש\"מ<sup data-n=\"1002\">55</sup> הי' מעין גורם שאדה\"ז נסע לפ\"ב. כי: כשבאו לתפוס את אדה\"ז, התחבא. דרשו מאשתו הרבנית שתגלה איפוא הוא. כשלא הגידה הכוה על הלחי ויפילו שן מפי'. ויסעו (הבאים לתפוס). כעבור איזה זמן ופעם בלילה בשעה מאוחרת דפק רש\"ם בבית אדה\"ז. אדה\"ז הלך בעצמו אל הדלת וישאל מי שם. (ויענה רש\"ם אַ איִד. אדה\"ז הכירו בקולו ויפתח לו. ויאמר רש\"ם: עס איִז אַ איִדיִשע שטוב מ'מעֶג זיִך אָנואַרמעֶן. ויאמר לו אדה\"ז — והם עומדים שניהם אצל התנור — הרובעֶ — דו ווייֵסט שמואל מעֶן וויִל מיִך צונעמעֶן. ויענה רש\"ם: נו איִז ואָס זײַנט איִר אַ רבי וועֶט אײַך קייֵן קויל ניִט נעמעֶן. אויב ניִט זײַנט איִר וועֶרט. וויִ נעמט מעֶן דאָס אָפּ אַזוי פיִל חיות איִן גַשמיות באַ טויזענטעֶר איִדעֶן<sup data-n=\"1003\">56</sup>. כל המוקף — הענין אמיתי אבל איני זוכר ברור האותיות. הכותב).\nויצוו למחר בעיר שלא לאמר עוד שאין אדה\"ז בעיר — כי עד אז הוציאו קול שאינו בעיר. וכעבור איזה זמן תפסו את אדה\"ז.\n<b>ב' דחוהמ\"ס.</b>\nהא<sup data-n=\"1004\">57</sup> דתמיד מבארים ב' המשלים דתהום וכח הצומח יחד (לענין יש ואין)<sup data-n=\"1005\">58</sup>, מפני שכח הצומח העצמי — והדגיש מלה זו — שבארץ ותהום שמתחת לארץ יש להם שייכות זל\"ז. אבל אין מפרסמים טעם זה<sup data-n=\"1006\">59</sup>.\nההמשכה שבאין הב' בעשבים שבלי זריעה<sup data-n=\"1007\">60</sup> לא נתבאר במאמר. ולפעמים מבארים שהוא מלחלוחית הארץ. אבל בטוב מתבאר זה בנמשל בעבודה המרירות על ריחוקו ודוקא בידיעה ג\"כ טיב ועילוי הענינים שנתרחק מהם.",[["1002","55","ראה גם לעיל ע' 67 ואילך."],["1003","56","ראה גם שיחת ש\"פ חיי שרה תשי\"א (תורת מנחם — התוועדויות תשי\"א ח\"א ע' 93. וש\"נ). ובהערת כ\"ק אדמו\"ר על זה: ויש להעיר יסוד לזה — ממארז\"ל \"כל הישן בקילעא וכו'\" (עירובין סג, ב)."],["1004","57","הבא לקמן הוא, ביאור בהמאמר ד\"ה בסוכות תשבו שנאמר ביום ב' דחג הסוכות שנה זו. המאמר מיוסד על ד\"ה זה היום תרס\"ט (סה\"מ תרס\"ט ע' ז ואילך)."],["1005","58","ראה גם תו\"ח שמות רסו, א ואילך. המשך והחרים תרל\"א ע' לז ואילך. המשך וככה תרל\"ז פמ\"ג ואילך. סה\"מ תרנ\"ז ע' רב ואילך. ובכ\"מ."],["1006","59","ראה מכתב רבינו מיום ד' שבט שנה זו (תרצ\"א) — אגרות­קודש ח\"ב ע' שיב ואילך:. . . מבואר במ\"א בענין מעינות תהום רבה הנוזלים עמוק עמוק בבטן האדמה, ואינם מתגלים לעולם. . אף כי אינם בעלי פועל לפעול דבר. . ואינם אלא רק מה שהם נמצאים במציאות נמצא בארץ, לזאת הנה טבע הארץ להיות רטובה. והגם שאין יחס כלל בין מעינות התהום לרטיבת הארץ, מ\"מ הנה מזה שבארץ נמצאים המעינות דתהום רבה לזאת בסיבת מסיבות דבעל הסיבות ב\"ה הנה טבע הארץ להיות רטובה. והנה להיות כי בארץ דוקא יש טבע הרטיבות (הנק' בל' העולם פייכקייט) הנה הארץ דוקא הרי יש בה כח הצמיחה."],["1007","60","ראה המשך וככה שם פמ\"ד. סה\"מ תרס\"ט שם ע' ח. עטר\"ת ע' תנה ואילך. תרפ\"ה ע' קנז ואילך. תרח\"ץ ע' רסה ואילך. ובכ\"מ."]]],[4301600342,"תהום הוא מים ולא רק כח וכו' לזה. לפעמים איתא באו\"א מפני הענין שנתבאר שם.\n<b>מוצשחוהמ\"ס.</b>\nאמר<sup data-n=\"1008\">61</sup>: במוצשחוה\"מ א\"א ויתן לך. כן א\"א שלום עליכם, אחעט\"ב, מזמור לדוד ודא היא סעודתא בין בשחוה\"מ, בין שיו\"ט.\nאדנ\"ע וכן אאזמו\"ר נ\"ע לא אמרו. היו זמנים שאמרו (א\"י אם בחוה\"מ או ביו\"ט או בשניהם. הכותב) אבל זה אינו שייך לאחרים.\nפעם אמרו לי טעם ע\"ז (א\"י אם על הפרישה או האמירה. הכותב) בַעַל­שֶם'סקעֶ וועֶרטעֶר.\nבליובאַויִטש<sup data-n=\"1009\">62</sup> ליל שמע\"צ ערכו הבנים כאו\"א קדוש (בני הצ\"צ ובני מהרשנ\"ע). הצ\"צ לא עשה. יום שמח\"ת ערכה הרבנית קדוש בשם כל הבנים בשביל הצ\"צ.",[["1008","61","ראה לעיל ע' 143."],["1009","62","ראה גם אגרות­קודש ח\"ג ע' תא ואילך."]]],[4301600343,"<h3>ליל שמחת תורה תרצ\"א<sup data-n=\"1010\">1</sup></h3>\nהרבה טועים בענין עבודה שבלב<sup data-n=\"1011\">*1</sup> און מיינען שהוא כעין הידור מצוה, מדת חסידות, און זאָגן לכשאפנה אשנה<sup data-n=\"1012\">2</sup>, היינו כשיהי' לו כל הצטרכותו, לפי מה שהוא מודד לו בעצמו כל ההצטרכות שלו, וויפעל עס קומט אים לפי דעתו.\nדער טעות בני אדם איז דאָך זייער גרויס, דער אהבת עצמו און דער יקר בעיני עצמו, די אייגענע ליבשאַפט און די אייגענע טייערקייט וואָס דער מענטש האָט זיך ליב און באַ זיך טייער דאָס פאַר בלענט אים דיא אויגן און איז מכסה על האמת.\nאיז אַז ער טראַכט אָפּ וויפיל ער דאַרף און וויפיל אים קומט לפי דעתו, איז יעמולט הייבט ער אָן טראַכטן וועגן עבודה, מאָנטיג און דאָנערשטיג, שבת נאָך קאַווע, אַז ער קומט אין בית הכנסת און רעט אָפּ מיט אַלעמען איז נאָך דעם ווי דער צבור האָבן גיענדיקט דאַוונען הייבט ער אָן טראַכטן וועגן עבודה דאַוונען באריכות, און לבסוף דאַווענט זיך ניט, ער זאָגט אָפּ די ווערטער און יוצא.\nדער טעם הדבר איז פשוט עס פעלט אים די גאַנצע הקדמה והכנה אל התפלה, פריער גאָר די פשוטע הקדמה פון אין עומדין להתפלל אלא מתוך כובד ראש<sup data-n=\"1013\">*2</sup> שהוא הכנעה ושפלות ווי רש\"י זאָגט<sup data-n=\"1014\">3</sup>.",[["1010","1","נדפס בלקוטי דיבורים חלק ד תשג, ב ואילך. בהוצאה זו ניתוספו הערות וציונים מהמו\"ל."],["1011","*1","ראה תענית ב, סע\"א."],["1012","2","אבות פ\"ב מ\"ד."],["1013","*2","ברכות רפ\"ה."],["1014","3","כ\"ה בכ\"מ בדא\"ח בשם רש\"י \"הכנעה ושפלות\" (סה\"מ תרס\"ה ס\"ע קצד. המשך תרס\"ו ע' תפז. סה\"מ תרע\"ח ריש ע' צד. שם ע' תלג. תש\"ז ע' 203. ועוד).\nאבל בפרש\"י שלפנינו אין תיבת \"ושפלות\" (וכן אינה בהעתקת לשון רש\"י באגה\"ת פ\"י (צט, ב). מאמרי אדה\"ז על מארז\"ל (ע' מב. מד). אוה\"ת על מארז\"ל (ע' יג. יח). ועוד).\nונ\"ל שהכוונה במקומות הנ\"ל רק לתוספת ביאור על פרש\"י בענין ההכנעה.\nוראה ספר המכתם לברכות שם: \"הכנעה ושפלות הרוח\". וראה רמ\"א ושו\"ע אדה\"ז או\"ח סצ\"ח ס\"א. לקו\"ת בלק עא, ג. שערי תשובה לאדמו\"ר האמצעי שער התפלה פ\"ב (כג, סע\"ב ואילך). ובכ\"מ.\n— עפ\"י הערת כ\"ק אדמו\"ר בסה\"מ תרע\"ח שם (ס\"ע צג ואילך), תש\"ז שם. לקוטי שיחות חלק לד ע' 69 הערה 18. אגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"ב ע' שפט."]]],[4301600344,"הכנעה ושפלות אַליין דאַרף האָבן אַ הקדמה והכנה דאָס הייסט אַז מיא זאָל צוא קומען צוא הכנעה ושפלות אמיתי דאַרף מען האָבן אַ הקדמה והכנה לזה וכידוע בענין קריאת שמע שעל המטה ותיקון חצות. אָבער על כל פנים די פשוטע הכנה פון הכנעה ושפלות דאָס הייסט אַ קצת התבוננות לכל הפחות אין די עטלעכע ווערטער, מי הוא המתפלל ולפני מי הוא מתפלל, וואָס די התבוננות וואָלט אויך פועל גיווען אַ קצת חיות אין דאַוונען אָבער אַז קודם התפילה רעט מען, און ריידנדיק פאַר הערט מען אַ אמן, אַ אמן יהא שמי' רבא, אַ ברכו פון קריאת התורה, איז דאָס גאָר אַ היפוך לגמרי פון דעם ענין פון דאַוונען במילא אַז ער שטעלט זיך דאַוונען דאַווענט זיך ניט, נאָר ער מיינט אַז דאָס איז עבודה און אַז דאָס איז אַ חסיד.\nעבודה שבלב כפי שקבלתי הוא, אין האַרצן און מיטן האַרצן, עס שטייט אין פסוק<sup data-n=\"1015\">4</sup> ולעבדו בכל לבבכם, זאָגט די גמרא<sup data-n=\"1016\">5</sup> איזו היא עבודה שבלב הוי אומר זו תפלה. תורה שבכתב און תורה שבעל פה איז חכמה און בינה, תורה שבכתב איז חכמה, תורה שבעל פה איז בינה<sup data-n=\"1017\">6</sup>.\nמיר זאָגן אין ברכת המזון ועל תורתך שלמדתנו, שטייט אין חסידות<sup data-n=\"1018\">7</sup> בשם כוונת האר\"י ז\"ל<sup data-n=\"1019\">8</sup>, ועל תורתך כמו שהיא באצילות שלמדתנו בעולם הבריאה<sup data-n=\"1020\">9</sup>, חכמה איז אַ נקודה, די נקודה פון השכלה, בינה איז אורך ורוחב התפשטות פון השגה, דערפאַר איז ספירת החכמה הייסט מעין, אַ מעין איז נובע טיפּין טיפּין, און ספירת הבינה הייסט נהר.\nאיז תורה שבכתב וואָס דאָס איז ספירת החכמה זאָגט ולעבדו בכל לבבכם, און תורה שבעל פה וואָס דאָס איז ספירת הבינה שמבאר נקודת החכמה זאָגט איזו היא עבודה שבלב, וואָס הייסט אַ עבודה וואָס זי איז אין האַרצן און מיט האַרץ הוי אומר זו תפלה.\nדי עבודה פון דאַוונען איז אין האַרצן און מיטן האַרצן<sup data-n=\"1021\">10</sup>, דאָס הייסט אז מיא דאַוונט ווי עס בעדאַרף זיין, איז נאָכן דאוונען, אין די אַלע הנהגות פון טאָג דאָ אַ רושם פון דעם דאַוונען, די כוונה איז אַז מיא דאַוונט מיטן האַרצן איז נאָכדעם דער גאַנצער טאָג גאָר אַ",[["1015","4","עקב יא, יג."],["1016","5","תענית שם."],["1017","6","לקו\"ת דרושים לשמע\"צ פה, ב. ובכ\"מ."],["1018","7","ראה הערות 9­8."],["1019","8","כן הוא בכ\"מ בדא\"ח דאיתא בכתבי האריז\"ל בפירוש \"ועל תורתך שלמדתנו\" — ראה סה\"מ תרע\"ח ע' תלה. תרפ\"ט ע' 153. ה'ש\"ת ע' 68. וראה בהמצויין בהערה הבאה. ועוד.\nובהערת כ\"ק אדמו\"ר בסה\"מ ה'ש\"ת שם: ואולי הכוונה שע\"פ כתהאריז\"ל מובן שזהו פי' ועל תורתך שלמדתנו. — וראה ל\"ת להאריז\"ל ר\"פ בראשית. סי' האריז\"ל ושער הכוונות בפי' ונתן לנו תורת אמת. לקו\"ת סד\"ה להבין מ\"ש ביום השמע\"צ [פא, ד]. — להעיר מהקדמת התיקונים (ד, ב): ואית אורייתא דבריאה ואורייתא דאצילות. וראה קונטרס שבסו\"ס אמת ליעקב שאלה מם."],["1020","9","ראה לקו\"ת עקב יז, ב. אוה\"ת תשא ע' א'תתקע. סה\"מ תרכ\"ז ע' קנד. תרל\"ד ע' רעח."],["1021","10","ראה גם סה\"מ ה'ש\"ת ס\"ע 66."]]],[4301600345,"אַנדער טאָג, אין יעדער זאַך און אין יעדער מענטשן זעהט מען די גוטע זייט, און ער ליגט אין דעם אַז ער אַליין זאָהל ווערן בעסער בכל מדותיו והנהגותיו.\nדי משנה<sup data-n=\"1022\">11</sup> זאָגט לפיכך כל אחד ואחד חייב לומר בשבילי נברא העולם, דער לפיכך איז דאָך אַ המשך פון פריער להיות ווי הקדוש ברוך הוא האָט יעדער מענטשן בעשאַפן מיט אַ בעזונדער פּנים<sup data-n=\"1022\">11</sup>, דאָס הייסט אַז יעדער מענטש האָט אַ באַזונדער טבע, דערפאַר מוז יעדער מענטש זאָגן אַז בשבילי איז נברא העולם.\nעולם הוא לשון העלם<sup data-n=\"1024\">12</sup>, דשרש ההעלם הוא מצמצום הראשון, דהכוונה בהצמצום הוא בשביל הגילוי<sup data-n=\"1025\">13</sup> וואָס דאָס איז דאָך אַ קל וחומר מהצמצומים דסדר השתלשלות, ומה הצמצומים דסדר השתלשלות דענינם הוא רק מיעוט האור, כוונתם בשביל הגילוי כל שכן הצמצום הראשון דענינו סילוק האור לגמרי<sup data-n=\"1026\">14</sup>, פשיטא דכוונתו הוא בשביל הגילוי.\nצמצומים פון סדר השתלשלות זיינען בסדר והדרגה, וואָרעם אַ המשכה אָדער אַ השפעה מעליון לתחתון מוז זיין בדרך צמצום העליון לפי ערך ואופן התחתון בכדי אַז דער תחתון זאָל דאָס קאָנען צו נעמען, איז דער צמצום וואָס דער משפיע איז זיך מצמצם בשביל המקבל, איז דאָס בסדר והדרגה, וויילע דער משפיע וויל דאָך דעם טובת המקבל, און לטובת המקבל איז דאָך מוכרח אַז עס זאָהל זיין די השפעה לפי ערכו, און בכדי אַז עס זאָהל זיין די השפעה לפי ערכו מוז זיך דער משפיע מצמצם זיין, איז דאָך במילא מובן אַז דער צמצום פון דעם שכל המשפיע איז צוליב דעם מקבל אַז דער מקבל זאָהל האָבן אַ גילוי אור.\nלפי זה איז דאָך ממילא מובן אַז דער צמצום הראשון, וואָס דאָס איז כביכול סילק אורו הגדול יתברך ויתעלה געוויס בשביל טובת המקבל אַז ער זאָהל האָבן אַ גילוי אור עליון יותר והכוונה בזה הוא שיהי' הגילוי דאור אין סוף שלפני הצמצום, און דאָס זאָהל מען ממשיך זיין דורך עבודה דוקא<sup data-n=\"1027\">15</sup>.\nוואָס דאָ איז דאָך דער אופטו פון טאַטן בענין חזר והאיר<sup data-n=\"1028\">16</sup> (עס איז שוין צעהן יאָהר<sup data-n=\"1029\">17</sup> אַז דעם טאַטנס גוף איז דאָ ניטא, דאַרף מען צוקושן דעם הנשאר הגשמי מהגוף, הגם דלגבי שאר אדם אין זה מעלה (הכוונה על הנשאר מהגוף) אָבער באַ צדיקים איז אַנדערש וכו').\nוואָס באמת איז דאָך באַ אַ רבי ניט שייך דער וואָרט אופטו, דער ענין פון רבי איז לגלות למטה מה ששמע בגן עדן, אַ רבי איז דער אנכי עומד בין ה' וביניכם בעת ההיא להגיד לכם את דבר",[["1022","11","סנהדרין פ\"ד מ\"ה (לז, א). וראה גם סה\"מ תרע\"ח ס\"ע פח ואילך. תרח\"ץ ע' קסז."],["1022","11","סנהדרין פ\"ד מ\"ה (לז, א). וראה גם סה\"מ תרע\"ח ס\"ע פח ואילך. תרח\"ץ ע' קסז."],["1024","12","ראה לקו\"ת שלח לז, ד. סה\"מ תרפ\"ט ע' 160. תרצ\"ו ע' 117. תרח\"ץ ע' רכא."],["1025","13","ראה מקומות שבהערה 15. סה\"מ עת\"ר ע' ל. תרפ\"ט ע' 253. ובכ\"מ."],["1026","14","ראה עץ חיים שער א (דרוש עיגולים ויושר) ענף ב. אוצרות חיים ומבוא שערים בתחלתם. לקו\"ת הוספות לויקרא נא, סע\"ב ואילך. ובכ\"מ."],["1027","15","ראה המשך תרס\"ו ע' ד. ע' תקט. סה\"מ תרע\"ח ע' פו. תרפ\"ד ע' פד ואילך. תרח\"ץ ע' קס. תש\"ב ע' 28. ספר השיחות תש\"ב ע' 146. ובכ\"מ."],["1028","16","ראה המשך תרס\"ו שם. ועוד."],["1029","17","מיום ב' ניסן תר\"פ."]]],[4301600346,"ה', וואָס עס שטייט באַ משה רבינו עליו השלום<sup data-n=\"1030\">18</sup>, וואָס דער פירוש פון להגיד לכם איז להמשיך<sup data-n=\"1031\">*18</sup>, איז דער טייטש להגיד לכם דבר ה' ממשיך זיין צו אייך דעם דבר ה', און דאָס איז אַ רבי להמשיך גילוי אור בתורה, על דרך דעם אופן פון לימוד התורה אין גן עדן.\nבאַ אַ רבין אופטו הייסט דער ענין פון ורבים השיב מעון<sup data-n=\"1032\">19</sup>, ער גיט אַ קוק אויף איינעם וואָס איז אַ חוטא ונכשל בעון ר\"ל, וואָס יענער ווייס וואָס ער האָט גיטאָן און דער רבי זעהט דאָס אויף אים, איז מיט דעם קוק איז ער אים מעלה<sup data-n=\"1033\">20</sup>, וואָס די דרכי הרפואה זיינען, דער נתינת כח פון רבין אַז די גוטע וואָס אין יענעם איז פאַראַן זאָל זיך גובר זיין אויף די ניט גוטע.\nוואָרעם גם מי אשר ר\"ל חטא ופשע איז באַ אים פאַראַן דער ישראל, וואָס דאָס איז דאָך דער פירוש מאמר רז\"ל<sup data-n=\"1034\">21</sup> אע\"פ שחטא ישראל הוא, דער הוא איז אַ ישראל, דאָס הייסט אַז בגלוי איז ער ניט גוט ער איז ר\"ל אַ חוטא ער איז ר\"ל אַ חולה די קאָפּ און הענט זיינען ניט געזונט ער לייגט קיין תפילין ניט, און כמו כן די איבעריקע אברים ח\"ו זיינען ניט געזונט אָבער דער הוא זיינער איז אַ ישראל. הוא איז דער טייטש נסתר ונעלם<sup data-n=\"1035\">22</sup>, דאָס וואָס טיף בעהאַלטן דאָס הייסט אַז דער נעלם ונסתר באַ יעדער אידן איז אַ געזונטער, איז אַ קוק פון אַ צדיק גיט אַ כח אַז די געזונטע זייט פון דעם חולה ר\"ל זאָל זיך גובר זיין אויף דער קראַנקער זייט.\nאין אופני הרפואה איז פאַראַן צוויי דרכים<sup data-n=\"1036\">23</sup>, הא' וואָס מיא גיט רפואות צו דער חולאת ר\"ל, והב' וואָס מיא שטאַרקט די כחות פון די געזונטע אברים אַז זיי זאָהלן קאָנען דורך האַלטן די מלחמה פון די קראַנקע אברים ר\"ל.\nאון אַזוי איז אין רוחניות אַז איינער איז ר\"ל אַ חולה אויף תפילין אויף שבת אויף טהרת המשפחה אויף מאכלות אסורות וכו' איז פאַראַן צוויי אופני רפואה, היילן די מחלות ר\"ל און געבן אַ שטאַרקונג די געזונטע זייט.\nאון דאָס איז די אמתע רפואה וועג אַז מיא זאָל טאָן ביידע זאַכן. און דאָס איז דער פעולת צדיק לחיים<sup data-n=\"1037\">24</sup>, אַ קוק פון אַ צדיק גיט אַ כח אין דעם ישראל הוא, אַז ער זאָל נתעורר ווערן בהתעוררות פנימי און יעמולט וועט דער חוטא ופושע ר\"ל ווערן אַ בעל תשובה.\nבאמת להביט על מי שיש בו רע איז דאָס אַ גרויסער מסירת נפש און בפרט קוקן נאָך בעין טובה ובעין יפה, וואָרעם עס איז פאַראַן אַ קוק וואָס דערפון ווערט יענער ח\"ו ור\"ל אַ גל של עצמות, וכמאמר<sup data-n=\"1038\">25</sup> יהיב עיני' ביה ונעשה גל של עצמות. וואָס באמת איז דאָס קיין דרך ניט, מער ניט וואו מיא דאַרף לבטל את הקליפה בדרך דחי' וואָרעם אפילו די וואָס זיינען ח\"ו כלל ניט ווי מיא דאַרף, איז אויך די כוונה העליונה אַז עס זאָהל",[["1030","18","ואתחנן ה, ה."],["1031","*18","ראה דניאל ז, י. לקו\"ת שה\"ש ב, ג. מא, א. ובכ\"מ."],["1032","19","מלאכי ב, ו. ראה גם שיחת י\"ט כסלו תרצ\"ב."],["1033","20","ראה גם ספר השיחות תר\"פ­תרפ\"ז ע' 159."],["1034","21","סנהדרין מד, רע\"א."],["1035","22","ראה תו\"א מג\"א צ, ד. צד, א. סידור עם דא\"ח לט, ג. ובכ\"מ."],["1036","23","ראה גם אגרות­קודש ח\"ד ע' שנד (הועתק ב\"היום יום\" כח מנ\"א)."],["1037","24","משלי י, טז."],["1038","25","סנהדרין ק, א."]]],[4301600347,"זיין בשוב רשע מדרכו וחי'<sup data-n=\"1039\">26</sup> אָבער אַז עס זאָל ח\"ו זיין מות המת דאָס איז ניט די כוונה העליונה, און אויף דערויף שטייט<sup data-n=\"1040\">27</sup> כי לא אחפוץ כו' השי\"ת וויל דאָס ניט, דער רצון העליון איז אַז מיא זאָהל תשובה טאָן, דערפאַר איז דער קוק פון אַ צדיק דאַרף זיין בעין טובה ובעין יפה.\nעס קאָן זיין אַמאָהל אַ טיפער קוק מיט אַ פּאָר שטאַרקע ווערטער, וואָס די ווערטער קאָנען דורך נעמען דורך און דורך על דרך ווי די ווערטער פון דער תוכחה, אַז די ווערטער שטעכן און ברענען בפועל ממש, אָבער באמת איז דאָך דאָס לטובה, ווי עס שטייט אין לקוטי תורה בד\"ה בשברי לכם מטה לחם<sup data-n=\"1041\">28</sup>. אָבער דער כללות פון אַ קוק של הצדיק על החוטא ר\"ל הוא מסירת נפש.\nדער חטא עץ הדעת איז געווען וואָס אדם הראשון הסתכל במקום הקליפות<sup data-n=\"1042\">29</sup>, דקודם החטא איז דאָך געווען דער מקום הקליפות וסטרא אחרא מתחת כל העולמות<sup data-n=\"1043\">30</sup>, רע איז דאָך אַ מציאות נברא ווי עס שטייט<sup data-n=\"1044\">31</sup> ובורא רע, נאָר די בריאה פון רע איז געווען מתחת כל העולמות און עס האָט ניט געהאַט קיין שייכות אל העולם, ועל ידי זה וואָס חוה האָט עובר געווען דעם ציווי השי\"ת, איז האָט זיך דער רע מתגבר געווען און עס איז געוואָרן תערובות טוב ורע בכל הנבראים. האָט אדם הראשון אַ קוק געטאָן במקום הקליפות וואָס מיט דעם קוק האָט אדם הראשון געוועלט פאַריכטן דאָס וואָס חוה האָט מקלקל געווען, און דאָס איז געווען דער חטא פון אדם הראשון וויילע אדם הראשון איז ניט געווען קיין רבי<sup data-n=\"1045\">32</sup>, פרצוף אדם קדמון איז אויך ניט קיין רבי, פרצוף איז דאָך אַ ציור, און רבי איז ניט דער ענין פון ציור (וזהו מאמר המוסגר).\nאָבער מכל מקום הרי חזר והאיר און עס האָט מאיר געווען דער אין סוף שלפני הצמצום, פרעגט דאך דער עץ חיים<sup data-n=\"1046\">33</sup> אַ שטאַרקע קשיא, דער גאַנצער ענין פון צמצום הראשון איז געווען אַז עס זאָהל ניט מאיר זיין כביכול דער אור אין סוף וואָס לפני הצמצום בכדי עס זאָהל זיין אַ עולם גשמי, אם כן אַז לאחר שנתהווה העולם חזר והאיר האור אין סוף שלפני הצמצום, אם כן וואָס האָט אופגעטאָן דער צמצום. נאָר באמת האָט דער צמצום זייער אַפולע אופגעטאָן, צמצום האָט אופגעטאָן דעם ענין פון עבודה, און אַז דורך עבודה זאָהל מען ממשיך זיין דעם עצמות אור אין סוף וואָס לפני הצמצום<sup data-n=\"1027\">15</sup>.\nאַז<sup data-n=\"1048\">34</sup> מען גייט אין גאַס דאַרף מען טראַכטן דברי תורה, אַ פסוק חומש, תהילים, צי אין מחשבה אָדער אין דבור, וואָס דאָס ווענדעט זיך אָן דעם אָרט וואו ער גייט צי מיא מאָג על פי דין ריידן דאָרטן דברי תורה, אָבער אַז ער גייט אין גאַס און איז ניט פערנומען אין דברי תורה, זאָגט אים דער שטיין אויף",[["1039","26","יחזקאל לג, יא."],["1040","27","שם יח, לב."],["1041","28","בחוקותי מח, סע\"א ואילך."],["1042","29","ראה תו\"א בראשית ו, א. אוה\"ת בראשית חלק ו תתרפה, ב. המשך וככה תרל\"ז פקכ\"ט (ע' רד)."],["1043","30","ראה סה\"מ תרנ\"ט ע' קעו. תש\"ד ע' 139. ובכ\"מ."],["1044","31","ישעי' מה, ז."],["1045","32","להעיר משיחת ש\"פ בשלח תשט\"ו."],["1046","33","שער א (דרוש עגולים ויושר) ענף ג. וראה המשך תרס\"ו שם (ע' ד). ובכ\"מ."],["1027","15","ראה המשך תרס\"ו ע' ד. ע' תקט. סה\"מ תרע\"ח ע' פו. תרפ\"ד ע' פד ואילך. תרח\"ץ ע' קס. תש\"ב ע' 28. ספר השיחות תש\"ב ע' 146. ובכ\"מ."],["1048","34","קטע זה הועתק ב\"היום יום\" ז אדר שני. וראה גם לעיל ע' 10. לקמן ע' 189."]]],[4301600348,"וועמען ער טרעט דו בולאַך<sup data-n=\"1049\">35</sup> איינער וואָס טרעטסטו אויף מיר, ווער ביזטו, מיט וואָס ביזטו העכער פון מיר, פאַר וואָס זאָהל איך ניט טרעטן אויף דיר. אַז מען גייט אין גאַס און מען טראַכט ניט קיין דברי תורה, דערמיט איז מען ח\"ו מעכב די גאולה, מה שאין כן אַז מען וועט טראַכטן אין דברי תורה וועט מען דערמיט מקרב זיין די גאולה.\nדי חסידישע בעלי עסקים דאַרפן האַלטן אין די קראָמען אַ חומש אַ תניא, אָדער אַ תהלים, און אין די פרייע צייט לערנען. מען דאַרף טאַקע אונטער שרייבן אַ וועקסל און ניט מאַכן קיין טעות, מען דארף מאַכן אַ חשבון פאַר דעם קונה אויך, אָבער פאַר דעם אונטער שרייבן דעם וועקסל און נאָכדעם דאַרף מען לערנען אַ פסוק חומש, זאָגן אַ פסוק תהלים, און יעמולט וועלן זיי מצליח זיין אין זייערע עסקים.\nאון דאָס האָט אופגעטאָן דער צמצום הראשון אַז עס זאָל זיין אַ וועלט מיט אַ גשמיותדיקער גאַס מיט חומריותדיקע מענטשן, מיט קראָמען און וועקסלען, און מיא זאָל גיין אין גאַס און טראַכטן אָדער זאָגן אַ דברי תורה, מיא זאָל זיצן אין דער גשמיותדיקער קראָם און לערנען תורה.\nנאָר דאָס איז אַלץ אַ מאמר המוסגר, דרך אגב, דאָס איז אַלץ בעלי בתישקייט, פאַר בעלי בתים, דער ענין פון עבודה דאַרף זיין בירור המדות, ואהבת לרעך כמוך<sup data-n=\"1050\">36</sup>, איז ניט דער פשט יענעם ווי זיך, ניין עס איז אַ טעות, דער פשט איז כמוך, זיך ווי יענעם.\nלחיים דער אויבערשטער זאָל העלפן אַז דעם גוטן יאָר וואָס דער זיסער טאַטע האָט אונז געגעבן זאָל אַראָפּ קומען אין אַ בפועל ממש בטוב הנראה והנגלה, עס זאָל זיין, אז תרצ\"א, הגם עס שטייט<sup data-n=\"1051\">37</sup> מיט אַ ה', אָבער מיר ווילן אז עס זאָל זיין מיט אַ אלף<sup data-n=\"1052\">38</sup>.\nאחר כך בירך בברכתו הק' אַז דעם יאָר זאָלן אַלע אַרעסטירטע און פאַרשיקטע וועלכע זיינען אין רוסלאַנד זאָלן בעפרייט ווערן, משה רבינו הי' אצל פרעה וברח ונעשה לו נסים שצווארו נעשה כשיש והסכין לא חתך וכדומה<sup data-n=\"1053\">39</sup>, אַ קונץ, און די וואָס האָבן זיך מוסר נפש געווען אויף הרבצת תורה זיינען פאַרשיקט אין סיביר, עס איז שווער מער צו ליידן, גינוג, מיר ווילן עס זאָל זיין תרצ\"א מיט אַ אלף, עס זאָל אַראָפּ גינומען ווערן אַלע העלמות והסתרים, די חדרים זאָלן זיי גאָר ניט",[["1049","35","גולם."],["1050","36","קדושים יט, יח."],["1051","37","בחוקותי כו, לד."],["1052","38","במכתב הר\"י פייגין מכ\"ו תשרי תרצ\"א מעתיק קטע משיחה זו, ומוסיף: ואח\"כ דיבר [רבינו] הרבה מענין ביאת המשיח, ואמר שבשנה זו דארפין זיך ריכטן. ואמר אז תרצה, אז הוא ע\"פ הזהר<sup data-n=\"e43\">*</sup> שהא' הוא על ז' שהוא מדרי' משיח<sup data-n=\"e44\">**</sup>, ואף שנאמר תרצה בה', אך ידוע מרבינו שהחליף הה' על א'*<sup data-n=\"e45\">***</sup>.\nובמכתב אחר מתשרי תרצ\"א כותב: אח\"כ דיבר שבשנה זו יש תקוה חזקה על משיח, ואמר דכתיב אז תרצה, ואז הוא מדרי' משיח. ואף כי תרצה הוא בה', ידוע מרבינו שהחליף א' במקום ה', וע\"כ נקוה על תרצ\"א."],["1053","39","ראה מכילתא ופרש\"י יתרו יח, ד. שמו\"ר פ\"א, לא. דב\"ר פ\"ב, כח."],["e43","*","ראה זוהר ח\"א רטז, א וברמ\"ז שם. ח\"ב נד, א וברמ\"ז שם. כלי יקר ר\"פ שמיני."],["e44","**","ראה כלי יקר שם. סה\"מ תרע\"ח ע' רסט ואילך. תש\"ה ע' 167 ואילך."],["e45","***","להעיר מהוראת אדמו\"ר הזקן לכתוב פצוע דכא באל\"ף לבסוף ולא בה\"א — ראה לקמן ע' 228 וש\"נ. ולהעיר ממאמרי אדה\"ז תקס\"ב ח\"א ע' מא. ד\"ה בסוכות תשל\"ז (סה\"מ תשל\"ז ע' 31)."]]],[4301600349,"זעהן וכשירצו לעשות איזה רעה ח\"ו ללומדי תורה זאָל באַ זיי אָפּנעמען די הענט.\nאַ גרויסער זון אַז ער זאָגט צום טאַטן, טאַטע איך בעט דיך זאָל זיין גינוג<sup data-n=\"1054\">40</sup>, דאַרף זיך דער טאַטע צוהערן, על פי תורה טאָר מען אַ גרויסן זון ניט שלאָגן, ער דאַרף זיך צוהערן וואָס דער גרויסער זון זאָגט, טאַטע גענוג צו שלאָגן, עס איז ולפני עור לא תתן מכשול<sup data-n=\"1055\">41</sup> ווילן מיר אַז עס זאָל זיין תרצ\"א מיט אַ אלף. אַלע אידן האָפן דאָך אויף משיח'ן, אָבער איך רעכין אַז מען דאַרף האָפן אויף דעם יאָר, מען דאַרף זעך גרייטן וכו', און די עצה איז תורה וואָס מגינא ומצלי<sup data-n=\"1056\">42</sup>.\nאחר כך קרא לצעירי אגודת ישראל (דפה ריגא) ואמר להם, איבער מאָרגן וועט ווערן דריי יאָר זינט איך בין געקומען אַהער<sup data-n=\"1057\">*42</sup>, נאָך וואָס איך האָב בעדאַרפט אַרויספאָרן פון דאָרטן ווייס איך ניט, צי דען האָט גיפעלט מלאכים די וואָס היטן אַלע אידן מכל צרה ופגע רע ח\"ו וואָס זיי זאָלן מיר אויך אָפּ היטן בתוך כלל ישראל אַז מיא זאָל מיך ניט דערשיסן, אויף אַלץ איז דאָ מלאכים, נאָר אויף דעם האָט שוין געפעלט, איך האָב דען ניט געקאָנט שטיין דריי טפחים העכער פון דער ערד? איז נאָך וואָס איך האָב בעדאַרפט אַרויס פון דאָרטן ווייס איך ניט, נאָר צו וואָס איך בין געקומען אַהער איז מובן, זיי זיינען געוואָרן ב\"ה אַפולע אַנדערש ווי פריער (געמיינט די צעירי אגודת ישראל).\nמיט אייער שיטה והנהגה אינני מסכים כלל וכלל. כמו כן מיט דעם סדר הלימוד אייערן אינני מסכים כלל וכלל, נאָר צו אייך (געמיינט די צעירי אגודת ישראל) האָט דאָס ניט. איר דאַרפט מאַכן אייערע חדרים (תורה ודרך ארץ), אייערע גנים ופרדסים (עס איז אפילו ניט די פרדסים שעשה אברהם אבינו עליו השלום<sup data-n=\"1058\">43</sup>), אָבער נאָך אייער שכל נאָך, נאָך אייער הדרכה ווי מען האָט אייך מדריך געווען איז דאָס געוויס גוט.\nאַודאי דאַרפט איר אַליין ווערן בעסער, מיא דאַרף האָבן גאַנצע בערד און פאותן, די ציצית זיינען באַ אייך געוויס כשר'ע, און איר האָט בעזרת השם יתברך בכח ווערן ווי מיא דאַרף, דאָס איז בהנוגע צו אייך אַליין, אָבער דאָס וואָס איר דאַרפט טאָן מיט לייטן דאַרפט איר טאָן מיט חיות, זאָל זיין גנים זאָל זיין פרדסים אַבי זיי זאָלן זיין אידן.\nאויב איך זאָל וויסן איין אינגל וואָס וויל לערנען אין אַ חדר ווי מען האָט אַמאָל געלערנט, וואָלט איך אָנגי­ווענדעט אַלע כחות ער זאָל צו אייך אין שול ניט אַריין פאַלן, און ראַטעווען אים פון אייערע הענט, און ער זאָל לערנען באַ אַ מלמד פון דער אַלטער וועלט, אָבער די קינדער וואָס קאָנען ח\"ו אריין פאַלן ר\"ל אין אַנדערע חדרים, וואָס זיי זעהען אויס פון דרויסן אויך אידיש, איז געוויס אַז מיא מוז אָנווענדן אַלע כחות אַז זיי זאָלן אָנקומען צו אייך, און מיא בעדאַרף אייך געבן כל המיני עזר ותמיכה אַז איר זאָלט האָבן מעגליכקייט אויסהאַלטן מער קינדער.",[["1054","40","ראה גם ספר השיחות תרצ\"ו — חורף ה'ש\"ת ס\"ע 312."],["1055","41","קדושים יט, יד. וראה מו\"ק יז, א."],["1056","42","סוטה כא, א."],["1057","*42","ראה לעיל ב\"מבוא\" ע' ז."],["1058","43","ראה סוטה י, א. ב\"ר פנ\"ד, ו."]]],[4301600350,"איר האָט אַזוי פיל אַרבעט, וואָס שווייגט איר, איך פאַרשטיי אייך גאָר ניט. איר דאַרפט אַליין טאָן און אויך ווירקן אויף דעם צווייטן. איר דאַרפט זיך שטעלן אויף די טראָטואַרן<sup data-n=\"1059\">44</sup> און שלעפּן אידן אין בית הכנסת לערנען אַ בלאַט גמרא וכדומה, קיין אָפּהאַלט צוליב געלט דאַרף ניט זיין, זייט מעורר די גבירים וכו'.\nאַמאָל וואָלט מען מיט אַזעלכע יונגע לייט גאָר ניט גערעט, נאָר היינט דאַרפט איר דאָס זיין די מעוררים בעניני חיזוק התורה.\nמיא מאָנט באַ מיר פאַר וואָס איך בין צו גוט, איך קוק בעין יפה, נאָר דער אמת איז אַז דאָס האָט מען מיר געגעבן איך זאָל קוקן אויף אַ אידן בעין יפה. ווען<sup data-n=\"1060\">45</sup> איך בין אַלט געווען פיר יאָר האָב איך גיפרעגט באַ דעם טאַטן פאַר וואָס האָט דער אויבערשטער ברוך הוא בעשאַפן אַ מענטשן צוויי אויגן און איין מויל, און איין נאָז. האָט ער מיך גיפרעגט צו ווייס איך אלף בית, ועניתי הן. פרעגט מיך ווידער דער טאַטע, צי ווייסטו אַז עס איז פאַראַן אַ שין און אַ סין, און וואָס איז דער חילוק פון זיי. ועניתי לו, אַז אַ שין איז די פּינטעלע פון דער רעכטער זייט און סין איז די פּינטעלע פון דער לינקער זייט. האָט מיר דער טאַטע געזאָגט, פאַראַן זאַכן וואָס מיא דאַרף אויף זיי קוקן מיט דער רעכטער אויג, און פאַראַן זאַכן וואָס מיא דאַרף אויף זיי קוקן מיט דער לינקער אויג. אין אַ סידור און אויף אַ אידן דאַרפמען קוקן מיט דער רעכטער אויג, און אויף אַ צוקערקע און אַ צאַצקע מיט דער לינקער אויג. און פון יעמולט אָן האָט זעך איינגעוואָרצלט די זאַך אַז אויף אַ אידן ווער ער זאָל ניט זיין און ווי ער זאָל ניט זיין דאַרף מען קוקן בעין יפה.\nאמר לרמ\"ד<sup data-n=\"1061\">46</sup> ולרא\"וו<sup data-n=\"1062\">47</sup>, שהם צריכים להתעסק בהחזקת התורה במדינה זו (לעטלאַנד), ושלא יחסרו האמצעים הדרושים לזה. ועל זה הנני שליח למסור להם זאת. איר אַלע זייט עדות אַז איך האָב מיין שליחות איבערגעגעבן.\nפאַר וואָס קוקט איר ניט אויף אייערע שכנים הטובים פולין וליטא. נו אויף פולין קאָנט איר ענטפערן עס איז קיין עין הרע ניט אַ מדינה גדולה ורחבה, כן ירבו, אָבער ליטא איז דער זעלבער סכום אידן, כן ירבו ווי אין לעטלאַנד כ\"י, איז ב\"ה פאַראַן עטלעכע גרויסע ישיבות, און אין יעדער שטעטל איז דאָ אַ ישיבה קטנה, עס איז ב\"ה פאַראַן תלמוד תורה'ס חדרים מיט ערלעכע אידן מלמדים, מלמדים וואָס מיא לערנט תורה באמת, מיא לערנט ווי מיא האָט אַמאָליקע יאָרן געלערנט.\nבאַ יעדן ליטווישן אידן און אידענע איז פאַראַן אַ טייערקייט פון תורה, מען האָט ליב אַ ישיבה בחור, אַ ישיבה בחור שטייט זייער הויך, און וואָס איז אין לעטלאַנד ר\"ל פּוסט און וויסט, וואו זיינען אייערע ישיבות וואו זיינען אייערע תלמוד תורה'ס וואו זיינען אייערע חדרים.\nריגא און די גאַנצע מדינה גיט ב\"ה זייער פיין צדקה, גיט אויף אַלע ישיבות אָן עין הרע, גיט אויף אַלץ בעין יפה, השי\"ת זאָל זיי העלפן. אָבער זיי אליין",[["1059","44","מדרכות הרחובות."],["1060","45","הובא בלקוטי שיחות חלק ב ע' 596."],["1061","46","ר' מרדכי דובין."],["1062","47","ר' אביגדור וואלשאנאק."]]],[4301600351,"האָבן גאָר נישט. אמת ריגא איז געווען אַ אָפּגעשלאָסענע שטאָט און דערפאַר איז דאָס ניט קיין מקום תורה, אָבער פאַר די לעצטע צען יאָר אַז איר זייט געוואָרן אַ מדינה האָט איר געדאַרפט טראַכטן וועגן מאַכן אייער מדינה פאַר אַ מקום תורה, און איר אַלע גרויסע בעלי בתים און גבירים זייט מחוייב זען מאַכן געלט אויף הרבצת תורה, מאַכט חדרים און ישיבות נאָר די געלט דאַרף אַוועקגיין אויף החזקת תורה ממש, למקום הראוי וואו מיא לערנט בדרך הישן קמץ אלף אָ קמץ בית באָ, פתח אלף וכו'<sup data-n=\"1063\">48</sup>.\nדי אותיות פון תורה און די נקודות פון תורה זיינען הייליק<sup data-n=\"1064\">49</sup>, קמץ איז כתר, פתח איז חכמה, און די הייליגקייט פון די אותיות און נקודות זיינען מאיר די נשמות פון די קינדערלעך שיחיו וואָס לערנען אַז זיי זאָלן בלייבן ערליכע אידן.\nמיא האָט געדאַרפט מאַכן בעוואוסט צווישן אידן, אַז אַלע טאַטעס און אַלע מאַמעס זאָלן וויסן אַז די קינדער דאַרפן לערנען קמץ אלף פתח אלף, עס איז זיי נוגע אין לעבן ממש. עס איז אויפגעשטאַנען אַ דור וואָס ווילן באַ אידן אויסרייסן די קדושת האותיות און קדושת הנקודות, זיי מאַכן זיך פאַר אוהבי ישראל, בעלי טובה'ניקעס זיי זוכן די טובה פון די קינדער, אָבער מיט דעם ווילן זיי אויסרייסן באַ אידן ח\"ו די הייליגקייט פון אותיות און נקודות.\nאיך זאָג אייך אידן אַז זיי זיינען אייערע גרעסטע שונאים, זיי מאַכן ר\"ל די קינדער פאַר אפיקורסים, דער אויבערשטער ברוך הוא זאָל געבן אַלע אידן לאַנגע געזונטע יאָרן, אריכות ימים ושנים אָבער מיא לעבט ניט אייביק, פון אַזעלכע קינדער וועט ח\"ו קיין קדישים ניט זיין.\nאידן געדענקט גוט אַז אין דעם חדר און אין דעם חינוך אין דעם היינגט אָפּ אייער גאַנצער לעבן אַז דער קינד זאָל בלייבן אַ איד.\nאַמאָליקע יאָרן איז אַ איד וואָס השי\"ת האָט אים געהאָלפן ער האָט געהאַט פרנסה בריוח פלעגט ער האַלטן אַ חבר מיט וועמען ער פלעגט לערנען, ער פלעגט גיין צום ?לאַט אפילו פּראָסטע אידן פלעגן קומען אין בית המדרש הערן עין יעקב, מיא פלעגט הערן אַ מאמר רז\"ל אַ סיפור המעשה פון אַ הנהגה טובה אין חיבת התורה און מצות, אין החזקת והרבצת תורה, אין מדות טובת, יראת שמים, וטבעי בני אדם, וואָס יעדער מאמר וואָס אַ איד האָט געהערט איז דאָס באַ אים אַ אור מאיר אין זיין לעבן און אין זיין פירונג מיט זיינע בני בית.\nדי גמרא<sup data-n=\"1065\">50</sup> דערציילט אונז אַז ינאי המלך האָט געזאָגט לדביתי' זאָלסט ניט מורא האָבן ניט פאַר די בני תורה (הגם זיי זיינען געווען זיינע אומפריינד) און ניט פאַר די פרייע, נאָר מורא האָבען דאַרף מען פאַר די צבועים, די גיפאַרבטע, וואָס מיט זייערע רייד (און אַמאָל אויך אפילו מיט זייער אופפיהרען) זיינען זיי פון אויסווייניק גלייך צו די בעלי תורה, אָבער דער אינוועניק זייערער איז אַ שלעכטער.",[["1063","48","ראה לעיל ע' 44. וש\"נ."],["1064","49","ראה: תקוני זוהר בהקדמה (ז, ב ושם), שם תי' סט (קד, ב ושם). זהר חדש בתיקונים (צט, ב ושם). ובכ\"מ. שו\"ת הרדב\"ז ח\"ג סי' תרמג. ועוד. — הערת כ\"ק אדמו\"ר בספר השיחות תש\"א ע' 88."],["1065","50","סוטה כב, ב."]]],[4301600352,"איז אַ איד האָט גיהערט אַזאַ מאמר האָט ער געוואוסט אַז עס איז דאָ אַזעלכע וואָס פון דרויסן וואַייזן זיי אויס גאַנץ פרום און זיינען בעלי תורה און ריידן גוטע רייד און שטעלן דאָס איין אין קלוגע ווערטער זיי זאָגן אַז זיי מיינען נאָר די טובה פון די קינדער, אַז זיי זאָלן קאָנען בעסער, און עס זאָל זיי זיין גרינגער, זאָל מען לערנען באַ אידן להבדיל ווי מיא לערנט באַ אַלע פעלקער, וואָס דאַרף מען לערנען קמץ אלף וכו' ווי פאַרצייטיקע אידן האָבן גילערנט. מיט די גוטע רייד ווילן זיי, ח\"ו וח\"ו עוקר מן השרש זיין הי' לא תהי' די מנהגים פון די פאַרצייטיקע אידן, מיא האָט זיך גיגעבן אַ נאָמען מ'<sup data-n=\"1066\">51</sup>.\nעס איז פאַראַן אַ מדינה, וואָס איך האָב גיזעהען און גוט ב\"ה דורך גיזעהען אָבער באמת גוט דורך גיזעהען אין אַלע זייערע ענינים און זיי הייסן אויך מיט דעם נאָמען<sup data-n=\"1067\">52</sup>, אָבער יענע זיינען באמת ירא שמים'ס ווילן טאַקע אַז מיא זאָל מקיים זיין תורה ומצות ווי אַמאָל איז גיווען, און דאָרטן איז דער נאָמען מער ניט ווי אַ צוגיקלעפּטער, אָדער דער נאָמען איז אַ נאָמען אָבער די וואָס טראָגן דעם נאָמען זיינען ירא שמים'ס באמת זיי וואָלטן זייער געוואָלט אַז עס זאָל זיין באַ זיי אין דער מדינה חדרים און ישיבות ווי עס איז גיווען אין דער אַלטער היים זעהענדיק בדרך כלל און בדרך פּרט אין פאַרשיידענע שטעט און פאַרשיידענע סוגי בני אדם, מאַכט אַזאַ גוטן רושם, ווי אַלע אָהן אונטערשייד זיינען אַזוי צו גיטראָגן צו דער אַלטער היים באַ זיי איז פאַרקריצט אין האַרצן און אין גידענקען די קליינע שטעטלעך מיט די אַלטע זיידעס ווי זיי זיינען גיגאַנגען פאַר טאָג און בין מנחה למעריב אין בית מדרש, דער חדר מיט די פאַרצייטיקע מלמדים יעדערער שטאָלצירט מיט זיין עיר מולדת, מיט די אַלטע בעלי שם'דיקע רבנים און מלמדים, חדרים און ישיבות, און זיי איז דער גידענקען פון דער אַלטער היים מיט דעם פאַרצייטיקן אמת גרונטיקן און תמימותדיקן יראת שמים, זייער טייער, און דערציילן דאָס און ריידן אין דעם מיט אַ גיוויסער התלהבות, מיא זעהט אַז באַ זיי לעבט דאָס טיף אין האַרצן מיט אַ גרויסן דרך ארץ והדרת הקדש. אַזעלכע זאַכן זעהט מען אפילו באַ גאָר גאָר פאַרשטייבטע מענטשן, וואָס זיינען פאַרשטייבט מיט דעם פּיל פון לעבן. אַז איך דערמאָן זיך איצטער אויף די פערשיידענע פעהל פון אַזעלכע זאַכן וואָס איך האָב גיזעהען מאַכט דאָס אַ שמחה בלבבי.\nאָבער אין די מדינות איז דער נאָמען גאָר אַ אַנדער זאַך, דאָס זיינען די פון וועמען מיא דאַרף זיך היטן און מורא האָבן פאַר זיי, עס וואָלט גיווען אַפולע בעסער פאַר דעם כלל ישראל אַז זיי זאָלן ניט האָבן אַזאַ אויסזען.\nפון דעם וואָס שטייט גדול זכות פון מזכי הרבים<sup data-n=\"1068\">53</sup> פון דעם קאָן מען פאַרשטיין דעם פאַרקערט, עס שטייט<sup data-n=\"1069\">54</sup> יתמו חטאים מן הארץ עס זאָל זיך אויסלאָזן זינד פון דער ערד און די זינדיקע זאָלן תשובה טאָן.\nאידן דאַרפן וויסן אַז מיא דאַרף אַנטלויפן פון די חדרים וואָס זיי מאַכן",[["1066","51","אולי הכוונה למשכילים."],["1067","52","אולי הכוונה למשכילי יהודי אשכנז."],["1068","53","ראה אבות פ\"ה מי\"ח. יומא פז, א."],["1069","54","תהלים קד, לה. וראה ברכות י, א."]]],[4301600353,"כמטחוי קשת, און געלט אויף תורה דאַרף מען געבן נאָר למקום הראוי אַז ניט גייט דאָס אַוועק ר\"ל אויף מסים וארנונית וכהמעשה דרבי יוחנן שמובא בגמרא (ב\"ב<sup data-n=\"1070\">55</sup>).\nפאַר וואָס קוקט איר ניט אויף אייער שכן ליטא, אַז עס איז ב\"ה פאַראַן כמעט אין יעדער שטעטל אַ תפארת בחורים יחיו כן ירבו יונגע לייט וואָס זיינען בעלי עסקים און בחורים בעלי עסקים בעלי מלאכות קומען זיך צונויף און מיא לערנט מיא שטאַרקט זיך אין אידישקייט. פאַר וואָס איז אין לעטלאַנד גאָר נישט. ניטאָ קיין תפארת בחורים<sup data-n=\"1071\">56</sup> עס זיינען פאַראַן אַ קליין הייפטעלע צעירים שיחיו צי דען דאָס איז דער אידישער יוגענד, פאַר וואָס גיט מען זיי ניט קיין הילף אַז זיי זאָלן קאָנען מרבה תורה זיין. אידן אין לעטלאַנד דאַרפן טראַכטן מכח זיך מאַכן די לאַנד פאַר אַ מקום תורה און השי\"ת זאָל זיי העלפן.\nהיינט איז שמחת תורה, די תורה פרייד זיך און אַלע פרייען זיך, אַלע אידן זיינען זיך משמח מיט דער תורה, עס איז פאַראַן מענטשן וואָס אַ גאַנץ יאָהר זיינען זיי ניט קיין תורה אידן, קאָנען ניט לערנען און ווילן ניט לערנען, און וויילע זיי ווילן ניט לערנען דערפאַר קאָנען זיי ניט, און אַז עס קומט שמחת תורה פרייען זיי זיך, עס איז שמחת תורה.\nדער אמת פון דעם איז וויילע בשמחת תורה איז אַ עת רצון למעלה, און דער עת רצון איז אין אַ תנועה פון שמחה, דער פאַר איז למטה שמחה און אַלע פרייען זיך. וכמו בראש השנה ויום הכפורים שהוא עת רצון למעלה בתנועה של יראה, ווערן די טעג אָנגירופן ימים נוראים, יראהדיקע טעג, אַלע האָבן יראת שמים, אַלע ציטערן אָבער גאָר אַלע אפילו די וואָס אַ גאַנץ יאָר זיינען זיי פאַרטומלטע מיט זייערע עסקים, מיט תענוגים מיט תאוות ר\"ל, און פון טומלעניש ווייס מען ניט פון קיין שול פון דאַוונען וכו' ר\"ל, קומט אָבער ראש השנה און יום הכפורים יעמאָלט ניכטערן זיי זיך אויס פון זייערע פאַרטומלעניש פון דעם פּלאָנטער פון יצר הרע, און עס כאַפּט זיי אויך אַ מורא, אַ ציטער, עס איז דאָך ראש השנה, עס איז ערב יום כפור עס איז יום כפור. יעמולט דערמאָנען זיי זיך אַז זיי זיינען אויך אידן ווי אַלע אידן.\nדער טעם הדבר איז וויילע יעמולט איז דער זמן פון קירוב המאור אל הניצוץ<sup data-n=\"1072\">57</sup> און אַז דער מאור איז בקירוב אל הניצוץ יעמולט כאַפּען זיך אַלע אויף, אָט אַזוי ווי עס וועט זיין בזמן דתחיית המתים, אַז עס וועט נתגלה ווערן דער טל תורה וועט דאָס זיין אַ טל תחי'<sup data-n=\"1073\">58</sup>, אָט אַזוי איז לפי ערך אין דעם זמן פון קירוב המאור אל הניצוץ איז יעמולט כאַפּן זיך אַלע אויף, ולהיות דלמעלה הוא זה בהתנועה דיראה על כן גם למטה הוא יראה, ובשמחת תורה דלמעלה הוא עת רצון בתנועה דשמחה",[["1070","55","י, א."],["1071","56","\"בכמה מקומות במרחבי תבל נוסדו אגודת תפארת בחורים וענינה של אגודה זו אשר מתקבצים בחורים. . אשר רובם מבעלי מלאכה, בעלי עסקים. . מתקבצים יחד בזמן קבוע בכל יום ללמוד שעה אחת כו'\" — אגרות­קודש ח\"ב ע' קלב ואילך. וש\"נ."],["1072","57","ראה דרך חיים כא, סע\"ב. כד, ד ואילך. צא, א. סה\"מ תרצ\"ז ע' 158. תרח\"ץ ע' ב. וש\"נ."],["1073","58","ראה ילקוט שמעוני כו, יט. תניא ספל\"ו. וראה אגרות­קודש כ\"ק אדמו\"ר שליט\"א חלק כב ע' צז בהערה."]]],[4301600354,"לזאת הנה גם למטה הוא בגילוי דשמחה, וואָס אַלע, גאָר גאָר אַלע זיינען פריילעך און אופגעלייגט עס איז שמחת תורה.\nאון אַזוי ווי ראש השנה און יום הכפורים ווערט אַ איד אַ בעל תשובה, דאָס הייסט אפילו די ראש השנה און יום כפור אידן, וואָס אַ גאַנץ יאָר איז ער ר\"ל אין חשך ואפלה, דאָס הייסט אַרום גינומען פון אַלע זייטן ר\"ל מיט רע גמור, און אַז עס קומט ראש השנה און יום הכפורים און ער קומט אין שול קאָן דאָך זיין אַז ער זאָל טאַקע באמת תשובה טאָן, וואָס די אמתע תשובה איז אַז לא ישוב לכסלה עוד<sup data-n=\"1074\">59</sup>, אַז די ניט גוטע זאַכן וואָס ער האָט גיטאָן ביז איצטער, און די תענוגים ותאות זאָל ער מער ניט טאָן, און פון היינט אָן זאָל ער ווערן אַ איד אַ שומר תורה ומצוה. אָט אַזוי איז שמחת תורה קאָן אַ שמחת תורה איד צו קומען צו תשובה מתוך השמחה והקירוב, נעמען אַ ביסעל משקה אָנוואַרעמען זעך מיט אַ אידישער וואַרעמקייט אָנכאַפּן זיך אָן אַ עץ חיים פון אַ ספר תורה, און אַוועקגיין אין דעם אידישן קאַראַהאָד, טאַנצן און פרייען זיך מיט דער שמחה פון תורה.\nדי שמחה פון תורה איז אַ רפואה צו אַלע מחלאות ר\"ל, דעם בעל עבירה ר\"ל מאַכט די שמחה אַ פתיחת הלב והמוח אויף חרטה האָבן על כל עניניו הרעים, און נעמען אויף זיך ווערן אַ איד וואָס איז מקיים מצות, און דעם אידן פון תורה ומצות איז די שמחה פון תורה מאַכט אַ פתיחת הלב והמוח אויף להתקרב לאלקות, און דעם חסידישן אידן העלפט די שמחה פון תורה להתדבק בדביקות ובהתלהבות.\nאַ גרויסן רבי'ן נשמתו עדן, האָט מען גיענטפערט אויף זיינע שאלות אויף יחידות באַ זיין רבי'ן, וואָס זיין רבי איז אונזער רבי, נאָר אונזער רבי איז ער דורך אים, אַז מיר זיינען זיינע חסידים איז דורך אים זיינען מיר אויך זיין רבי'נס חסידים, און זיין רבי איז אונזער רבי, האָט דער רבי גיזאָגט אין דעם ענין פון ריקוד דשמחת תורה אַז דאָס איז על דרך ווי אַ פאָטער זאָגט זיין בן יחיד, טאַנץ פאַר מיר, מיט דעם נעמסטו מיך אין גאַנצן, אַז איך בין אינגאַנצן דיינער, במילא ווערן מיר אינגאַנצן זיינער. דאָס הייסט מיא טאַנצט אין אויר פון גן עדן, וואָס דאָס איז דאָך דער ענין פון הקפות, הקפות איז מקיף, אין דער הקפה האַלט מען אַ ספר תורה אותיות שבתורה וואָס דאָס איז דער עצמות אין סוף ברוך הוא פון חכמה עילאה דאצילות וואָס עס איז ניט נשתנה גיוואָרן און כמו שהוא למעלה כמו כן הוא למטה ממש, און די אותיות הקדושות מיט דעם אור עצמי פון עצמות אין סוף ברוך הוא גייט מיט אונז אין דער הקפה, און אין דעם אויר טאַנצט אַ איד בשמחת תורה.\nאַמאָל פלעגט מען צו חסידות ניט אַריינלאָזן קיין יונגע לייט, מ'האָט פריער גידאַרפט וויסן לכל הפחות דעם סדר השתלשלות, וויסן לכל הפחות די סטאַנציעס, וואָס דאָס איז דאָך דער ספר שער היחוד דעם מיטעלן רבינס, וואָס ער איז מבאר גוף ענין ההתבוננות מה היא בעצם, און במה יתבונן, וויסן די חסידישע סטאנציעס. און איצטער לאָזט מען אַלעמען אַריין, דאַרפמען מכיר טובה זיין, און צוהערן, און בפרט באַ אַ חסידישן פאַרבריינגען פלעגט מען גאָר",[["1074","59","אגה\"ת פ\"א (צא, רע\"א). וראה רמב\"ם הל' תשובה פ\"ב ה\"ב."]]],[4301600355,"נאָהענטע יונגע לייט אויך ניט אַריין לאָזן, איצטער איז די טירן אָפן ווער עס וויל קאָן קומען.\nדער טעם הדבר איז וויילע איצטער איז עקבות דמשיחא, און עס איז די צייט פון קיום ההבטחה<sup data-n=\"1075\">60</sup> פון יפוצו מעיינותיך חוצה<sup data-n=\"1076\">61</sup>, אַז חסידות און די עבודה פון חסידות וועט ריינמאַכן בעזרת השם יתברך דעם חוצה.\nאיצטער איז גיקומען די צייט אַז אַלע בני תורה אָן אַ חילוק פון מפלגה<sup data-n=\"1077\">62</sup> אפילו די וואָס האָבן זיך אַמאָל גירופן מתנגדישע בני תורה, עולמותשע ישיבות דאַרפן לערנען חסידות און זיין בעלי עבודה ווי חסידות מאָנט, ניטאָ איצטער דער ענין פון התנגדות ח\"ו, דער וואָרט מתנגד דאַרף זיין און מוז זיין מרוחק בתכלית הריחוק, באַ אונז איז ניטאָ און עס דאַרף ניט זיין קיין חילוקים ח\"ו.\nעס איז פאַראַן און עס דאַרף זיין דער חילוק אין נוסחאות, וואָס דאָס זיינען שערים מיוחדים מכוונים להשבטים והשתחואות שבמקדש שהם כנגד י\"ג שערים שבמקדש דלעתיד לבוא במהרה בימינו אמן<sup data-n=\"1078\">63</sup>, נוסח אר\"י ז\"ל נוסח אשכנז וכו' במילא איז דער נאָמען אשכנזים.\nאין תורה ומצות איז ניטאָ קיין חילוקי נוסחאות, אַלע בני תורה ומצות פון אַלע נוסחאות אין תפלה, דאַרפן נתאחד ווערן אין דער עבודה פון תורה ומצות וואָס עס איז נתגלה גיוואָרן בתורת החסידות, די טירן זיינען אָפן פאַר בני תורה, פאַר מקיימי מצות די טירן זיינען אָפן פאַר אידן, פאַר די וואָס דער נקודת היהדות ציט זיי וואו אידן זיינען און וואו אידן זיינען זיך משמח בשמחת תורה.\nאחר כך נמשך הדיבור בענין שמיני עצרת שהוא בא לאחר ההכנות של חודש אלול, שענינו הוא חרישה, שהוא ענין תעניתים, ואחר כך ימי הסליחות נעכט ניט שלאָפן און לערנען (אַ יושב אוהל אַז ער וויל אָנהויבן אַ נייע מסכת מאַכט ער דאָך אַ חשבון, אין חודש אלול דאַרף ער זיך דערמאָנען ס'איז דאָך עפּעס חודש אלול מיא דאַרף מאַכן אַ חשבון פון די עלף (11) חדשים וואָס זיינען דורכגיגאַנגען<sup data-n=\"1079\">64</sup>), נאָכדעם ראש השנה דענינו זריעה, ניט עסן און ניט שלאָפן, מייקר זיין כל רגע, און נאָכדעם יום כפור דענינו הוא ענין הרקבון שהוא התענית דיום הכפורים, וואָס דאָס איז דער תענוג פון ניט עסן.\nאיך וועל אייך דערציילן אַ מעשה, וואָס הייסט חינוך. אַז איך בין אַלט געווען זיבען יאָר דאָס הייסט אַ פערטל אויף אַכט, האָט מיך דער טאַטע צוגירופן ערב יום כפור און האָט מיר גיזאָגט, ביינאַכט טאָרסטו ניט עסן, מאָרגן אינדערפרי ביז צוועלף דעם זייגער דאַרפסטו ניט עסן, און נאָך צוועלף איז ווי דו וועסט וועלן, און האָט מיר מבאר גיווען וואָס הייסט עסן אין יום כפורים, נאָר אויב דו וועסט וועלן עסן זאָלסטו באַ קיינעם ניט בעטן, זאָלסט קומען צו מיר, איך האָב פאַר דיר אָנגיגרייט וואַסער מיט עסן און",[["1075","60","ראה בארוכה שיחת שמח\"ת תר\"ץ (לעיל ע' 84 ואילך)."],["1076","61","משלי ה, טז."],["1077","62","ראה גם לעיל ע' 72. וש\"נ."],["1078","63","ראה לקוטי אמרים להרב המגיד סימן קלג. מאמרי אדה\"ז הקצרים ע' תקפא ואילך. שער הכולל בהקדמה. ראה גם לקמן ע' 256."],["1079","64","ראה סה\"מ תרצ\"ו ס\"ע 141. וש\"נ."]]],[4301600356,"סאָק<sup data-n=\"1080\">65</sup>, טאָמער וועל איך האַלטן אין שמונה עשרה זאָלסטו אַ וויילע צו וואַרטן, באַ קיינעם זאָלסטו ניט בעטן עסן נאָר באַ מיר. און יענעם יאָר האָב איך גיפאַסט, און דער נאָך דעם אַנדער יאָר איז דאָס שוין גיווען בפשיטות וכו' (בעת ער<sup data-n=\"1081\">66</sup> האָט דערמאָנט דעם וואָרט דער טאַטע, האָט ער גיזאָגט, איך זאָג ניט אויף דעם טאַטן נשמתו עדן, ערשטנס בין איך ניט קיין אַדרעסן שרייבער, און ווידער פאַר מיר איז דער טאַטע ניט נסתלק גיוואָרן וכו'<sup data-n=\"1082\">67</sup>).\nסוכות איז די ווינטן וואָס בלאָזן, אוצרות רוח, וואָס זיי בלאָזן אויף די צמחים ווי זיי ליגן נאָך אין דער ערד, שמיני עצרת איז ווי דער קנה הצמיחה וואָס די יושבי הארץ דערקענען פון די דשאים קטנים דעם אופן הצמיחה וואָס וועט זיין, וואָס דעם אופן הצמיחה מיינט מען ניט אין כמות נאָר מען מיינט אין דעם ענין השביעה (זאַטקייט), וואָרום עס איז פאַראַן אַמאָל אַז די תבואה הגם זי איז ווייניק אין כמות, אָבער זי איז אַ תבואה וואָס זעטיקט, און אַזוי איז פאַראַן פאַרקערט וכו'. וואָס דעם סדר הצמיחה ווייסן מיר וויילע אַזוי שטייט אין זהר, און אין חסידות ווערט דאָס נתבאר וואָס דאָס איז הן אין עבודה פון די ענינים וואָס בכל השנה און הן אין דער עבודה וואָס בנפש האדם איז.\nמיא זאָל מיך פרעגן ווי די וועלט פירט זיך אין ראש השנה ווייס איך ניט, איך ווייס נאָר ווי מיא האָט זיך גיפירט אין ליובאַוויטש, אין גן עדן התחתון און אין גן עדן העליון.\nגיוויס געדענקען אַלע וואָס מיא האָט אַמאָל גירעט<sup data-n=\"1083\">68</sup> אַז דעם רבינס חסידים, דעם אלטן רבינס חסידים, פלעגן רופן דעם חדר וואָס מיא האָט דאָרטן גיוואַרט אויף יחידות, גן עדן התחתון, און דעם חדר וואו דער רבי איז גיזעסן האָבן זיי גירופן גן עדן העליון. באַ זיי איז גיווען דער רבי און חסידות די מדריגה פון עולמך תראה בחייך<sup data-n=\"1084\">69</sup>, דאָס איז גיווען זייער לעבן און דאָס איז גיווען זייער גן עדן אויף דער וועלט, און אַזוי איז באַ חסידים מקושרים בהתקשרות אמיתי.\nשמיני עצרת איז דער מריבוי' וטפוי', שמחת תורה איז דורך דעם ריקוד איז",[["1080","65","מיץ."],["1081","66","= רבינו."],["1082","67","ומוסיף בזה כ\"ק אדמו\"ר בשיחת ש\"פ שלח תש\"י (התוועדויות תש\"י ע' 106): \"ועד\"ז בנוגע לכ\"ק מו\"ח אדמו\"ר — שאין לומר עליו \"נשמתו עדן\", כי (א) מי הוא זה שיכול ליתן \"כתובות\" להגביל את מקומו ל\"גן עדן\", ג\"ע התחתון או ג\"ע העליון, או למעלה מזה עד אין שיעור, (ב) למה לנו לשלחו מאתנו?! הוא בודאי אינו רוצה להיפרד מאתנו, ונמצא אתנו!\nומאותו טעם שאין אומרים \"נשמתו עדן\", אין אומרים גם \"זכר צדיק לברכה\", כי, ענין הזכרון (\"זכר\") שייך רק על דבר הרחוק שנופל בו ענין השכחה, משא\"כ בנדו\"ד שלא שייך ענין השכחה ח\"ו, אין צורך בזכרון, כמו שאין צורך בנוגע לאדם חי\".\nובלקו\"ש חי\"ז ע' 513 במענה לשאלה למה לא נז' על רשב\"י \"זי\"ע\" (במכתב כללי דל\"ג בעומר תשל\"ה — לקו\"ש חי\"ב ע' 235): \"י\"ל ע\"פ ביאור הראגצובי (בחוקותי כו ס\"ק מב)<sup data-n=\"e46\">*</sup> דביצחק אין שייך זכירה כו'\"."],["1083","68","לעיל ע' 17. וש\"נ."],["1084","69","ראה ברכות יז, א."],["e46","*","וז\"ל: בתו\"כ פ' בחקותי דאמר שם דשם זכירה לא שייך רק על דבר שאינו לפנינו, ולכן ביצחק לא שייך זכירה רק ראיה. . דשל תורה הוא דבר הנמשך ופועל תמיד ולכן לא שייך בזה גדר זכירה."]]],[4301600357,"מען ממשיך דעם תענוג עצמי הבלתי מורגש פון העלם העצמי דאין סוף, וואָס דאָס איז וואָס מיא איז ממשיך דורך דעם ריקוד וואָס דער ענין אין דעם איז אַז עס דערלאַנגט ביז די כפות רגליו, א מענטש אַז ער איז פריילעך פּאַטשט ער מיט די הענט, און אַז די שמחה איז נאָך גרעסער טאַנצט ער מיט די פיס, דאָס הייסט אַז די שמחה האָט אים דורכגענומען און נעמט אים אַרום אינגאַנצן עד כפות רגליו.\nנעכטן אין דער צייט בין איך דאָך ניט געזעסן (ליידיג) בטל, און יעצט זיצט מען אַ פּאָר שעה, באַ אייך איז דאָס מסתמא אַ קשיא, באַ מיר איז דאָס אויך אַ קשיא, נעכטן איז מען דאָך ניט גיגאַנגען ליידיג, איי שלאָפן, איז דאָך אויך אַ סדר, דאָס איז דאָך באַ יעדער בן תורה איד דער חלקי ה' אמרה נפשי, עס איז דאָך פאַראַן די צייט וואָס אמרה נפשי, וואָס דער נפש רעט, דער ענין אין דעם איז אַז מיא האָרעוועט אויף אַ ענין און מיא ווייס אים ניט, איז נאָכדעם בעת השינה שהנשמה עולה למעלה ווערט דאָס אים נתגלה, דאָס איז דער חלקי ה' אמרה נפשי<sup data-n=\"1085\">70</sup>.\nעס איז דאָ אַ העכערע דרגא אַז די ענינים וואָס מיא לערנט, און די ענינים אלקים וואָס מיא איז זיך אין זיי מתבונן בעת התפלה וכו' איז בעת השינה שהנשמה עולה למעלה ושואבת לה חיים<sup data-n=\"1086\">71</sup>, יעמאָלט ווייסט מען די פנימיות ועמקות הענינים (אבל זה הוא כעין שכר כו')<sup data-n=\"1087\">72</sup>.\nאיר האָט אַמאָל גיזעהן אויף אַ וואָקזאַל ביינאַכט, עס איז פינסטער, ווייניק מענטשן, און דער שומר גייט אַרום און שיקט פאַנאַנדער די וואַגאָנעס, יעדערן אויף זיין אָרט, דעם וואַגאָן אין דעם געגנט און דעם צווייטן וואַגאָן אין אַן אַנדער געגנט. עס איז דאָך עלמא עילאה כגוונא דעלמא תתאה<sup data-n=\"1088\">73</sup>, איז למעלה באַדערנאַכט ווען די נשמות זיינען עולה בעת השינה, דרייען זיך אַרום מלאכים, און מלאך מיכאל שיקט פאַנאַנדער די נשמות יעדערע צו איר היכל, אויב איינער האָט זיך באייטאָג גיטראָפן זיך מיט דעם צווייטן און האָט אים גיזאָגט, קום מיר וועלן גיין שאַפן אַ פּאָר רובל פאַר יענעם נויט באַדערפטיגן, און זיי זיינען צוזאַמען גיגאַנגען און גישאַפט פאַר דעם נויט באַדערפטיגן, איז נאָכדעם באיינאַכט למעלה די מלאכים זיינען מצרף די ביידע נשמות און מען שיקט זיי אָפּ אין היכל הצדקה, אויב איינער האָט געלערנט באייטאָג תורה, שיקט מען אים אָפּ אין היכל התורה, און דאָס איז דער ענין פון חלקי ה' אמרה נפשי, אַז עס ווערט אים נתגלה דער ענין וועלכן ער האָט פריער ניט פאַרשטאַנען<sup data-n=\"1087\">72</sup>. וכמו בענין דרש רבא כתיב<sup data-n=\"1090\">74</sup> התעיף עיניך בו וכו' ווערט באַ אים נאָכדעם רעכט דער ענין (ענין זה נתבאר בדרוש שמיני עצרת תרצ\"א).\nעל כל פנים נעכטן בין איך דאָך ניט געזעסן ליידיג (בטל) איצטער אַז מען זיצט און מיא גיט אַוועק צייט דאַרפמען",[["1085","70","איכה ג, כד."],["1086","71","ב\"ר פי\"ד, ט."],["1087","72","ראה שער הגלגולים הקדמה יז. ד\"ה צהר תעשה לתיבה תרצ\"ה (סה\"מ קונטרסים ח\"ב שדמ, א). סה\"מ ה'ש\"ת ע' 5. לקוטי שיחות חלק ד ע' 1026. ועוד."],["1088","73","ראה זוהר ח\"א לח, א. שם רה, ב."],["1087","72","ראה שער הגלגולים הקדמה יז. ד\"ה צהר תעשה לתיבה תרצ\"ה (סה\"מ קונטרסים ח\"ב שדמ, א). סה\"מ ה'ש\"ת ע' 5. לקוטי שיחות חלק ד ע' 1026. ועוד."],["1090","74","משלי כג, ה. סוטה לה, א."]]],[4301600358,"דאָך איצטער דער ריידן זיך צו אַ טאָלק. אויף וואָס דוכעט<sup data-n=\"1091\">75</sup> איר און אויף וועמען זייט איר זיך סומך, חסידים דאַרפן אַליין טאָן יעדערער מוז האָרעווען, עס דאַרף זיין עבודה שבלב, דער ענין פון תפלה, די הכנה צו עבודה שבתפלה דאַרף זיין ג' ד' שעות מקודם לימוד בעיון, און די יודעי העיון ווייסן אַז צוליב לערנען דריי שעות בעיון דאַרפמען לכל הפחות לערנען פינף זעקס שעה.\nדער צדיק ר' נחום פון טשערנאָביל נ\"ע, איז געווען שמן פון אמן יהא שמי' רבא<sup data-n=\"1092\">76</sup>, וואָרום מיר זעהען דאָס במוחש, אז מיא זעט אַ אידן לערנען קומט צו פשוט אין גשמיות אין לב ובשר הגשמי. אַז איך וואָלט זיצן צווישן הונדערט לומדי תורה, איז אויב מיא דאַרף אַ פונט ברויט אַ טאָג וואָלט איך מער ניט דאַרפן ווי אַ פערטל, און אויב מיא דאַרף אַ האַלבע פונט, וואָלט גיווען גינוג אַ אַכטל פונט.\nאיך וואָלט וועלן זיין אַ איש פשוט, נאָר אַזוי ווי די רבותינו הקדושים האָבן פאַרשטאַנען דעם ענין פון איש פשוט, מיכל שצערבינער<sup data-n=\"1093\">77</sup> (הערת המו\"ל, דאָס איז גיווען אַ ישובניק פון דאָרף שצערבינע, נאָהענט פון ליובאַוויטש, און ער פלעגט פאָרן אין ליובאַוויטש צום רבין) איז אַמאָל גישטאַנען באַ סליחות ניט ווייט פון טאַטן, און עס האָט גירונען באַ אים טרערן פון ביידע אויגן, האָט דער טאַטע אים מקנא געווען, דער טאַטע איז דאָך גיווען אַ שיינער אין גשמיות איז באַ אים איינגיפאַלן די באַקן פון קנאה, און האָט גיזאָגט אַז ער איז מקנא מיכלן ווי ער זיצט באַ זיך אין דאָרף און שטייט אויף צוויי אַזייגער באיינאַכט און זאָגט תהלים וכו'.\nהערט אידן מען קאָן נאָך אַריינכאַפּן תשובה טאָן, ראש השנה שרייבט מען<sup data-n=\"1094\">*77</sup>, און יום הכפורים שרייבט מען אונטער, הושענה רבא נעמט מען אַרויס די פתקי חיים<sup data-n=\"1095\">78</sup>, און ביז שבת בראשית גייען זיי נאָך ניט אַרויס פון היכל.\nאחר כך פנה להמון עם שנתאספו, און האָט גיזאָגט, איך בין מודיע אויב דאָ געפינען זיך אַזעלכע וואָס לייגן ח\"ו ניט קיין תפילין און היטן ניט קיין טהרת המשפחה, זאָלן זיי ניט זיין באַ מיינע הקפות. אדם הראשון איז אַרויס גיטריבן גיוואָרן פון גן עדן נאָך דעם חטא, ווייל די קרקע פון גן עדן און דער אויר פון גן עדן קאָן ניט פאַרליידן קיין חטא<sup data-n=\"1096\">79</sup>, עשרה שיושבים ועוסקים בתורה שכינה שרוי' ביניהם<sup data-n=\"1097\">80</sup>, אַ קיבוץ פון חסידים וואָס זיינען בהתקשרות לאבות העולם, איז אויר פון גן עדן, צו מיינע הקפות קאָנען ניט זיין די וואָס היטן ניט קיין טהרת המשפחה און די וואָס לייגן ניט קיין תפילין (מיט מיר אונטער איין מקיף קאָנען זיי ניט זיין), סיידן זיי זאָלן אויף זיך מקבל זיין פון היינט אָן צו היטן טהרת המשפחה און לייגן תפילין.\nעס שטייט<sup data-n=\"1098\">81</sup> קץ שם לחושך,",[["1091","75","בוטחים."],["1092","76","ראה שיחת יום שמח\"ת תרפ\"ט (לעיל ע' 46). וש\"נ."],["1093","77","נזכר בשיחת מוצאי יוהכ\"פ תרפ\"ט (לעיל ע' 25 ואילך)."],["1094","*77","ראה ר\"ה טז, ב."],["1095","78","ראה זוהר ח\"א רכ, סע\"א (ובאור החמה שם). ח\"ב קמב, סע\"א. ח\"ג לב, א. פרי עץ חיים שער הלולב פ\"ד."],["1096","79","מאמרי אדמו\"ר האמצעי ויקרא ח\"ב ע' תשג. סה\"מ תרס\"ב ע' רצט."],["1097","80","אבות פ\"ג מ\"ו."],["1098","81","איוב כח, ג."]]],[4301600359,"פינסטערניש האָט אויך אַ ברעג, איר יונגעלייט וואָס איר לויפט מיט דעם וועלט שטורעם, לויפענדיק נאָך די וועלטיקע זאַכן פאַרגעסט איר אויף אידישקייט. איר פאַרגעסט אויף תפילין, אויף שבת, אויף טהרת המשפחה, איר זייט צוטראָגן פאַר יאָגט, די דאגת הפרנסה, דער שטורעם פון לעבן פאַרשלעפּט אייך פאַר בלענדעט אייך די אויגן, אָט אַזוי לעבט איר אָפּ אַ טייל פון אייער לעבן.\nדערמאָנט זיך יונגע מענטשן און בעטראַכט זיך איר וועט ווערן עלטער, וואָס וועט זיין פון אייך און פון אייערע קינדער, איר קאָנט ניט לערנען איר זייט פּראָסט אין וויסן אַ דין, איר און אייערע פרויען ווייסט ניט וואָס מיא מאָג און וואָס מיא טאָר ניט, מיא ליגט אין לעבן, מיא זוכט אַלץ וואָס בעסער פאַר דעם גוף, און אויף דער נשמה פאַרגעסט איר.\nיעדער מענטש דאַרף קוקן אויף שפּעטער זעהען וואָס וועט זיין די ענדע, די ענדע וועט געוויס זיין אַ גוטע עס שטייט דאָך כי לא ידח ממנו נדח<sup data-n=\"1099\">82</sup>, סוף כל סוף וועלן אַלע תשובה טאָן נאָר עס איז דאָ צוויי וועגן, איינע וואָס השי\"ת גיט דעם מענטשן רוב טוב, און די צווייטע ח\"ו דורך יסורים ר\"ל, מיא דאַרף האָבן דעם בית הקברות אין זינען, מיא דאַרף גידענקען אין אַלע צייטן אפילו ווען מיא איז ב\"ה יונג, דאָרטן זיינען דאָ פערשידענע עלטער און השי\"ת זאָל געבן אַלע אידן אומעטום אריכות ימים ושנים, אָבער ימינו איז דאָך כצל עובר<sup data-n=\"1100\">83</sup>, מיא דאַרף לייגן תפילין, היטן טהרת המשפחה. אַז מיא היט אָפּ אידישקייט ווערן געבאָרן כשרע קינדער גיזונטע קינדער, און אַז איר וועט זיי געבן לערנען אין גוטע חדרים וואָס מיא לערנט קמץ אלף וועט איר אין זיי זעהען אפולע נחת, איר וועט האָבן אריכות ימים ושנים, און נאָך אריכות ימים וועט איר האָבן כשרע קדישים און כשרע קינדס קינדער. די וואָס זיינען מקבל אויף זיך לייגן תפילין און היטן טהרת המשפחה קאָנען בלייבן צו הקפות, און מיר וועלן זיך משמח זיין בשמחת התורה און השי\"ת זאָל אונז אַלעמען בתוך כלל ישראל געבן אַ גיזונטן גליקליכן יאָר בגשמיות וברוחניות.\nואחר כך עמד על רגליו ואמר בקול רם, אתפשטותא דמשה בכל דרא<sup data-n=\"1101\">84</sup>, משה איז גיווען אַ אוהב ישראל, באַ משה רבינו איז גיווען טייער אַ אידישער גוף, לא מיבעי נפש רוח ונשמה, נאָר אויך אַ אידישער גוף. יקר אצלי גופו של כל אחד ואחד מישראל, ועל כן הנני מודיע עוד הפעם, שבאם ישנם בכאן כאלו וואָס היטן ניט קיין טהרת המשפחה, און אַזעלכע וואָס לייגן ניט קיין תפילין, זאָלן ניט באיי זיין צו מיינע הקפות, וויילע עס איז פאַר זיי אַ סכנה, מיט סכנות נפשות שפּילט מען זיך ניט<sup data-n=\"1102\">85</sup>.",[["1099","82","ע\"פ שמואל­ב יד, יד. וראה הל' ת\"ת לאדה\"ז פ\"ד ס\"ג. תניא ספל\"ט."],["1100","83","ע\"פ תהלים קמד, ד."],["1101","84","תקו\"ז תס\"ט (קיב, רע\"א. קיד, רע\"א). וראה ב\"ר פנ\"ו, ז."],["1102","85","במכתב הר\"י פייגין מכ\"ו תשרי תרצ\"א מעתיק קטע משיחה זו, ואח\"כ מוסיף: באסרו חג נודע לנו ממקום ברור אשר מקלוב [=מועדון] פרץ שבפה, שהם מקו השמאל לגמרי פשוט קאמוניסטן, באו בהכנה לבלבל ההקפות והי' מוכן אצלם מי שיחתוך העלעקטרא, ואם יעמדו נגדם הי' מוכן אצלם אלים ר\"ל. וכשאמר [רבינו] דברים אלו, אמר הגדול שבהם להשאר שילכו והלכו. והוא פלאי בכח עליון שפעל על הרשעים הללו.\nוממשיך הר\"י פייגין במכתב הנ\"ל: ביום ו' נכנסתי אצלו [לרבינו] וספרתי לו הענין הנ\"ל, אף כי כבד הי' להמשיך עליו מרה שחורות בכ\"ז מצאתי לנכון אשר צריך שידע זאת. ואמר [רבינו:] אט איצט איז מיר רעכט, איך האב בעת מעשה ניט פארשטאנען וואס האט מען מיך מכריח געווען אויף זאגן דאס."]]],[4301600360,"די וואָס האָבן פאַרלאָשן די עלעקטרא און אָנגיצונדן האַלטן ווי די דעת המתירים אַז יום טוב מאָג מען, עס איז אַ טעות גמור, מיא טאָר ניט. וואָס זיי האָבן אין דעם גימיינט איז קיינעם ניט נוגע. אויב אפילו דאָס וואָס זיי מיינען גאָר גאָר טיף, בעזה\"י איך האָב דערפאַר ניט מורא, אידן זיינען ברשות הקב\"ה און ניט ברצון בשר ודם.\nאפילו די וואָס מיינען אַז זיי האַלטן פון גאָר גאָרנישט ח\"ו בין איך זיי מחויב צו זאָגן אַז זיי זאָלן זיך היטן, מיט סכנות נפשות שפּילט מען ניט, בעסער פאָלגן און אַוועקגיין גיזונטערהייט, און די וואָס בלייבן דאָ יע צו הקפות איז געוויס זיינען זיי אויף זיך מקבל דברי חברות פירן זיך ווי מיא דאַרף. (והפועל יוצא הוא שהי' אַז אַפולע האָבן מבטיח גיווען אַז זיי זיינען אויף זיך מקבל פירן זיך ווי מיא דאַרף וכו'). אחר כך ישב כ\"ק אדמו\"ר שליט\"א על מקומו און האָט גיזאָגט אָט די אַלע יונגע לייט דאַרפמען געבן אַ ביסל משקה און פאַרבייסן, יעצט זיינען מיר ברידער.\nבאַ ברכת כהנים שטייט<sup data-n=\"1103\">86</sup>, ואני אברכם, איז פאַראַן אין דעם צוויי פירושים<sup data-n=\"1104\">87</sup>, הא' שהקב\"ה ימלא הברכה שהכהנים מברכים לישראל, והב' שהקב\"ה מברך להכהנים. איך דעם טאַטנס אַ זון, דעם זיידנס אַ אייניקל, דעם עלטער זיידנס אַ אוראייניקל, וואָס בכלל איז דאָס אַ המשכה עצמית, ווי מען האָט גערעדט (כוונתו על המאמר דראש השנה תרצ\"א<sup data-n=\"1105\">88</sup>) ובפרט זרע קודש, בענטש איך אייך און אַלע אידן וועלכע געפינען זיך בכל מרחבי תבל, מיט אַ שנה טובה ומתוקה וכו'.\nאחר כך אמר, איך בין מיט אייך באָ בברית, אַז יעדערער זאָל זיך משתתף זיין אין אַ שיעור לימוד ברבים און זאָל זיך משתדל זיין צו קובע זיין שיעורי לימוד ברבים, יעדערער דאַרף האָבן אַ שעה קבועה אין טאָג אויף לערנען.\nאיך וועל זיין אַביסל אַ מגלה סוד, וואָס מיא דאַרף האָבן היינטיגען יאָר מיא זאָל קלאָר ווערן בעל פה די ערשטע צוועלף פרקים פון תניא בדקדוק באותיותיהם מיט דער הקדמה אליכם אישים אקרא (דאָס הייסט פון דער הקדמה אליכם וכו' ביז פרק י\"ג)<sup data-n=\"1106\">89</sup>. און אַז מיא גייט זיך לייגן שלאָפן, אַז מיא שטייט אוף, און וואו מיא גייט, זאָל מען דאָס חזרן בדבור ובמחשבה.\nאחר כך בא ר\"מ שי' שו\"ב<sup data-n=\"1107\">90</sup>, און האָט גיזאָגט לכ\"ק אדמו\"ר שליט\"א, אַז ער איז אַ שליח פון די פרויען וואָס זיינען גיבליבן וואַרטן אויף הקפות, אַז זיי האָבן גיהערט די גאַנצע רייד און אַלע אזהרות והם מעידים על עצמם שהן",[["1103","86","נשא ו, כז."],["1104","87","חולין מט, א. פרש\"י עה\"פ."],["1105","88","ד\"ה א\"ר אבהו דיום ב' דר\"ה שנה זו (סה\"מ קונטרסים ח\"א קלא, א ואילך)."],["1106","89","ראה גם ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 17. וראה גם אגרות­קודש חי\"ג ע' תקיט­תקכ. אגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"ז ע' קכט. ובכ\"מ."],["1107","90","ר' מרדכי חפץ מדיסנא. שו\"ב בריגא. ראה אודותו ספר השיחות תר\"פ­תרפ\"ז ע' 18 ובהערה 39. נזכר לעיל ע' 41. וש\"נ."]]],[4301600361,"רשאות להיות בעת ההקפות. האָט כ\"ק אדמו\"ר שליט\"א גיהייסן ענטפערן זיי אַז ער בענטשט זיי אַז די וואָס האָבן זין און טעכטער יחיו זאָלן זיי און זייערע מענער יחיו מגדל זיין זיי לתורה חופה ומעשים טובים, און די וואָס האָבן נאָך לעת עתה ניט קיין קינדער זאָל זיי השי\"ת דערפרייען זייערע הערצער און די הערצער פון זייערע מאַנען שיחיו מיט גיזונטע גוטע קינדער, און זיי זאָלן מאַכן אַ אגודת נשים וואָס זאָל טאָן אין פאַרשטאַרקן דעם טהרת המשפחה. והשי\"ת יברך את עמו ישראל בכל טוב גשמי ורוחני."],[4301600362,"<h3>כ\"ז — כ\"ט תשרי צ\"א ריגא<sup data-n=\"1108\">1</sup>.</h3>\nספר<sup data-n=\"1109\">2</sup>: פעם שחקתי עם ר\"ח מרזוב<sup data-n=\"1110\">3</sup> שַחמַט<sup data-n=\"1111\">4</sup>. אאמו\"ר נ\"ע עזר לי. וסו\"ס נצח אף שר\"ח הוא משחק טוב. ואמר אאדנ\"ע שבסברות אלו — שבשַחמַט — הרי בענין דבריאה יש מאין יש להם מקום יותר<sup data-n=\"1112\">5</sup>.\nכ\"ט תשרי — אור ליום ג' שתה תה אצלנו. ספר: הצ\"צ בהיותו ילד נכנס פעם לאדה\"ז בבואו מהחדר (ויאמר לו אדה\"ז מדאַרף לעֶרנען. הצ\"צ: עס וויִלט זיִך ניִט. אדה\"ז: אַזוי עס וויִלט זיִך ניִט. הלך לפינת החדר, לקח את מקלו. ויכה על שכם הצ\"צ ויאמר<sup data-n=\"1113\">*5</sup>: בזה הנני ממשיך בך אהבת ד' ויראת ד'. דו זאָלסט דעֶם אויבעֶרשטעֶן ליִב האבעֶן און דוּ זאָלסט פאַר עם מורא האָבעֶן<sup data-n=\"1114\">6</sup>. הלשון איני זוכר בדיוק. הענין ברור. הכותב). כה ספר לי אדנ\"ע. גם ספר לי שכן עשה הצ\"צ למהר\"ש ומהר\"ש לאדנ\"ע. (וכהבנתי מדבריו: אדנ\"ע למו\"ח כק\"ש. הכותב). וזה הי' אז באותו זמן כשאמר לי — בהמשך לאיזה מאורע — וואָס מייֵנסט איִך דאַרף האָבען דײַן פלייֵש, פלייֵש קאָן איִך האָבעֶן פריִשע יעֶדעֶ וואָך<sup data-n=\"1115\">7</sup>.\nבשנת מ\"ט הלך גם אדנ\"ע לקדוש אל הרז\"א. כי ליל שמח\"ת היו מקדשים",[["1108","1","מרשימות כ\"ק אדמו\"ר."],["1109","2","ראה שיחת ש\"פ שמיני תשי\"ב: כ\"ק מו\"ח אדמו\"ר האט אמאל געשפילט שחמט מיט חאנע'ן, דער רבי (מהורש\"ב) נ\"ע איז צו זיי צוגעגאנגען און האט זיך אריינגעמישט. ער האט געזאגט המצאות ווי צו גיין, און האט אויסגעטייטשט די אלע ענינים אין עבודה.\nבא דעם רבי'ן נ\"ע איז דאס געווען מלמעלה למטה, פון די ענינים ווי זיי זיינען אין רוחניות האט ער געוואוסט אויך ווי צו שפילען אין גשמיות."],["1110","3","הרה\"ח ר' אלחנן דובער מאראזאוו. ראה אודותו לעיל ע' 32 ובהמצויין שם בהערה 16."],["1111","4","ע\"ד התוכן וההוראה דמשחק זה בעבודת ה' — ראה רשימת דברי כ\"ק אדמו\"ר משנת תש\"ח (נדפסה בס' \"ימי בראשית\" ע' 338 ואילך (ובהערה 7 שם))."],["1112","5","לכאורה הכוונה שהסברות שבמשחק השחמט כפי שהם בשרש הענינים למעלה — בענין בריאה יש מאין — יש להם מקום יותר מכמו שהם בהמשחק למטה (ולכן יודעם אדנ\"ע בטוב יותר)."],["1113","*5","בשיחת חה\"פ תרצ\"ה שאמר: \"נאַ דיר אהבה, נאַ דיר יראה\"."],["1114","6","בספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 143 (ובספר התולדות מהר\"ש (קה\"ת, תש\"ז) ע' 65), שאדמו\"ר הצ\"צ סיפר: בהיותי בן ט' שנה והי' לי שיעור ללמוד, והנהוג הי' אשר אאזמו\"ר [=אדמו\"ר הזקן] הי' בוחן אותי. אחר הבחינה נתן לי ענין ללמוד והייתי אז מיוגע מהלימוד הקודם, וגם חפצתי להיות באויר ודחיתי הלימוד על שעה מאוחרת והלכתי החוצה. בראות אאזמו\"ר מבעד החלון כי הנני בחוץ קרא אותי ושאלני למה אינני לומד הענין שנתן לי, ואמרתי כי יגעתי כבר מוחי מלימוד הקודם, ולקח אאזמו\"ר מקלו ונתנו על כתפי ואמר: נא דיר חכמה נא דיר בינה נא דיר פתיחת הלב."],["1115","7","ראה שיחת ש\"פ פינחס תש\"י (תורת מנחם התוועדויות — ה'שי\"ת ע' 148)."]]],[4301600363,"אצלו<sup data-n=\"1116\">8</sup>, ובשנים הראשונות הי' המנהג שהם אמרו ג' פסוקים הראשונים (א\"ה — רז\"א. ל\"נ — אדנ\"ע. א\"כ — רממנ\"י<sup data-n=\"1117\">9</sup>) ומפרשים אותם עפ\"י חסידות. רז\"א שתה הרבה, בכלל, לא הי' שותה. רק ג\"פ ראיתיו ששתה הרבה ובהפלגה יתרה עד לה' כוסות ראָם זא\"ז. אז, חתונת מ' תי'<sup data-n=\"1118\">10</sup> וחתונתי<sup data-n=\"1119\">11</sup>. אדנ\"ע נגש אליו, אחז בידו ויאמר: קום הערעֶן חסיִדות פון טאַטעֶן. רוקט זיִך פאַנאַנדעֶר (כי היו באותו מעמד כשני מנינים. כי לא כל החפץ נכנס). שניהם לבשו כובעיהם והאבנטים ויעמדו על רגליהם משך זמן ובבטול גדול וכו'. ויאמר רז\"א<sup data-n=\"1120\">12</sup>: אַ ליִטואַק גלייֵבט ניִט ביִז ואַנעֶט ער צייֵלט ניִט דורך. דורכצייֵלעֶן און ניִט גלייֵבעֶן.. . מעֶר ניִט ווײַל עֶס איִז אַ מסך מבדיל.. .\nעד<sup data-n=\"1121\">13</sup> כמה שאפשר הי' לדחות לא חפץ אדה\"ז לנסוע מליאַדי (או ליאזני. א\"י<sup data-n=\"1122\">14</sup>. הכותב). ונסעו משם עש\"ק מברכין אלול<sup data-n=\"1123\">15</sup>. ונסעו גם בש\"ק<sup data-n=\"1124\">16</sup>. עד קראַסנאָועֶ. מסמאָלעֶנסק שלחו שני פּאָלק<sup data-n=\"1125\">17</sup> בני חיל עם ארטיִלעֶריעֶ לשומרם. ר' נחום<sup data-n=\"1126\">18</sup> הי' במקום עגלון. ועל פרשת דרכים טעה והטה העגלות לדרך אחרת. אדה\"ז הי' תפוש ברעיונות. אבל פתאום נתעורר: וא איִז מעֶן! לחזור כבר הי' א\"א כי נשמעו כבר קול יריות כלי תותח של האויב. ונסעו בהקפה עד בואם לקראַסנאָועֶ.\nקודם<sup data-n=\"1127\">19</sup> נסעו צוה אדה\"ז שלא לעזוב מאומה מכליו. ולעקור וליקח אתם גם השטעֶנדעֶר שהתפלל אצלו (הי' מחובר) וגם להקציע את הטיח שבמקומו בביהכ\"נ וחלק מהרצפה שעליו הי' עומד. ותיכף בנסעם מהעירה פרצה דליקה בבית אדה\"ז. בבוא נאַפאָליעֶן להעירה התחיל תיכף לדרוש אחר איזה חפץ מחפצי אדה\"ז. ועכ\"פ דרש שיורוהו מקום שעליו הניח אדה\"ז ידו (פעם אחר ספר כק\"ש: שסו\"ס נודע ע\"י החקירה שאצל יהודי א' נשארה חבית או עריבה מבית אדה\"ז. אבל עד שבאו שליחי נאַפ' לקחתה אירע שהסיקה אשת האיש את התנור בעצי העריבה. קרוב לודאי.",[["1116","8","ראה גם לעיל ע' 151."],["1117","9","= אתה הראת — רז\"א<sup data-n=\"e47\">*</sup>. לעושה נפלאות — אדנ\"ע. אין כמוך — ר' מנחם מענדל נ\"י<sup data-n=\"e48\">**</sup>."],["1118","10","חתונת אחותו הרבנית חי' מושקא עם הרה\"ח וכו' מו\"ה משה הכהן הארענשטיין — שהתקיימה ביום ו' עש\"ק תצא יו\"ד אלול תרנ\"ב."],["1119","11","חתונת רבינו בי\"ג אלול תרנ\"ז."],["1120","12","ראה גם ספר השיחות: תרצ\"ו — חורף ה'ש\"ת ע' 112. תש\"ה ע' 13; אגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"ח ע' רסו. ע' רצט. ח\"ט ע' קיג. וראה גם לעיל ע' 62."],["1121","13","בהבא לקמן — ע\"ד נסיעת אדה\"ז בעת מלחמת נאפאלעאן — ראה אגרות­קודש אדמו\"ר האמצעי ע' רמא. רשימת המאסר — ספר השיחות תר\"פ­תרפ\"ז ע' 232. וש\"נ. רשימת רבינו — \"דברי ימי חיי אדמו\"ר הזקן\" (נדפס בספר התולדות אדה\"ז (קה\"ת — אה\"ק, תשמ\"ו) ח\"ד ס\"ע 1027 ואילך). שיחת יט כסלו תרצ\"ג סעיף ד."],["1122","14","במקומות שבהערה הקודמת: מליאדי. וראה לעיל ע' 149 הערה 50. לקמן ע' 171 (קטע המתחיל \"סיבת העתק\")."],["1123","15","ראה ספר השיחות תר\"פ­תרפ\"ז שם ובהערה 120 שם."],["1124","16","באגרות­קודש אדמו\"ר האמצעי שם: ואאמו\"ר ז\"ל צוה לנו לנסוע בשבת כי אמר שזה היתר גמור ומצוה להציל א\"ע מן המזיקים וכו'."],["1125","17","= פלוגות."],["1126","18","הרה\"ק הרה\"ח ר' מנחם נחום. בנו של אדמו\"ר האמצעי. — בכ\"ז — ראה אגרות­קודש ח\"ד ע' תסז."],["1127","19","ראה רשימת רבינו ושיחת יט כסלו שבהערה 13."],["e47","*","ראה אודותו — ספר השיחות תר\"פ­תרפ\"ז ע' 41. וש\"נ."],["e48","**","ראה אודותו — לעיל ע' 96 הערה 45."]]],[4301600364,"הכותב). בהיותם כבר בדרך נזכרו ששכחו דבר מה (פאַנטאָפעל<sup data-n=\"1128\">20</sup>. כמדומה<sup data-n=\"1129\">21</sup>. הכותב) ושלח אדה\"ז שליח להביאו. בבואם למוסקבא היתה עצת אדה\"ז שלא יעזוב חיל רוסיא את העיר. כשהביא לו האמצ'<sup data-n=\"1130\">22</sup> הידיעה שעוזב החיל את העיר. צוה גם הוא לנסוע. והיו בפלך קורסק פולטבא וכו'.\nבר\"ה<sup data-n=\"1131\">23</sup> הי' ההתחרות בין ר\"ש קרליִנער<sup data-n=\"1132\">24</sup> ואדה\"ז מי ינצח<sup data-n=\"1133\">25</sup> (א' צדד שאלכס' ור\"ש — נאפ'<sup data-n=\"1134\">26</sup>). שניהם חכו לתקיעות. מי שיתקע הא' — ינצח. ורש\"ק גם ישב בתענית ע\"ז. תיכף כשהאיר הבוקר צוה אדה\"ז שהאמצעי והחסידים ילכו עמו יחד (עם אדה\"ז) לטבול ומיד בבואו מהמקוה התחיל למנצח. ותקע. ובזה נצח. [אדה\"ז בהסתלקותו מת שלא לפי ערך שנותיו ובריאותו. כי הי' בריא אולם, ביותר]<sup data-n=\"1135\">27</sup>.\nסיבת העתק מושבו מליאזני לליאדי<sup data-n=\"1136\">28</sup> הוא<sup data-n=\"1137\">29</sup>: בתחלה חפצו בפ\"ב לגזור על אדה\"ז שישאר לדור בפ\"ב. וגרַף ליובאָמיִרסקי פעל שירשו לו לחזור למקומו. בעד זה בקש מאדה\"ז שידור באחת העירות אשר לו. הי' בין אלו ליאַדי וליובַ'. אדה\"ז נסע דרך ליובאַויץ אבל לא התעכב שם וקבע דירתו בליאַדי.",[["1128","20","נתבאר בשיחת פורים תשח\"י (לקוטי שיחות ח\"י ע' 228). שיחת אחש\"פ תשל\"ג."],["1129","21","כ\"ה (\"פאנטאפעל\") גם בשיחת יט כסלו שם."],["1130","22","= (אדמו\"ר) האמצעי."],["1131","23","ראה גם ספר השיחות תורת שלום ע' 203. התוועדויות תשד\"מ ח\"א ס\"ע 307 ואילך. תשמ\"ז ח\"א ע' 538."],["1132","24","ראה לקמן ע' 174 ובהערה 11."],["1133","25","ראה אגרות­קודש אדמו\"ר הזקן ח\"א ע' קנ­קנא. ספר השיחות תר\"פ­תרפ\"ז שם ובהערה 122. וש\"נ."],["1134","26","= אדה\"ז צדד שאלכסנדר (ינצח) ור\"ש — (ש)נאפאלעאן."],["1135","27","בקטע זה הושמטו תיבות אחדות."],["1136","28","לאחרי המאסר השני בשנת תקס\"א. וראה גם לעיל ע' 149 הערה 50."],["1137","29","בהבא לקמן — ראה אגרות­קודש ח\"ג ע' שדמ. רשימת רבינו — \"דברי ימי חיי אדמו\"ר הזקן\" (נדפס בספר התולדות אדה\"ז (קה\"ת — אה\"ק, תשמ\"ו) ח\"ג ע' 751 ואילך)."]]],[4301600365,"<h3>מוצש\"ק פ' נח<sup data-n=\"1138\">1</sup>.</h3>\nהי' מאמר צהר תעשה. נכנסתי לחדרו. אמר<sup data-n=\"1139\">2</sup>: אַזוי לעֶרנט מעֶן איִן געה\"ת. דאָס איִז אַ פשַט פון ג\"ע. צ' ת לת'<sup data-n=\"1140\">3</sup> זוהר תעשה לתיבה. ואל אמה<sup data-n=\"1141\">4</sup> און דעֶמאָלט וועֶט זײַן א' מלך העולם<sup data-n=\"1142\">5</sup>,",[["1138","1","מרשימות כ\"ק אדמו\"ר."],["1139","2","באגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"א ע' מט: \"ואסיים במילתא מרגניתא ששמעתי מכ\"ק מו\"ח אדמו\"ר שליט\"א — מוצש\"ק פ' נח רצ\"א — בהמשך למאמר דא\"ח שאמר אז — ש\"פ נח — צהר תעשה לתבה. והואיל לאמר: אזוי לערנט מען כו'\" (כבפנים)."],["1140","3","= צהר תעשה לתבה. — נח ו, טז."],["1141","4","נח שם."],["1142","5","אלקינו מלך העולם — ר\"ת אמה. — ראה גם סד\"ה צהר תעשה לתיבה ה'ש\"ת (סה\"מ ה'ש\"ת ס\"ע פד ואילך). לקוטי שיחות חלק א ע' 10. ספר השיחות תש\"נ ח\"א ע' 102 הערה 53. תנש\"א ח\"א ע' 80. ע' 392. ובכ\"מ."]]],[4301600366,"תכלינה מלמע'<sup data-n=\"1141\">4</sup>, שגם הכלים יעשו מלמע'.\nאון דער רבי<sup data-n=\"1144\">6</sup> האט געֶגעֶביִן אייֵנעֶם דעֶרמיִט חיים בשרים<sup data-n=\"1145\">7</sup> בפו\"מ.",[["1141","4","נח שם."],["1144","6","אדמו\"ר הזקן (אגרות­קודש שם)."],["1145","7","באגרות­קודש שם: בשריים."]]],[4301600367,"<h3>י\"ט כסלו תרצ\"א<sup data-n=\"1146\">1</sup></h3>\n<b>ליל א'</b>\nדער רבי<sup data-n=\"1147\">2</sup> האָט געהאַט מסירת נפש אויף דעם כלל ישראל<sup data-n=\"1148\">3</sup>, אַז דער כלל ישראל זאָל שטייגן העכער, ער איז געווען אַ דורש טוב לכל אחד מישראל ער האָט געקוקט מיט אַ עין טובה אויף יעדערן, און האָט געזוכט דעם גרעסטן לימוד זכות אויף יעדערן.\nדעם רבי'נס מסירת נפש איז געווען ניט נאָר בכח נאָר מסירת נפש בפועל, מס\"נ בכח איז אַז מיא איז ביי זיך אויפן אָרט און מיא איז זיך עוסק בתורה ועבודה ובתפלה לד' שיאיר ויפקח עיני האנשים לראות ולהכיר את האמת ואשר ישלח רוח ממרום לעורר לבות בני אדם להתקרב לדרכי העבודה, וואָס אַזוי איז געווען אין כמה זמנים אַז בעזה\"י אידישע הערצער זיינען געוואָרן וואַרעמער און אופגילעבט בדרך התעוררות מלמעלה, וואָס דאָס איז געווען בהתעוררות רחמים של הצדיקים ותפלתם במס\"נ בתעצומות עוז קדש הקדשים.\nאָבער מסירת נפש בפועל הוא מה שהצדיק מניח את עצמו לגמרי מכל וכל, וכל התעסקותו הוא להאיר אור בדרך משפיע ומקבל והיינו להכניס את עצמו בכל פרטי המקבל לפי\"ע ומצבו של התלמיד ולאו דוקא כשהוא מקבל היינו בעל כשרון אלא דכל ההתעסקות שלו לעשותו למקבל, און מאַכן אַ מקבל איז דאָס נאָר דורך דעם מסירת נפש פון משפיע, דאָס הייסט מסירת נפש פון משפיע מאַכט אַ מקבל.\nאון דאָס איז איינע פון די טעמים וואָס באַ חסידים האָט מען ניט געזוכט קיין בעלי כשרונות, דאָס הייסט מיא האָט ניט געשטעלט קיין תנאים מוגבלים פון גוטע חושים דוקא און גוטע קעפּ, דער עיקר איז גיווען אַז מיא זאָל זיין אַ בעל עבודה, יעדערער לפי כחו און דאָס איז געווען דעם רבינס שיטה, מאַכן מקבלים אָן אַ חילוק צי יענער איז אַ בעל חושים וכשרונות מופלאים או בינונים אָדער גאָר פשוטע חושים.\nמיר ווייסן אַז דער רבי איז געווען אַ מסודר, ער איז געווען אַ מופלא אויך אין דעם ענין פון סדר, אַלץ איז באַ אים געווען מסודר, אַ סדר פון תורה ועבודה, אַ סדר אין תלמידים בעלי מוחין בעלי מדות, רבנים, שוחטים, מלמדים, בעלי עסקים ואברכים הסמוכים על שולחן אבותיהם או חותניהם.\nאון פאַר יעדערן פון די אַלע סוגי",[["1146","1","נדפס בלקוטי דיבורים חלק ד תשיג, ב ואילך. בהוצאה זו ניתוספו הערות וציונים מהמו\"ל."],["1147","2","אדמו\"ר הזקן."],["1148","3","הובא ונתבאר בארוכה בשיחת י\"ט כסלו תשכ\"א."]]],[4301600368,"בני אדם האָט דער רבי אַ סדר כללי און אַ סדר פרטי ווי עס איז צו זען פון תקנות השניות וואָס זיינען געשריבן געוואָרן בליאזנא בשנת תקנ\"ח<sup data-n=\"1149\">4</sup> (ווען זיינען די תקנות הראשונות געשריבן געוואָרן ווייס איך אין­דער­וויילע ניט<sup data-n=\"1150\">5</sup>).\nאָט אַזוי זעהן מיר דעם רבי'ן אין פערשיידענע צייטן, און אין פערשיידענע ענינים אין דער צייט פון זיין וואַקסן אַלעס תלמיד קטן באַ דעם רבי'ן ר' ישכר דוב נ\"ע קאַבילניקער המגיד דליובאַוויטש<sup data-n=\"1151\">6</sup> בהיותו בן י\"ב שנה<sup data-n=\"1152\">7</sup>, וכן אנו רואים אותו בעמדו על פרשת דרכים בהיותו בן עשרים<sup data-n=\"1153\">*7</sup>, ובמהלך נפשו הק' והטהורה במעזריטש ובימי נשיאותו ובהנהגותיו עד יומו האחרון בעלמא דין, אַ ציור כללי וואָס דער רבי איז, איז אַרום נעמענדיק די אַלע הנהגות און הדרכות פון רבין, איז אַרויס זאָגן אין קורצע ווערטער, איז דער רבי געווען און ער איז אַ לב בוער ומוח שליט על הלב.\nבאַ יעדער זאַך וואָס עס גייט אַרויס פון רבין זעהן מיר ווי צוויי גרויסע וועלטן, מוח ולב קומען זעך צוזאַמען, און דורך זיי ביידן ווערט געשאַפן אַ ברייטע וועג פאַר דעם כלל ישראל, אַ וועג וואָס איז אַ דרך סלולה גלייך גוט פאַר דעם גרעסטן למדן און משכיל, און פאַר דעם גאָר גאָר פשוטן אידן.\nדער רבי האָט אונז אָפּגיעפנט די אויגן און האָט אונז באַוויזן, די גרויסקייט פון דער קלענסטער זאַך און די קליינקייט פון דער גרעסטער זאַך.\nחסידות לערנט אונז פאַרשטיין און פילן דעם אמת פון אמת, זעהן אין יעדער זאַך דעם גשמי ורוחני, דעם גוף און די נשמה, איידלען דעם גשמי און ציען זיך צו דעם רוחני.\nדער רבי זאָגט אַז אַלץ בעדאַרפמען אָנהויבן פון זיך אַלץ זיך אויסבעסערן, יעדער קלייניקייט פון ניט קיין גוטע זאַך, וואָס אין זיך איז פאַראַן אין מדות אָדער אין הנהגת בני אדם זאָל זיין אַ פולע גרעסער און פאַרנעמען מער אָרט ביי זיך, ווי די גרעסטע בעסטע זאַך פון גוטע וואָס באַ זיך איז יע פאַראַן. וואָרום די ביסעלע ניט גוטע, קען איבערפירן די גוטע, והוא אומר אַז אַביסעלע גוטע דורך תשובה ועבודת הלב קאָן בעזרת השם יתברך ברענגען אַ רפואה שלמה צו אַלע חולאתן ר\"ל פון מדות רעות.\nדאָס איז דער יסוד העבודה פון תורת החסידות דאָס מאָנט דער רבי באַ אונז און דאָס איז דער יסוד החסידות וואָס אבותינו רבותינו הקדושים האָבן אונז געגעבן, און אונז מדריך געווען.\nדער רבי האָט מחנך געווען יונגעלייט, געוויס האָט ער געזוכט בעלי כשרון ובעלי חוש אויך, אָבער דער עיקר וואָס ער האָט מחנך געווען אַז מיא זאָל זעהן דיא גרעסטע אמתע גרויסקייט",[["1149","4","אוצ\"ל: תקנ\"ה — ראה \"התמים\" חוברת ב ע' לה [סה, א]. אגרות­קודש אדה\"ז ח\"א ע' סה."],["1150","5","לאח\"ז בשנת תרצ\"ו כשנדפסו ה\"תקנות הראשונות\" ב\"התמים\" חוברת ב (ע' לב [סד, ב]) כתב המערכת: \"כפי שיכולים לשער הנה התקנות הראשונות נערכו בשנת תק\"מ­ג בערך\". וראה גם מקורות והערות לאגרות­קודש אדה\"ז ח\"א ע' תל."],["1151","6","ראה אודותו — בספר הזכרונות חלק א פרק ז. שיחת חג הפסח תרצ\"ד סעיף ג. ועוד."],["1152","7","כ\"ה גם בבית רבי חלק א פרק א. וברשימת רבינו ב\"בטאון חב\"ד\" גליון 39­38 ע' 37 שכשנתמלאו לאדה\"ז י\"א שנה התחיל ללמוד עם ר' ישכר דוב. ובספר השיחות קיץ ה'ש\"ת ע' 96: בן עשר."],["1153","*7","ראה ספר השיחות תש\"ו ע' 23 הערה 6."]]],[4301600369,"אין דעם תמימותדיקן דאַוונען, אמן יהא שמי' רבא, און מדות טובות שבטבע ורגילות פון יעדער גאָר גאָר פשוטן אידן.\nגרויסע יסורים איז דער רבי אויסגעשטאַנען צוליב חסידים, דאָס הייסט צוליב מאַכן חסידים. בכלל איז דער דרך דעם רבין אַליין אויך גרינג ניט אָנגעקומען, יעדער דבר פנימי קומט אָן שווער, און בפרט אַ דבר פנימי וואָס איז פאַרבונדן מיט פנימית המוח און פנימית הלב, קומט געוויס אָן זייער שווער.\nאַלטע חסידים וואָס האָבן געהאַט גאָר אַ אַנדער דערהער אין אַ ענין, זיי האָבן געהאַט אַ טיפן געפיל אין יעדער זאַך האָבן אָנגעציילט צעהן יסורים אין פערשיידענע אופנים.\nדער גיין אין מעזריטש, צוויי קפידות פון הצדיק הקדוש ר' פנחס'ן (בעל הפלאה)<sup data-n=\"1154\">8</sup>, די התנגדות פון זיינע גוטע בעקאַנטע גאונים פון שקלאָוו, מהליב וכו' פאַר זיין גיין אין מעזריטש, די שוועריקייטן אין הכרעת דינים בשו\"ע, תלונת התלמידים הישנים ובראשם הצדיק הקדוש ר' ברוך זצ\"ל על דרכי ושיטת חסידות חב\"ד<sup data-n=\"1155\">9</sup>, הויכוחים עם המנגדים, תלונת חביריו צדיקי וואלין על אשר לא חפץ להשתתף עמהם להטיל חרם ר\"ל על המנגדים<sup data-n=\"1156\">10</sup>, העבודה בהחזקת יושבי אה\"ק ת\"ו, ותלונת הצדיק הקדוש ר' שלמה נ\"ע מקארלין<sup data-n=\"1157\">11</sup> על",[["1154","8","לע\"ע לא מצאתי במק\"א ע\"ד קפידת הרה\"ק ר' פינחס הלוי הורביץ (בעל ההפלאה) על אדמו\"ר הזקן, ואדרבא, ידוע ע\"ד האהבה וחיבה ששררה ביניהם — ראה אגרות­קודש אדה\"ז ח\"א ע' קיג. בית רבי חלק א פרק כה (סה, א ואילך). וראה הקדמת בני הגאון המחבר לשו\"ע אדה\"ז. ועוד."],["1155","9","ראה בית רבי חלק א פרק כא. וראה גם אגרות­קודש אדה\"ז ח\"א ע' קטו. ע' רב. ע' רטז."],["1156","10","ראה רשימת רבינו הנקרא \"דברי ימי חיי אדמו\"ר הזקן\". ספר השיחות תרצ\"ו ע' 80 ואילך."],["1157","11","בספר סיפורי חסידים להרש\"י זוין (ע' 208 ואילך) מעתיק השיחה שבפנים, ובמכתב כ\"ק אדמו\"ר אליו (אגרות­קודש חלק טו ע' תנ. והמשכו שם חלק טז ס\"ע רלח) כ': \"רווח הנוסח דבר פלוגתי' דאדה\"ז בהנוגע למלחמת נפאליאן הי' הרה\"צ וכו' מהר\"ש מקרלין. וכן הועתק בס' [סיפורי חסידים] הנ\"ל.\nואינו, ע\"פ המובא בסדה\"י שהנ\"ל נהרג על קדה\"ש הרבה שנים לפני מלחמה זו.\nכמדומה ראיתי מכבר באיזה ס' שהעיר ע\"ז. וי\"א שהבר פלוגתי' הי' המגיד מקוזניץ\". עכ\"ל<sup data-n=\"e49\">*</sup>.\nוראה גם רשימת אדמו\"ר הזקן משנת תקנ\"ט (אגרות­קודש שלו ח\"ב ע' לח): ומ' שלמה ג\"כ נפטר זה זמן רב.\nאמנם עפמ\"ש רבינו באגרות­קודש ח\"ב ע' שסט שהרה\"ק ר' שלמה מקארלין \"ביקר את כ\"ק רבינו הגדול בליאזנא, בשנת תקנ\"א­ב' (כי פעמים הי' בליאזנא בשנת תקנ\"א­ב', ובשנת תקנ\"ה­ו', ואחרי כן כשלשה פעמים בליאדי)\", נמצא שבשנת תקס\"א, השנה שבה הגיע אדה\"ז לליאדי<sup data-n=\"e50\">**</sup>, עדיין הי' הרה\"ק ר' שלמה מקארלין בעלמא דין. וראה גם אגרות­קודש אדה\"ז ח\"א ע' רח (מהגניזה החרסונית). לעיל ע' 171."],["e49","*","בבית רבי חלק א פרק כב הערה א (מה, ב): \"בסיפורים הנדפסים מכבר כתוב שרבינו הי' מחולק אז עם הרה\"ק ר\"ש מקארלין נ\"ע שרבינו התפלל בעד ממשלתנו והרר\"ש התפלל שתגבור עם צרפת כו'. . אך אין זה אמת כי הרה\"ק ר\"ש נ\"ע נפטר שנים הרבה מקודם כי הוא נפטר בשנת תקנ\"ב שהתחילה ממשלתנו לכבוש לגמרי את מדינת פולין ואז הי' ההתחלקות ביניהם שכאו\"א קיים מארז\"ל הוי מתפלל שלומה של מלכות. . וע\"כ הרר\"ש שהי' תחת ממשלת פולין התפלל עבורה, ורבינו שהי' תחת צל ממשלתנו הרוממה התפלל עבורה. וב\"ה שרבינו יצא המנצח. . אבל בעת מלחמת צרפת שמענו מאחד הרבנים מנכדי רבינו שרבינו הי' מחולק אז עם הרה\"ק המגיד מקאזניץ נ\"ע. . וב\"ה שגם אז הי' רבינו המנצח בתפלתו כו'\". וראה גם בית רבי פרק כה (סד, ב)."],["e50","**","ראה גם לעיל ע' 171."]]],[4301600370,"אשר הי' נגד נאַפּאליאן<sup data-n=\"1158\">12</sup>.\nושאל אחד מהיושבים פאַר וואָס רעכנט מען עפּעס ניט דעם זיצן, אין פּעטראָפּאַוולאווסקין קרעפּאסט און דאָס איז דאָך דער יום טוב של גאולה.\nוהשיב כ\"ק אדמו\"ר שליט\"א יע י\"ט כסלו איז אַ יום טוב, היום הרת עולם, היינט זיינען חסידים געבאָרן געוואָרן, און בכל שנה ושנה איז דאָס דער ראש השנה פון חסידות, דער רבי האָט געהאַט מסירת נפש אויף חסידים ניט אויף חסידות, חסידות איז דער פאַרשטאַנד און חסידים איז די עבודה. דער רבי האָט געהאַט מס\"נ אויף עבודה מיא זאָל זיך ניט נאַרן, מיא זאָל אַלע מאָל און אין אַלע צייטן, וויסן וואו מיא שטייט אין דער וועלט.\nנאָר דאָס וואָס ער איז געזעסן אין פּעטראָפּאַוולאווסקין קרעפּאסט האָבן אַלטע חסידים גערעכנט איינע פון די צעהן זכותים וואָס דער רבי האָט זוכה געווען<sup data-n=\"1159\">13</sup>.\nבאַ אַ פנימי איז יעדער זאַך הן גוטע אָדער חלילה פאַרקערט אַ טיפע איבערלעבונג, ווי מיר זעהן במוחש אין טבעי בני אדם פאַראַן אַזעלכע וואָס הן די גוטע כו' לעבן זיי דאָס גרינג און געך איבער, דאָס רופט מען אַ חיצון ניט קיין יסודותדיקער מענטש, דאָס איז אַ קל הדעת, דעת איז דאָך התקשרות<sup data-n=\"1160\">*13</sup> צוגעבונדן און איינגעשלאָסן מיט דעם וואָס ער איז פאַרבונדן, און קל הדעת הייסט אַ גרינגער און שוואַכער פאַרבונד, אָבער באַ אַ פנימי איז אַלץ טיף, אַלץ קומט פון פנימיות המוח און דערלאַנגט אין פנימית הלב, ומכל שכן אַ עצמי דאָס איז שוין גאָר אַ אַנדער זאַך.\nדער רבי איז געווען אַ עצמי<sup data-n=\"1161\">14</sup>, לבד זאת וואָס בכלל נשמות הגבוהות זיינען אין דער מדריגה פון עצמי ניט התפשטות (כידוע בענין הב' מדריגות שבאור, אור מתפשט ואור עצמי) ומכל שכן נשמה דאצילות<sup data-n=\"1162\">15</sup>, איז דער רבי געווען אַ עצמי מצד העבודה, והיינו זיין עבודה איז געווען אין דער מדריגה ווי אַ משפיע וואָס מקבלים קאָנען האָבן אין דעם אַ קצת תפיסא והשגה.\nאין דעם עצם המוחין ומדות פון רבי'ן קאָנען מיר קיין שום השגה ותפיסא ניט האָבן, באַ אונז איז דאָס במופלא ממך אל תדרוש ובמכוסה ממך אל תחקור<sup data-n=\"1163\">16</sup>. וואָס מיר קאָנען יע עפעס האָבן אַ אפס קצה השגה ותפיסא איז אין מעשה כמו שנראה הנהגת רבינו עם תלמידיו, עם חסידים מיט סתם אידן, אין יעדער הנהגה, אין יעדער וואָרט, פון יעדער אגרת הקדש וואָס דער רבי רעט בעניני התפלה, הן בהעבודה פנימית שבתפלה והן בהאזהרה הגדולה שלא",[["1158","12","ראה אגרות­קודש אדמו\"ר הזקן ואדמו\"ר האמצעי ח\"א ע' ע' קנ­קנא. ע' רלז ואילך. ספר השיחות תורת שלום ע' 203. ספר השיחות תר\"פ­תרפ\"ז ע' 232. וש\"נ. לעיל ע' 171."],["1159","13","ראה שיחת ליל ב יט כסלו שנה זו (לקמן ס\"ע 181 ואילך."],["1160","*13","ראה תניא ספ\"ג. פמ\"ב. ובכ\"מ."],["1161","14","ראה ספר השיחות תורת שלום ע' 166. לעיל ע' 89. וש\"נ."],["1162","15","תורת שלום שם. מאמר אבות החסידות — \"התמים\" חוברת ב ע' מג [סט, א]."],["1163","16","חגיגה יג, א."]]],[4301600371,"לדבר בעת התפלה, וכן בעניני ההדרכה במדות טובות איז אין יעדער וואָרט ליגט אַ שטיק עצמי, אַ שטיק לעבן, אַלץ איז ערנסט, טיף אויסגעוויינט, עס פילט זיך אַז די ווערטער גייען פון אַ ווייטן טיפן, שטאַרקן קוואַל. איצטער באַ אונז איז דאָך דעם רבינס ווערטער גע­שריבענע ווערטער, געדרוקטע ווערטער אויף פּאַפּיר, אָבער די געדרוקטע און געשריבענע ווערטער לעבן מיט אַ חיות פנימי, די ווערטער אַליין שרייען פון זיך אַליין, די דברים הקדושים וואָס יוצאים מהלב בוער, ברענט נאָך ב\"ה איצטער בלבת אש קדש ווי זיי זיינען אַרויס ממקורם ושרשם, זיי שרייען זיי בעטן זיי הייסן. אָפּ­לערנענדיק דעם רבינס עטלעכע שורות פון אַ אגרת (הן מהנדפסים והן אשר בכתובים) אַריין נעמענדיק די ווערטער אין קאָפּ איז די ווערטער אַליין זיינען מעורר און עס פועלט אין קאָפ און אין האַרצן.\nדעם רבי'נס אגרות<sup data-n=\"1164\">17</sup> בהנוגע קופת רמבעה\"נ זיינען ברענענדיקע ווערטער אַ אזהרה ופקודה לדורות, און אַ הבטחה בברכת בני חייא ומזונא לדורי דורות. וויפל לעבן האָט דער רבי אָפּ געגעבן אויף עניני ארץ הקודש ת\"ו, ווי עס איז ידוע איז דער בעל שם טוב אויך געווען אַ נשיא פאַר ארץ הקדש ת\"ו ווי ער שרייבט אין איינעם פון זיינע בריוו<sup data-n=\"1165\">18</sup> אשר מעתה מן השמים קא זכו לי' להיות הראש והגבאי גם על פרנסת הנסתרים דארעא דישראל, כן מורינו הרב המגיד ממעזריטש נ\"ע האָט געטאָן לטובת קופת רמבעה\"נ<sup data-n=\"1166\">19</sup>, ורבינו הגדול נ\"ע הוסיף אומץ בעבודת הקדש, וכידוע אשר הבטיח לכל החבורא קדושה מהתלמידים אשר נסעו עם הרה\"צ הקדוש רמ\"מ זצ\"ל כי בעזה\"י פרנסתם תהי' בטוחה<sup data-n=\"1167\">20</sup>, און בגלל זאת האָבן מיר זוכה געווען די אגרות הקדש.\nאונזערע טאַטעס און זיידעס האָבן אויף זיך מקבל געווען לדורותיהם מחזיק זיין לומדי תורה אין ארץ ישראל, מיא דאַרף וויסן אַז דאָס האָבן זיי מקבל געווען אויף זיך לדורותיהם באלה ובשבועה על דעת המקום שאין לו הפרה לעולם, געוויס איז די הבטחות און ברכות פון רבין אויך לדורותיהם, דאַרף יעדער איד און אידענע וואָס זיינען מגזע החסידים וויסן אַז אין וואָס פאַר אַ מדינה זיי זיינען דאַרפן זיי האָבן אַ פּושקע פון כולל חב\"ד וואָס מיט דעם זיינען זיי מקיים דעם צוזאָג פון זייערע עלטערן ז\"ל, מיט דעם זיינען זיי מזכה די נשמות פון זייערע עלטערן ז\"ל און מאַכן זיי אַ קורת רוח אין גן עדן און מיט דעם וועלן זיי זוכה זיין צו די הבטחות און ברכות פון רבי'ן וואָס ער בענטשט לדורי דורות די אַלע וואָס וועלן מקיים זיין זיין פקודה געבן ארץ ישראל געלד אויפן כולל חב\"ד ודברי צדיקים וברכותיהם חיים וקיימים לעד.\nדי אַלע תירוצים וואָס איז איצטער פאַראַן פאַר וואָס מיא איז זיך ניט עוסק בתורה ועבודה שבלב ווי חסידות מאָנט<sup data-n=\"1168\">*20</sup>, איז באמת דאָך געווען אין אַלע צייטן און אין די פריערדיקע דורות",[["1164","17","כו\"כ נדפסו באגרות­קודש אדה\"ז ח\"א­ב. וראה ספר תולדות חב\"ד בארה\"ק ע' לט ואילך. ע' ח ואילך. וראה גם שיחת ליל יט כסלו תרצ\"ב. ספר השיחות תנש\"א ח\"ב ע' 614 ואילך."],["1165","18","\"התמים\" חוברת ה ע' ל [רכז, ב]."],["1166","19","ראה \"התמים\" חוברת ז ע' כו [שלא, ב]. ספר השיחות תש\"ח ע' 181."],["1167","20","ראה בית רבי חלק א פרק ו (ז, ב). פרק ח (יב, ב). ספר תולדות חב\"ד בארה\"ק ע' ח ואילך."],["1168","*20","ראה גם לעיל ע' 151 ואילך."]]],[4301600372,"אויך, זיי האָבן נעבעך אויך געהאַט ל\"ע גרויסע עניות ודחקות, און מכל מקום האָט מען געטאָן, עס איז געווען עבודה, רבנים האָבן געוואוסט אַז אויף זיי ליגט דער עול הקדש פון הדרכה, בעלי בתים האָבן געוואוסט אַז זיי דאַרפן הערן וואָס די רבנים זאָגן, עס איז געווען דער כבוד התורה און דער עול העבודה.\nשוחטים האָבן געוואוסט אַז זיי זיינען עמודי בית ישראל<sup data-n=\"1169\">21</sup>, זיי האָבן גיטראָגן אויף זיך עול תורה הן אַליין געלערנט אַ ריבוי זמן (לבד ההלכות והדינים המחויבים להיות בקיאים ולחזור עליהם תמיד<sup data-n=\"1170\">22</sup>) און אויך געלערנט בחבורה פאַר בעלי בתים, בפרט חסידישע שוחטים זיינען געווען פאַרנומען מיט לימוד חסידות בכתב ובעל פה און מיא איז געלעגן אין דאַוונען. דאַוונען האָט פאַרנומען אַ גרויסן אָרט אין דעם עבודת היום, דער פאַרן דאַוונען מיט דעם נאָכן דאַוונען איז געווען אַ עבודה. דער דאַוונען אַליין איז געווען באַ חסידים אַ שכר טוב, אַז עס האָט זיך געדאַוונט האָט זיך געדאַוונט, עס האָט זיך געלעבט, און אַז עס האָט זיך ניט געדאַוונט, האָט זיך געוויינט, די האַרץ האָט געוויינט פאַר וואָס דאַוונט זיך ניט. אָבער דער פאַרן דאַוונען און נאָכן דאַוונען איז געווען אַ עבודה, מיא האָט ניט געהיילט, מיא האָט געוואוסט אַז דאָס איז דער מקור חיים, מיא איז געלעגן אין אַ בירור וזיכוך פון אַ מדה, מיא האָט געהאַלטן זיך אַליין אין האַנט, מיא האָט געקוקט אויף זיך אַליין זייער שטאַרק, ניט גינאַרט, מיא האָט דערהערט דעם אַנדערן, דעם אַנדערנס גשמיות און ווער רעדט דעם אַנדערנס רוחניות איז געווען זייער נוגע, מיא האָט אַליין געוואָלט לעבן אַ לעבן פון תורה ועבודה און מיא האָט געוואָלט אַז דער אַנדערער זאָל לעבן.\nאַמאָליקער חיבת התורה און חיבת הקדש האָט אַרום גינומען די אידישע הויז, די טייערקייט פון אַ ערליכן אידן, די הייליגקייט פון די אותיות און נקודות<sup data-n=\"1171\">*22</sup> איז געווען איינגיבאַקן ביי יעדער איד און אידענע. די גליקלעכקייט פון יעדער אידישער הויז אַז מיא האָט דערלעבט דעם קינד פירן אין חדר, צו אַ מלמד אַ ערליכן אידן מיט אַ חיות, וואָס האָט זיך מוסר נפש געווען איינפלאַנצן יראת שמים אָפּ גיסן נעגל וואַסער, שלאָפן אין יאַרמולקע, זאָגן ברכות, לייענען קריאת שמע, ענטפערן אמן יהא שמי' רבא, פאָלגן דעם טאַטן און מאַמען, בענטשן ציצית אויף דעם ארבע כנפות, און די פאות האָבן טאַטע און מאַמע אַכטונג געגעבן, די גרויסע שמחה פון בר מצוה, און דער גרויסער נחת רוח וואָס מיא האָט געהאַט פון דעם קינד וואָס איז אין דער ישיבה.\nאיצטער איז אוי מה הי' לנו, עס איז ביטער אויפן האַרצן, אַ ביטערע קעלט, אַ פראָסט אין דער אידישער הויז, פון אַלע זייטן בלאָזט אַ ווינט, עס איז דאָך אפילו נקרש הדם, פאַרקילטע בלוט. אַז מיא האָט געבראַכט אַ קרבן אין בית המקדש, און אַלץ איז געווען כשר כדינו והלכתו לשם זבח ולשם זובח<sup data-n=\"1172\">23</sup>, בזמנו ובמקומו, האָט מען געדאַרפט טאָן שלא",[["1169","21","ראה לעיל ע' 44."],["1170","22","ראה רמ\"א יו\"ד הל' שחיטה ס\"א ס\"א. שו\"ע אדה\"ז שם ס\"ק יג. אגרות­קודש אדמו\"ר האמצעי ח\"א ע' שיב."],["1171","*22","ראה לעיל ע' 44. וש\"נ."],["1172","23","זבחים ב, ב. מו, ב."]]],[4301600373,"יקרש הדם<sup data-n=\"1173\">24</sup> וכתיב<sup data-n=\"1174\">25</sup> כי הדם הוא הנפש, דם איז אַ כלי צו חיות, און פירט פאַנאַנדער דעם חיות אין אַלע אברים, וואָס דאָס איז דאָך דער דופק רצוא ושוב, היינט איז נקרש הדם ח\"ו, אַז אפילו די וואָס ברענגען שוין אַ קרבן מיא מאַכט אַ חדר, איז ווער איז דער מלמד, און אַ מלמד אַ ערלעכן אידן וויל מען ניט, מיא זוכט מעטאָדעס אַז דער מלמד איז אַ קענער איז שוין אַלץ כשר, קיין יראת שמים פעלט ניט, קיין קדושת האותיות און קדושת הנקודות איז ניט נוגע, מיא איז פאַרקילט, נקרש הדם, עס איז ניטאָ קיין חיות אין קיין זאַך, חסידים לערנען ווייניג חסידות און אַז מיא לערנט יע אַמאָל איז דאָס ווי אַ נדבה עס איז ניטאָ קיין אהבת רעים קיין פאַרברענגען צווישן זיך, עס איז ר\"ל נקרש הדם ח\"ו און ווער רעדט מכח אַ עבודה בתפלה מיט אַ לעבן, ווי באַ גאָר געוויינליכע אַלטע חסידים איז געווען.\nמיר האָבן אַ תירוץ, זייער אַ ביטערער, זייער אַ טוטווייער תירוץ, דער מצב העולם די וועלט איז גיפאַלן, עס איז איבעריג צו ריידן יעדערער ווייס אַליין וואָס ער טראַכט. דער תירוץ איז אַ תירוץ, אָבער יעדערער מוז זיך פאַרטראַכטן און פרעגן באַ זיך אַליין צי איז דאָס אַ תירוץ. אמת טאַקע דער עולם ווערט פאַרפּראָסטעט, די אברים פון דעם בית ישראל זאָלן געזונט זיין ווערן שוואַך, ווער איז אָבער שולדיק, שולדיק איז נקרש הדם, די פאַרקילטע בלוט.\nאמת מיא דאַרף איצטער ריידן מכח זאַכן וואָס אַמאָל האָט מען מכח דעם ניט געדאַרפט ריידן, מיא רעט איצטער באַ אַ חסידישן פאַרברענגען וואָס אַמאָל האָט אפילו קיין מוכיח ניט געדאַרפט מכח דעם דערמאָנען. אַמאָליקע יאָרן וואָס פאַר אַ שלעכטער מצב אין פרנסה ל\"ע עס איז געווען האָט מען ניט גידאַרפט דערמאָנען מכח שמירת שבת, הנחת תפילין, שמירת טהרת המשפחה, מחנך זיין די קינדער באַ ערליכע מלמדים, און לערנען אלף בית קמץ אלף וכו'<sup data-n=\"1171\">*22</sup>.\nאמת עס איז שטאַרק טוטוויי אַז מיא דאַרף וועגן אַזעלכע זאַכן ריידן, אָבער אַז מיא דאַרף ריידן, אַז עס איז געקומען דערצו, מוז מען ריידן, און ריידן, פון טיפן האַרצן, זאָגן דעם גאַנצן אמת ווי ער איז, ניט פאַרפּוצן און צו שמייכלען ווי יענער טוט, השומע ישמע, אַ איד דערהערט אַ אמת, אַ אידישע האַרץ איז דער חלק אלוקה דער נקודת היהדות, און אַז איין איד אָדער איין אידענע דערהערט דעם אמת וואַקסט אויס אַ כשרער איד, און איין איד איז אַ בוים וואָס וועט בעזה\"י ברענגען אַפולע גוטע פירות וברכה בבית ישראל און דער נסיון האָט געוויזן אַז בעזה\"י אַז מיא איז אין דעם מצליח, ווי ביטער שלעכט ח\"ו דער מצב היהדות איז אין אייניגע ערטער זעהן מיר במוחש אַז לב ישראל חי הוא, און אַז די האַרץ לעבט קאָן דער גאַנצער גוף געזונט ווערן.\nאיך האָב היינט אַ בשורה טובה, אַ קאַרטל פון אַ וועלטישן געלערנטן יונגערמאַן וואָס שרייבט מיר אַז ער האָט מיך געפאָלגט, און האָט מיט אייניגע יונגע לייט גערעט און האָט ב\"ה פועל געווען בשמירת הכשרות. מיט עטלעכע וואָכן פריער האָב איך מקבל געווען אַ בריף פון איינעם אַ יונגערמאַן וואָס וויל און דאַרף פאָרן אין אַ אָרט צוליב זיינע זאַכן און בעט אַ ברכה אַז",[["1173","24","ראה מנחות כא, א."],["1174","25","ראה יב, כג."],["1171","*22","ראה לעיל ע' 44. וש\"נ."]]],[4301600374,"השי\"ת זאָל עם מצליח זיין, איך האָב עם אויף זיין בריף געענטפערט, און דרך אגב געשריבן אַז ער זאָל האָבן אַ שיעור לימוד בכל יום, וואָס איך האָב עם געשריבן און ערקלערט אַז אויף יעדער יונגערמאַן ליגט אַ חוב קדוש ווירקן אויף דער סביבה, אין דעם זין פון שמירת קיום המצות, און ווי ער איז דאָך אין אַזאַ אָרט וואָס זיינען דאָ נאָך יונגעלייט זאָל ער זעהן פירן שמועסן מכח שמירת שבת והנחת תפילין, כשר, ביז ער זאָל צו ברענגען מיא זאָל עפּעס לערנען.\nדעם יונגערמאַן קען איך ניט, אָבער דער ערשטער בריף זיינער איז געווען אמונה'דיק געשריבן, תמימות'דיק, אָן אייבער המצאות, און מיר האָט גיצייגן די האַרץ אים שרייבן וואָס איך האָב געשריבן.\nאין דער צייט האָב איך שוין פון עם געהאַט עטלעכע בריף, ער האָט שוין ב\"ה זייער אַפולע דורך געמאַכט, עטלעכע היטן שוין ריכטיק אָפּ וואָס מיא דאַרף, ער האָט שוין 6­7 חברים טובים, וואָס זיי זיינען שוין געוואָרן אין דער דרגא פון ליגן אין דעם ווי ווירקט מען אויף די איבעריקע, אַז זיי זאָלן זיין שומרי מצוה.\nווייא איז די יאָרן מיט וואָס מיא קוויקט זיך, אַז ב\"ה מיא לייגט תפילין, און מיא עסט כשר, מיא לערנט אַ פרשה חומש מיט רש\"י און מיא זאָגט אַ קאַפּיטל תהלים. אָבער אין אַזא מצב איז דאָס ב\"ה.\nאַ חולה מסוכן ר\"ל אַז השי\"ת העלפט און ער האָט בכח מאַכן אַ טראָט וועט השי\"ת העלפן און ער וועט ווערן אַ בריא.\nאַזעלכע פעל האָב איך געזען ב\"ה גאָר אַפולע אַז מיא איז מעורר ווערט מען נתעורר, די אברים זיינען טאַקע שוואַכע, אָבער אַז די בלוט איז געזונט, אַז עס איז רצוא ושוב מיט אַ חיות, גיט דאָס אַ חיזוק אין די אברים און זיי ווערן געזונט באמת.\nמיר דאַרפן תמיד געדענקען דאָס וואָס דער רבי האָט אונז געלערנט, זעהן אין יעדער קלייניקייט די גרויסקייט, קוקן אויפן זולת ניט נאָר בעין טובה, נאָר בעין יפה.\nטויזנטער טויזנטער יונגעלייט ווערן ח\"ו פאַרפאַלן איבער דעם נקרש הדם, די קאַלטקייט, און די גלייכגילטיקייט, וואָס האָט אַרומגענומען אַ טייל פון די יראי אלקים און בקרב אנ\"ש שי', די רבנים און די שוחטים, מיט די מלמדים און בעלי בתים. בני תורה האָבן געדאַרפט טאָן אין החזקת התורה, ניט נאָר יוצא זיין וואָס מיא העלפט די ישיבות מיא גיט אַ נדבה מיט דעם איז מען יוצא. ניין מיא דאַרף אַליין אויך לערנען, און מיא מוז פועל זיין אויף די בעקאנטע אַז זיי זאָלן קומען אין שול לערנען די שיעורים, אויף דעם דאַרף מען האָבן מסירת נפש, ליגן אין דעם בכל כחו.\nאנ\"ש שי' דאַרפן האָבן שיעורים פון לערנען חסידות בזמנים קבועים בכל מקום ומקום לפי תנאי המקום, מכח דעם האָבן מיר שוין אַפולע מאָל גערעט, און ב\"ה אין היפּש ערטער איז מען מקיים, וברכות יחולו על ראשם.\nדער רבי האָט פותח געווען דעם צינור פון מסירת נפש אויף תורה ועבודה שבלב און עס איז ידוע<sup data-n=\"1176\">26</sup> אַז",[["1176","26","ראה אגרות­קודש ח\"א ע' קצז. ע' רעג. ח\"ב ע' עז. ע' שפה. ח\"ד ע' דש. ח\"ו ע' עדר. ח\"ז ע' כג. ח\"ח ע' תקג. ח\"ט ע' רפט. ע' תכב. חי\"א ע' קא. ע' קמה. לעיל ע' 21. לקמן ע' ס\"ע 181. ועוד."]]],[4301600375,"דער רבי האָט געזאָגט אַז דעם כח און זכות פון זיין עבודה אויף תורת ודרכי החסידות גיט ער אַוועק חסידים לדורותיהם, אַז בכל עת ובכל מקום וואָס אַ חסידישער איד וועט מעורר זיין בחיזוק התורה והעבודה ובחיזוק קיום המצוות, בתיקוני המדות ואהבת רעים זאָלן זיי מצליח זיין, אין דעם פינסטערשטן ווינקל, השי\"ת זאָל רחמנות האָבן און מאַכן ליכטיג בגשמיות ורוחניות, איז אַז ס'קומען זיך צונויף הייפטלעך אידן, און יונגע לייט און מיא לערנט, מיא לערנט חסידות, און מיא פערברענגט וואָס יעדער טראָט איז מסירת נפש בפועל, איז דעם רבינס ברכה שטאַרקט זיי און היט זיי, ניט נאָר חסידים פון גזע אנ\"ש שי' נאָר יראי אלקים שומרי תורה ומצוות חסידים און מתנגדים, אין וואָס פאַר אַ מדינה עס זאָל ניט זיין, במרחבי תבל ומלואה איז דעם רבינס ברכה עליהם ועל זרעם בגשמיות וברוחניות, וויילע דער רבי האָט געהאַט מסירת נפש אויף דעם כלל ישראל.\nדער רבי האָט גיעפנט דעם צינור פון מסירת נפש, און האָט געוויזן די וועג פון עבודה, אַז מיא דאַרף אַליין טאָן, ניט נאָר בממונו נאָר טאָן בגוף מיט טרחה, און מיט דעם נפש, אַוועק געבן דעם גוף און דעם נפש מיט מסירת נפש בעבודה, דזהו מעלת אאע\"ה לגבי הצדיקים שקדמו לו<sup data-n=\"1177\">27</sup> שהיו צדיקים גדולים לעצמם, וגם התפללו על בני דורם, אבל אאע\"ה הוסיף ענין העבודה ללמדם דעת ולפרסם אלקותו ית' בעולם, אאע\"ה<sup data-n=\"1178\">28</sup> אַז עס איז צו אים געקומען אַ ערבי האָט ער זיך מיט אים מטפל געווען געגעבן עסן און טרינקען און געגעבן אים צו פארשטיין נאָך זיין ערבישן שכל נאָך, וואָס געטליכקייט איז, און אַז עס איז דאָ אַ בורא יחיד ב\"ה וואָס האָט בעשאַפן די וועלט און אַז דער מענטש דאַרף האָבן מדות טובות. וכן הוא ברבינו נ\"ע אשר לימד דעת את ד' ופתח הצינור דמסירת נפש על עבודה, ובכח זה ביכולתינו בעזה\"י גם אין דער צייט להאיר את העולם, באור תורה ועבודה שבלב, והתחלת העבודה הוא הרבצת התורה היינו לבד זה שיוסיפו אומץ בהחזקת הישיבות, זאָל מען זעהן אַז בעלי בתים בעלי עסקים זאָלן קומען לערנען בבתי כנסיות דאָס זאָל גיטאָן ווערן מיט אַ קאָך און מיט א חיות עס זאָל זיך ניט געפינען איין איד וואָס זאָל ניט קומען צום לערנען, און מיא זאָל מקרב זיין יונגעלייט זעהן געבן זיי אַ האַנט אָן וואָס זיי זאָלן זיך קאָנען אָנהאַלטן, אַז זיי זאָלן ווערן בעזה\"י נעהנטער צו אידישקייט, מיא דאַרף ריידן ברבים מיא דאַרף זיי מעורר זיין, וועלן זיי געוויס נתעורר ווערן.\nצדקה תרומם<sup data-n=\"1179\">29</sup> דע\"י פועל טוב נעשים מוחו ולבו זכים אלף פעמים ככה<sup data-n=\"1180\">30</sup>, אַז אַ איד אַ בן תורה, וואָס קאָן אַפולע לערנען, און איז אַ חסיד אויך וואָס זיינע אַ שעה איז זייער טייער, און",[["1177","27","ראה סה\"מ ה'ש\"ת ע' 29. לקוטי שיחות חלק ג ע' 776."],["1178","28","ראה סוטה י, א ואילך. ב\"ר פמ\"ט, ד. סה\"מ תרפ\"ט ס\"ע 98. וש\"נ."],["1179","29","משלי יד, לד. ראה סה\"מ תרפ\"ט שם ואילך."],["1180","30","ראה תו\"א בראשית א, ב. ועם הגהות — אוה\"ת שם ח\"ו תתרכו, ב ואילך. סה\"מ תרל\"ח ע' רלב ואילך. ספר השיחות תש\"ג ע' 10."]]],[4301600376,"ער גייט צו צו אַ יונגן מאַן און רעט מיט אים אַ שעה און צוויי גאָר אַזאַ פשוטע זאַך ווי לייגן תפילין, אָדער שמירת הטהרה וכו', וואָס מכח דעם האָט מען גאָר ניט גידאַרפט ריידן, איז די צוויי שעה אַ פולע טייערער ווי לערנען דעם טיפסטן ענין אין נגלה אָדער אין חסידות וויילע דאָס איז עבודה בפועל ממש, און ווי די גמרא<sup data-n=\"1181\">31</sup> זאָגט ומתוך שחסידים המה תורתם משתמרת ומלאכתם מתברכת.\nאון דאָס איז די זאַך פון מסירת נפש זיך מוסר נפש זיין צוליב יענעם<sup data-n=\"1182\">32</sup>, אָט די צוויי שעה וואָס ער וואָלט לערנען נגלה צי חסידות און פון דעם לערנען וואָלט גיוואָרן אַ תוספות כח אין אהבה ויראה, און אַ טוב טעם אין עבודת השי\"ת, איז מען זיך מוסר נפש און מי גיט דאָס אַוועק אויף דעם אַנדערן, אויף פועל זיין הנחת תפילין טהרת המשפחה וכו', און אויף דערוף זאָגט דער רבי<sup data-n=\"1180\">30</sup> וצדקה תרומם אַז דורך דעם פועל טוב נעשים מוחו ולבו זכים אלף פעמים ככה, אַז ער וועט לערנען און עוסק זיין בעבודה שבלב וועט ער בעזה\"י אופטאָן גלייך ווי ער וואָלט יענע צייט אויך געלערנט, און דעם צינור פון מסירת נפש האָט דער רבי פותח געווען און האָט געגעבן זיין הבטחה און ברכה, אַז בכל עת און בכל מקום אַז מיא וועט דאָס טאָן זאָל מען מצליח זיין.\nהערט אידן, דעם מצב העולם ווייסט איר, עס איז ר\"ל ביטער און פינסטער און מכל שכן דער וועלטיקער אידישער יוגענד, איז גאָר ווילד, שבת תפילין טהרה כשר כו' שטייט זייער זייער נידעריק השי\"ת יחוס וירחם, עס איז מיר זייער טוטוויי צו זאָגן, עס איז מיר ביטער צו ריידן, אָבער דער אמת איז אַז אשמים אנחנו, אַלע אידן יראי אלקים און בעלי תורה דאַרפן וויסן אַז זיי האָבן בעזה\"י דעם כח אויף צו העלפן, נעמט זיך אידן פאַר הרבצת התורה, גייט אין די שולן צו די שיעורים, באַ אייך זאָל זיין טייער יעדער פסוק חומש מיט רש\"י וואָס ווערט גילערנט ברבים, און יעדער קאַפיטל תהילים וואָס ווערט געזאָגט ברבים, רעט מיט די יונגעלייט מיט אַ קירוב הלב וועט איר בעזה\"י זייער אַפולע אופטאָן, און דער אור התורה והעבודה וועט מאיר זיין בבית ישראל.",[["1181","31","ברכות לב, ב."],["1182","32","ראה סה\"מ תרפ\"ט שם."],["1180","30","ראה תו\"א בראשית א, ב. ועם הגהות — אוה\"ת שם ח\"ו תתרכו, ב ואילך. סה\"מ תרל\"ח ע' רלב ואילך. ספר השיחות תש\"ג ע' 10."]]],[4301600377,"<h3>י\"ט כסלו<sup data-n=\"1184\">1</sup></h3>\n<b>ליל ב'</b>\nדי צעהן זכותים<sup data-n=\"1185\">2</sup> האָבן אַלטע חסידים גערעכנט, סידור השולחן ערוך, נוסח התפלה, תיקון המקוה, השחזת הסכין, פרסום תורת החסידות, החזקת בני ארץ הקדש ת\"ו, הישיבה במאסר והגאולה, ספריו התקבלו בכל העולם כספרי הגאונים הקדמונים ונכתר בשם רב, עשרה הניגונים ושפועלים התעוררות תשובה ודביקות, וברכתו<sup data-n=\"1186\">3</sup>",[["1184","1","נדפס בלקוטי דיבורים חלק ד תשיח, ב ואילך. בהוצאה זו ניתוספו הערות וציונים מהמו\"ל."],["1185","2","ראה לעיל ע' 175. וראה גם לקוטי שיחות חלק כה ע' 399."],["1186","3","ראה לעיל ס\"ע 179 ואילך."]]],[4301600378,"שבכל מקום אשר חסידים ישתדלו בהחזקת תורה ומצוות יצליחו והאחד יהי' לרבבה.\nנאַרן זיך טאָר מען ניט, עומק רום איז פאַרבונדן מיט עומק תחת, די העכסטע זאַך און די קלענסטע זאַך זיינען גלייך אין דעם ענין אַז גינאַרט טאָר מען ניט זיין, מיא מוז אַלע מאָל וויסן דעם ריכטיקן רעכענונג.\nבעלי עסקים ווייסן אַז עס טרעפט אַ צייט וואָס עס איז ניט קיין צייט אויף מאַכן חשבונות, וואָרעם אַז מיא זאָל יעמולט מאַכן דעם חשבון קאָן ווערן שטאַרק ניט גוט אויפן האַרצן, און מיא קאָן זעך יעמולט פאַרלירן און אַראָפּ פאַלן באיי זיך און עס וועט זעך גאָרניט אופטאָן.\nעס איז געווען אַ חסידישער איד אַ גרויסער סוחר און פאַררעכנט פאַר אַ גרויסן עושר, און האָט געהאַט זייער גרויסע בטוחות, זיין געשעפט איז געווען פּאַדראַדן<sup data-n=\"1187\">4</sup>, און יענע צייט איז גראַדע געווען זייער אַ איינגע, זייענדיק באיי זיך אין צימער אויסהערענדיק אַפולע גישעפטלעכע פאָרשלאגן, וויסנדיק זיינע גרויסע בטוחות האָט ער מחליט געווען מאַכן די געשעפטן, דער ווייל איז אַריין געגאַנגען דער בוכפיהרער און זאָגט אים איך האָב אייך געבראַכט די באַלאַנסן פון די חובות. ענטפערט אים דער סוחר, ביזט אַ שוטה איצטער איז ניט קיין צייט פון קיין באַלאַנסן.\nבעלי עסקים ווייסן אַז עס איז דאָ אַ צייט וואָס מיא דאַרף ניט קוקן קיין סך הכל'ן מיא דאַרף אויסנוצן די בטוחות, מיא דאַרף טאָן און דרייען די רעדל און האָפן אַז השי\"ת וועט געוויס העלפן.\nדאָס איז די ריכטיקע וועג, דאָס איז ניט גינאַרט זיי ווייסן דעם רעכענונג זייער גוט. זיי ווייסן וואו זיי האַלטן, זיי ווייסן וואָס זיי קומט און וואָס זיי זיינען שולדיק, אָבער זיי ווייסן אַז מיא דאַרף האָרעווען מיא דאַרף זייער טייער האַלטן די בטוחות, און מיא דאַרף אויסניצן אויף פאַרבעסרן בעזה\"י דעם גאַנצן מצב זיינעם און די אַלע וואָס זיינען אין זיין סביבה.\nאַ ערלעכער בעל עסק ווייס גאַנץ גוט ווי טייער מיא דאַרף און מיא מוז האַלטן די נאמנות און וויסנדיק אַז דאָס איז ניט אייגענע דאָס איז פרעמדע דאַרף מען זיין אויסגערעכנט אין דער הוצאה, אויף וואָס אויסצוגעבן די הלואה, אויב אויף פאַרבעסרן דעם געשעפט יעמולט איז די הוצאה אַ הכנסה און מיא מאָג פאַרניצן די בטוחות און הלואות, און סוף דבר השי\"ת מצליח לו.\nדי זעלבע זאַך איז אין עבודה, עס איז פאַראַן צייטן וואָס מיא דאַרף ניט קוקן אויף דעם סך הכל, מיא טאָר ניט בלעטערן דעם באַלאַנס, עס קאָן ווערן טונקל אין די אויגן און שווער אויפן האַרצן, מיא דאַרף אויסניצן די בטוחות און די הלואות און מיא דאַרף ווייטער טאָן אין לערנען און דאַוונען ניט אַראָפּ­פאַלן ביי זיך אלא עוד אדרבה מיט מער פרישקייט און לעבעדיקייט און האָפן להשי\"ת אַז ער וועט געוויס העלפן.\nאידן איז אין אַלע צייטן האָבן גרויסע בטוחות כי לא ינום ולא יישן שומר ישראל<sup data-n=\"1188\">5</sup>, וואָס מצד דעם איז דאָך",[["1187","4","קבלנות."],["1188","5","תהלים קכא, ד."]]],[4301600379,"ברוך השם כי לא אלמן ישראל<sup data-n=\"1189\">6</sup>, ניט קוקנדיק אויף דעם וואָס שה פזורה ישראל<sup data-n=\"1190\">7</sup>, מפוזר ומפורד אין אַלע מדינות, השי\"ת יחיש גאולתינו ע\"י גואל צדק בב\"א, איז ברוך השם אומעטום כי לא אלמן ישראל, און ווי דער רבי לערנט אונז צו זעהען די גרויסקייט פון יעדער קליינער זאַך, און בפרט אַז עס איז דאָ טיילווייס אויך גרויסע זאַכן, ב\"ה טויזנטער קינדער כן ירבו יחיו לערנען תורה, תורה אָהן זייטיקע חכמות און זיי וועלן בעזה\"י אַריין טראָגן אַ פרישן לעבעדיקן לעבן אין בית ישראל. אידן האָבן ב\"ה גרויסע בטוחות. און בפרט בעקבות משיחא אַז החשך יכסה ארץ<sup data-n=\"1191\">8</sup> זעהט זיך אָהן ב\"ה אָהן עין הרע די שטאַרקייט פון די בטוחות נאָך מערער, מיא לייט אונז מלמעלה גרויסע הלואות אַז אין אַזא שווערן רוחניותדיקן צושטאַנד איז פאַראַן אידן יחיו וואָס טוען בהרבצת תורה און עס איז פאַראַן וואָס עס שיינט דורך אַ גיפיל צו עבודה און דרכי החסידות, איז דאָס בעווייזט אויף אונזערע בטוחות.\nנאָר די נאמנות האָט מען געדאַרפט אויסניצן אין דער אַרבעט, מיר טאָרן זיך ניט נאַרן אין אונזער מצב הכללי, עס איז אַזוי ווי באַ דעם בעל עסק אַ שווערע צייט, דער עולם ווערט פאַרפּראָסטעט בעלי בתים האַלטן אין אויסרוען זיך, אַמאָל אַז מיא האָט אָפּגיטאָן דעם עסק ומסחר, איז מען געגאַנגען אין בית מדרש לערנען, איצטער אַז מיא טוט אָפּ דעם טאָג איז אַ גרויסער טייל קומט ניט לערנען, דער ענטפער איז אַז מיא האָרעוועט אָפּ דעם טאָג איז נאָכדעם מוז מען אויסרוען.\nבעלי בתים האַלטן אין אויסרוען זיך און די יונגע לייט די ערלעכע, די וואָס זיינען שייך צו עפּעס לערנען, איז אַז די עלטערע רוהען קריגן זיי אויך אַנדערע אַרבעט, און דער סך הכל איז אַז פון אַלץ אין איינעם ווערט געשאַפן אַ קאַלטער אויר. און די קעלט גייט אַריבער פון איין סוג מענשטן צו דעם צווייטן דער איז קאַלט צום לערנען, דער צווייטער ווערט ר\"ל קאַלט צום דאַוונען גאָר כפשוטו, און דאָס פירט צו ניט לייגן תפילין, חילול שבת, עסן וואו עס מאַכט און וואָס עס מאַכט זיך וכו', פון דער קעלט צום לערנען ווערט קאַלט די מקוה, עס ווערט ר\"ל אַלץ קאַלט, עס ווערט אַ קאַלטקייט ר\"ל צו אַלץ, עס איז ניט נוגע צי עס איז יע פאַראַן אַ מקוה אָדער עס איז ניט פאַראַן אַ מקוה, היט מען וואָס מיא דאַרף, היט מען ניט, עס איז ניטאָ קיין צייט צו זאָרגן פאַר אַזעלכע זאַכן, מיא דאַרף זיך אויסרוהען. אָבער וואו איז מסירת נפש, וואו זיינען חסידים, וואו זיינען תמימים, פאַרוואָס וועקט מען ניט, פאַרוואָס טוט מען ניט. דער רבי האָט גיהאַט מסירת נפש בפועל אויפן כלל ישראל, און מיט דעם האָט ער געגעבן אַ כח יעדערן אַז מיא זאָל קאָנען טאָן, און אַז מיא וועט טאָן זאָהל מען מצליח זיין.\nדער רבי האָט געהאַט אזויפיל יסורים ביז ער האָט געמאַכט חסידים, ביז ער האָט געמאַכט בעלי עבודה. עס איז גאָר קיין פלא ניט פאַרוואָס דעם רבין איז דאָס אָהן געקומען אַזוי שווער, מי לנו גדול ווי אברהם אבינו עליו השלום אַ נשמה דאצילות אַ מרכבה צו",[["1189","6","ירמי' נא, ה."],["1190","7","שם נ, יז."],["1191","8","ישעי' ס, ב."]]]]});
